def create_draft(raw=None, threadId=None, to=None, cc=None, bcc=None, subject=None, body=None, includeBodyHtml=None, **_extra):
    import json, os, datetime, base64, hashlib, re
    from email.parser import BytesParser
    from email import policy

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0142000" if __import__("os").path.isdir("./environment_mix/0142000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "create_draft"
    t0 = datetime.datetime.utcnow()

    def _now_iso():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _b64url_encode(b):
        return base64.urlsafe_b64encode(b).decode("ascii").rstrip("=")

    def _gen_id(prefix):
        return f"{prefix}_{_b64url_encode(os.urandom(12))}"

    def _log(op_status, gmail_account_id=None, error=None, related_object_type=None, related_gmail_id=None, request=None, idempotency_key=None, response=None):
        ops = _load("remote_operations.json")
        now = _now_iso()
        row = {
            "id": _gen_id("gop"),
            "gmail_account_id": gmail_account_id,
            "tool_name": endpoint,
            "request": request if isinstance(request, dict) else {},
            "idempotency_key": idempotency_key,
            "related_object_type": related_object_type,
            "related_gmail_id": related_gmail_id,
            "response": response,
            "error": error,
            "attempt_count": 1,
            "status": op_status,
            "scheduled_at": None,
            "started_at": now if op_status in ("running", "succeeded", "failed") else None,
            "finished_at": now if op_status in ("succeeded", "failed", "cancelled") else None,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        _save("remote_operations.json", ops)
        return row

    # Validate booleans/strings/arrays but do not over-restrict content (caller may pass ids/etc.)
    if includeBodyHtml is not None and not isinstance(includeBodyHtml, bool):
        _log("failed", error={"code": "VALIDATION_ERROR", "message": "includeBodyHtml must be a boolean"})
        return _err("VALIDATION_ERROR", "includeBodyHtml must be a boolean", field="includeBodyHtml")

    def _validate_str_list(x, field):
        if x is None:
            return None
        if not isinstance(x, list):
            return _err("VALIDATION_ERROR", f"{field} must be an array of strings", field=field)
        out = []
        for i, v in enumerate(x):
            if not isinstance(v, str) or not v.strip():
                return _err("VALIDATION_ERROR", f"{field} must be an array of strings", field=f"{field}[{i}]")
            out.append(v.strip())
        return out

    to_n = _validate_str_list(to, "to")
    if isinstance(to_n, dict) and "error" in to_n:
        _log("failed", error=to_n["error"] if "error" in to_n else None)
        return to_n
    cc_n = _validate_str_list(cc, "cc")
    if isinstance(cc_n, dict) and "error" in cc_n:
        _log("failed", error=cc_n["error"] if "error" in cc_n else None)
        return cc_n
    bcc_n = _validate_str_list(bcc, "bcc")
    if isinstance(bcc_n, dict) and "error" in bcc_n:
        _log("failed", error=bcc_n["error"] if "error" in bcc_n else None)
        return bcc_n

    if threadId is not None and (not isinstance(threadId, str) or not threadId.strip()):
        _log("failed", error={"code": "VALIDATION_ERROR", "message": "threadId must be a string"})
        return _err("VALIDATION_ERROR", "threadId must be a string", field="threadId")
    if subject is not None and not isinstance(subject, str):
        _log("failed", error={"code": "VALIDATION_ERROR", "message": "subject must be a string"})
        return _err("VALIDATION_ERROR", "subject must be a string", field="subject")
    if body is not None and not isinstance(body, str):
        _log("failed", error={"code": "VALIDATION_ERROR", "message": "body must be a string"})
        return _err("VALIDATION_ERROR", "body must be a string", field="body")
    if raw is not None and (not isinstance(raw, str) or not raw.strip()):
        _log("failed", error={"code": "VALIDATION_ERROR", "message": "raw must be a non-empty string"})
        return _err("VALIDATION_ERROR", "raw must be a non-empty string", field="raw")

    accounts = _load("gmail_accounts.json")
    mail_objects = _load("mail_objects.json")

    # Resolve account that can accept mutations (not revoked/disabled); do NOT require thread existence.
    acct = None
    for a in accounts:
        if isinstance(a, dict) and a.get("status") in ("active", "token_expired") and isinstance(a.get("id"), str):
            acct = a
            break
    if not acct:
        for a in accounts:
            if isinstance(a, dict) and a.get("status") in ("revoked", "disabled") and isinstance(a.get("id"), str):
                _log("failed", gmail_account_id=a.get("id"), error={"code": "UNAUTHORIZED", "message": "Gmail account is revoked/disabled"})
                return _err("UNAUTHORIZED", "Gmail account is revoked/disabled and cannot perform mutations", gmail_account_id=a.get("id"))
        _log("failed", error={"code": "UNAUTHORIZED", "message": "No connected Gmail account available for this operation"})
        return _err("UNAUTHORIZED", "No connected Gmail account available for this operation")

    if acct.get("status") in ("revoked", "disabled"):
        _log("failed", gmail_account_id=acct.get("id"), error={"code": "UNAUTHORIZED", "message": "Gmail account is revoked/disabled"})
        return _err("UNAUTHORIZED", f"Gmail account is {acct.get('status')} and cannot perform mutations", gmail_account_id=acct.get("id"))

    gmail_account_id = acct["id"]
    now = _now_iso()

    # Thread association: DO NOT require it exists in cache; accept and store threadId as thread_gmail_id.
    thread_gid = threadId.strip() if isinstance(threadId, str) and threadId.strip() else None

    # Build/persist raw RFC2822:
    raw_b64url = None
    parsed_headers = {}
    body_text = None
    body_html = None

    def _decode_base64url_relaxed(s):
        # accept urlsafe or standard base64, with or without padding
        s = s.strip()
        s2 = s.replace("-", "+").replace("_", "/")
        pad = (-len(s2)) % 4
        s2 = s2 + ("=" * pad)
        return base64.b64decode(s2.encode("ascii"), validate=False)

    if raw is not None:
        # Validate it's decodable and looks like RFC2822-ish (has headers)
        try:
            raw_bytes = _decode_base64url_relaxed(raw)
        except Exception:
            _log("failed", gmail_account_id=gmail_account_id, error={"code": "VALIDATION_ERROR", "message": "raw is not valid base64/base64url"})
            return _err("VALIDATION_ERROR", "raw is not valid base64/base64url", field="raw")
        try:
            msg = BytesParser(policy=policy.default).parsebytes(raw_bytes)
        except Exception:
            _log("failed", gmail_account_id=gmail_account_id, error={"code": "VALIDATION_ERROR", "message": "raw is not valid RFC 2822"})
            return _err("VALIDATION_ERROR", "raw is not valid RFC 2822", field="raw")
        # require at least one header line; email parser may accept empty. Enforce minimally.
        if not msg.keys():
            _log("failed", gmail_account_id=gmail_account_id, error={"code": "VALIDATION_ERROR", "message": "raw must contain RFC 2822 headers"})
            return _err("VALIDATION_ERROR", "raw must contain RFC 2822 headers", field="raw")

        raw_b64url = _b64url_encode(raw_bytes)

        # lightweight extraction for cache fields
        parsed_headers["subject"] = str(msg.get("Subject")) if msg.get("Subject") is not None else None
        parsed_headers["from"] = str(msg.get("From")) if msg.get("From") is not None else None
        parsed_headers["to"] = str(msg.get("To")) if msg.get("To") is not None else None
        parsed_headers["cc"] = str(msg.get("Cc")) if msg.get("Cc") is not None else None
        # body extraction best-effort
        try:
            if msg.is_multipart():
                # choose first text/plain and text/html parts
                for part in msg.walk():
                    ctype = part.get_content_type()
                    if ctype == "text/plain" and body_text is None:
                        body_text = part.get_content()
                    if ctype == "text/html" and body_html is None:
                        body_html = part.get_content()
            else:
                ctype = msg.get_content_type()
                if ctype == "text/html":
                    body_html = msg.get_content()
                else:
                    body_text = msg.get_content()
        except Exception:
            body_text = None
            body_html = None
    else:
        # Construct a minimal RFC2822; do not strictly validate email formats.
        # Ensure at least one recipient exists (Gmail would reject otherwise, but we keep cache consistent).
        recipients = []
        for lst in (to_n or []):
            recipients.append(lst)
        for lst in (cc_n or []):
            recipients.append(lst)
        for lst in (bcc_n or []):
            recipients.append(lst)
        if not recipients:
            _log("failed", gmail_account_id=gmail_account_id, error={"code": "VALIDATION_ERROR", "message": "At least one recipient is required when raw is not provided"})
            return _err("VALIDATION_ERROR", "At least one recipient is required when raw is not provided", rule="create_draft structured fields require recipients")

        from_addr = acct.get("primary_email") if isinstance(acct.get("primary_email"), str) else "me"
        subj = subject if isinstance(subject, str) else ""
        body_text = body if isinstance(body, str) else ""

        rfc = []
        rfc.append(f"From: {from_addr}")
        if to_n:
            rfc.append("To: " + ", ".join(to_n))
        if cc_n:
            rfc.append("Cc: " + ", ".join(cc_n))
        if bcc_n:
            # Bcc typically not included in headers for delivered message; but for draft raw, Gmail includes it.
            rfc.append("Bcc: " + ", ".join(bcc_n))
        rfc.append("Subject: " + subj)
        rfc.append("MIME-Version: 1.0")
        rfc.append("Content-Type: text/plain; charset=utf-8")
        rfc.append("")
        rfc.append(body_text)
        raw_bytes = ("\r\n".join(rfc)).encode("utf-8")
        raw_b64url = _b64url_encode(raw_bytes)

        parsed_headers["subject"] = subj
        parsed_headers["from"] = from_addr
        parsed_headers["to"] = ", ".join(to_n) if to_n else None
        parsed_headers["cc"] = ", ".join(cc_n) if cc_n else None
        body_html = None  # only generated if caller sent raw with html or other tools; keep None.

    # Create local draft object; enforce unique(gmail_account_id, object_type, gmail_id) by generating unique gmail_id.
    draft_gmail_id = _b64url_encode(os.urandom(9))  # looks like provider-ish opaque id
    existing_keys = set()
    for o in mail_objects:
        if isinstance(o, dict) and o.get("gmail_account_id") == gmail_account_id and o.get("object_type") == "draft":
            existing_keys.add(o.get("gmail_id"))
    while draft_gmail_id in existing_keys:
        draft_gmail_id = _b64url_encode(os.urandom(9))

    draft_row = {
        "id": _gen_id("gmo"),
        "gmail_account_id": gmail_account_id,
        "object_type": "draft",
        "gmail_id": draft_gmail_id,
        "thread_gmail_id": thread_gid,
        "draft_message_gmail_id": None,
        "internal_date_ms": None,
        "snippet": None,
        "subject": parsed_headers.get("subject"),
        "from_addr": parsed_headers.get("from"),
        "to_addrs": to_n if raw is None else (None if parsed_headers.get("to") is None else [parsed_headers.get("to")]),
        "cc_addrs": cc_n if raw is None else (None if parsed_headers.get("cc") is None else [parsed_headers.get("cc")]),
        "bcc_addrs": bcc_n if raw is None else None,
        "body_text": body_text,
        "body_html": body_html,  # will be shaped out below if includeBodyHtml != True
        "raw_rfc2822_base64url": raw_b64url,
        "label_gmail_ids": [],
        "size_estimate": len(raw_bytes) if isinstance(raw_bytes, (bytes, bytearray)) else None,
        "attachment_of_message_gmail_id": None,
        "filename": None,
        "mime_type": None,
        "attachment_data_base64url": None,
        "page_token": None,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }

    # Create remote op with idempotency (based on raw+threadId)
    req_obj = {
        "raw": raw_b64url,
        "threadId": thread_gid,
        "to": to_n,
        "cc": cc_n,
        "bcc": bcc_n,
        "subject": subject,
        "body": body,
        "includeBodyHtml": includeBodyHtml,
    }
    idem_src = json.dumps({"raw": raw_b64url, "threadId": thread_gid}, sort_keys=True).encode("utf-8")
    idempotency_key = "create_draft:" + hashlib.sha256(idem_src).hexdigest()

    ops = _load("remote_operations.json")
    for op in ops:
        if isinstance(op, dict) and op.get("gmail_account_id") == gmail_account_id and op.get("idempotency_key") == idempotency_key:
            # idempotent: do not create another draft; return the existing draft if we can map it, else conflict-like not found?
            # best-effort: find any draft with same raw+thread
            for o in mail_objects:
                if isinstance(o, dict) and o.get("gmail_account_id") == gmail_account_id and o.get("object_type") == "draft":
                    if o.get("raw_rfc2822_base64url") == raw_b64url and o.get("thread_gmail_id") == thread_gid:
                        out = dict(o)
                        if not includeBodyHtml:
                            out["body_html"] = None
                        latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
                        return {"draft": out, "idempotent": True, "latency_ms": latency_ms}
            # If no local draft found, still return deterministic error
            _log("failed", gmail_account_id=gmail_account_id, error={"code": "CONFLICT", "message": "Idempotent operation already recorded but local draft not found"}, idempotency_key=idempotency_key)
            return _err("CONFLICT", "Idempotent operation already recorded but local draft not found", idempotency_key=idempotency_key)

    mail_objects.append(draft_row)
    _save("mail_objects.json", mail_objects)
    _log(
        "queued",
        gmail_account_id=gmail_account_id,
        related_object_type="draft",
        related_gmail_id=draft_row["gmail_id"],
        request=req_obj,
        idempotency_key=idempotency_key,
        response={"draftId": draft_row["gmail_id"]},
    )

    out = dict(draft_row)
    if not includeBodyHtml:
        out["body_html"] = None
    latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
    return {"draft": out, "latency_ms": latency_ms}

def get_draft(id, includeBodyHtml=None, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0142000" if __import__("os").path.isdir("./environment_mix/0142000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    endpoint = "get_draft"
    t0 = datetime.datetime.utcnow()

    def _now_iso():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        import base64
        raw = (int(datetime.datetime.utcnow().timestamp() * 1000)).to_bytes(6, "big") + os.urandom(10)
        return f"{prefix}_{base64.urlsafe_b64encode(raw).decode('ascii').rstrip('=')}"

    def _log(status, gmail_account_id=None, request=None, related_gmail_id=None, error=None, response=None):
        ops = _load("remote_operations.json")
        now = _now_iso()
        ops.append({
            "id": _gen_id("gop"),
            "gmail_account_id": gmail_account_id,
            "tool_name": endpoint,
            "request": request if isinstance(request, dict) else {},
            "idempotency_key": None,
            "related_object_type": "draft",
            "related_gmail_id": related_gmail_id,
            "response": response,
            "error": error,
            "attempt_count": 1,
            "status": status,
            "scheduled_at": None,
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        })
        _save("remote_operations.json", ops)

    try:
        if not isinstance(id, str) or not id.strip():
            _log("failed", None, {"id": id, "includeBodyHtml": includeBodyHtml}, related_gmail_id=None,
                 error={"code": "VALIDATION_ERROR", "message": "id must be a non-empty string"})
            return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")
        if includeBodyHtml is not None and not isinstance(includeBodyHtml, bool):
            _log("failed", None, {"id": id, "includeBodyHtml": includeBodyHtml}, related_gmail_id=id,
                 error={"code": "VALIDATION_ERROR", "message": "includeBodyHtml must be boolean"})
            return _err("VALIDATION_ERROR", "includeBodyHtml must be boolean", field="includeBodyHtml")

        key = id.strip()
        mail_objects = _load("mail_objects.json")
        accounts = _load("gmail_accounts.json")

        draft = None
        for o in mail_objects:
            if not isinstance(o, dict):
                continue
            if o.get("object_type") != "draft":
                continue
            if o.get("id") == key or o.get("gmail_id") == key:
                draft = o
                break

        if not draft or draft.get("status") == "deleted":
            _log("failed", None, {"id": key, "includeBodyHtml": includeBodyHtml}, related_gmail_id=key,
                 error={"code": "NOT_FOUND", "message": "Draft not found", "id": key})
            return _err("NOT_FOUND", "Draft not found", id=key)

        gmail_account_id = draft.get("gmail_account_id")
        acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == gmail_account_id), None)
        if not acct or acct.get("status") not in ("active", "token_expired"):
            _log("failed", gmail_account_id, {"id": key, "includeBodyHtml": includeBodyHtml}, related_gmail_id=draft.get("gmail_id"),
                 error={"code": "UNAUTHORIZED", "message": "No connected Gmail account available for this operation"})
            return _err("UNAUTHORIZED", "No connected Gmail account available for this operation")

        out = dict(draft)
        # Business rule: omit body_html unless includeBodyHtml == true
        if includeBodyHtml is not True:
            out["body_html"] = None

        _log("succeeded", gmail_account_id, {"id": key, "includeBodyHtml": includeBodyHtml}, related_gmail_id=draft.get("gmail_id"),
             response={"id": out.get("gmail_id")})
        return {"draft": out}
    except Exception as e:
        _log("failed", None, {"id": id, "includeBodyHtml": includeBodyHtml}, related_gmail_id=id,
             error={"code": "CONFLICT", "message": "Internal error", "details": str(e)})
        return _err("CONFLICT", "Internal error", details=str(e))

def list_drafts(maxResults=None, q=None, includeSpamTrash=None, includeBodyHtml=None, **_extra):
    import json, os, datetime, uuid, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0142000" if __import__("os").path.isdir("./environment_mix/0142000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _pick_account(accounts):
        for a in accounts:
            if isinstance(a, dict) and a.get("status") in ("active", "token_expired"):
                return a
        return None

    def _log(remote_ops, gmail_account_id, status, request, response=None, error=None):
        now = _now()
        op = {
            "id": "op_" + uuid.uuid4().hex,
            "gmail_account_id": gmail_account_id,
            "tool_name": "list_drafts",
            "request": request,
            "idempotency_key": None,
            "related_object_type": "draft",
            "related_gmail_id": None,
            "response": response,
            "error": error,
            "attempt_count": 1,
            "status": "succeeded" if status == "succeeded" else "failed",
            "scheduled_at": None,
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        }
        remote_ops.append(op)
        return op

    # Validate
    if maxResults is not None:
        if not isinstance(maxResults, (int, float)) or isinstance(maxResults, bool):
            return _err("VALIDATION_ERROR", "maxResults must be a number", field="maxResults")
        if int(maxResults) != maxResults:
            # floats not representing ints are rejected
            if not (isinstance(maxResults, float) and maxResults.is_integer()):
                return _err("VALIDATION_ERROR", "maxResults must be an integer between 1 and 500", field="maxResults")
        mr = int(maxResults)
        if mr < 1 or mr > 500:
            return _err("VALIDATION_ERROR", "maxResults must be between 1 and 500", field="maxResults")
    else:
        mr = 100  # default <= 100

    if q is not None and not isinstance(q, str):
        return _err("VALIDATION_ERROR", "q must be a string", field="q")
    if includeSpamTrash is not None and not isinstance(includeSpamTrash, bool):
        return _err("VALIDATION_ERROR", "includeSpamTrash must be boolean", field="includeSpamTrash")
    if includeBodyHtml is not None and not isinstance(includeBodyHtml, bool):
        return _err("VALIDATION_ERROR", "includeBodyHtml must be boolean", field="includeBodyHtml")

    accounts = _load("gmail_accounts.json")
    mail_objects = _load("mail_objects.json")
    remote_ops = _load("remote_operations.json")

    acct = _pick_account(accounts)
    if not acct:
        return _err("UNAUTHORIZED", "No connected Gmail account available for this operation")
    gmail_account_id = acct.get("id")

    # Filter drafts
    drafts = []
    for mo in mail_objects:
        if mo.get("gmail_account_id") != gmail_account_id:
            continue
        if mo.get("object_type") != "draft":
            continue
        # deleted drafts are not listed
        if mo.get("status") == "deleted":
            continue
        # includeSpamTrash controls whether we include trashed drafts
        if not includeSpamTrash and mo.get("status") == "trashed":
            continue
        drafts.append(mo)

    # Gmail-style q: implement small subset: token search over subject/snippet/from/to/body_text, and status:trashed
    query = (q or "").strip()
    if query:
        tokens = [t for t in re.split(r"\s+", query) if t]
        def _matches(mo):
            hay = " ".join([
                str(mo.get("subject") or ""),
                str(mo.get("snippet") or ""),
                str(mo.get("from_addr") or ""),
                " ".join(mo.get("to_addrs") or [] if isinstance(mo.get("to_addrs"), list) else []),
                " ".join(mo.get("cc_addrs") or [] if isinstance(mo.get("cc_addrs"), list) else []),
                str(mo.get("body_text") or ""),
            ]).lower()
            for tok in tokens:
                tl = tok.lower()
                if tl in ("in:trash", "in:trashed"):
                    if mo.get("status") != "trashed":
                        return False
                    continue
                if tl in ("-in:trash", "-in:trashed"):
                    if mo.get("status") == "trashed":
                        return False
                    continue
                if tl.startswith("subject:"):
                    val = tl.split(":", 1)[1]
                    if val and val not in (mo.get("subject") or "").lower():
                        return False
                    continue
                if tl.startswith("from:"):
                    val = tl.split(":", 1)[1]
                    if val and val not in (mo.get("from_addr") or "").lower():
                        return False
                    continue
                # generic contains
                if tl not in hay:
                    return False
            return True
        drafts = [d for d in drafts if _matches(d)]

    # Sort by internal_date_ms desc, fallback to created_at desc
    def _key(mo):
        return (mo.get("internal_date_ms") or 0, mo.get("created_at") or "")
    drafts.sort(key=_key, reverse=True)

    total = len(drafts)
    page = drafts[:mr]
    has_more = total > mr
    next_token = None
    if has_more:
        # Opaque token: last item's gmail_id + total
        next_token = f"next:{page[-1].get('gmail_id')}:{mr}"

    # Shape response
    out = []
    for d in page:
        shaped = dict(d)
        if not includeBodyHtml:
            shaped["body_html"] = None
        out.append(shaped)

    op = _log(remote_ops, gmail_account_id, "succeeded",
              {"maxResults": maxResults, "q": q, "includeSpamTrash": includeSpamTrash, "includeBodyHtml": includeBodyHtml},
              response={"result_count": len(out), "total": total, "has_more": has_more})
    _save("remote_operations.json", remote_ops)

    return {
        "drafts": out,
        "nextPageToken": next_token,
        "resultSizeEstimate": total,
        "meta": {
            "maxResults": mr,
            "returned": len(out),
            "has_more": has_more,
            "latency_ms": int((time.time() - t0) * 1000)
        }
    }

def delete_label(id, **_extra):
    import json, os, datetime, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0142000" if __import__("os").path.isdir("./environment_mix/0142000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    endpoint = "delete_label"
    t0 = datetime.datetime.utcnow()

    def _now_iso():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        import base64
        raw = (int(datetime.datetime.utcnow().timestamp() * 1000)).to_bytes(6, "big") + os.urandom(10)
        return f"{prefix}_{base64.urlsafe_b64encode(raw).decode('ascii').rstrip('=')}"

    def _append_op(gmail_account_id, status, request, related_gmail_id=None, error=None, response=None, idempotency_key=None):
        ops = _load("remote_operations.json")
        now = _now_iso()
        ops.append({
            "id": _gen_id("gop"),
            "gmail_account_id": gmail_account_id,
            "tool_name": endpoint,
            "request": request if isinstance(request, dict) else {},
            "idempotency_key": idempotency_key,
            "related_object_type": None,
            "related_gmail_id": related_gmail_id,
            "response": response,
            "error": error,
            "attempt_count": 1,
            "status": status,
            "scheduled_at": None,
            "started_at": now if status in ("running", "succeeded", "failed") else None,
            "finished_at": now if status in ("succeeded", "failed", "cancelled") else None,
            "created_at": now,
            "updated_at": now,
        })
        _save("remote_operations.json", ops)

    try:
        if not isinstance(id, str) or not id.strip():
            _append_op(None, "failed", {"id": id}, related_gmail_id=None,
                       error={"code": "VALIDATION_ERROR", "message": "id must be a non-empty string"})
            return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")
        key = id.strip()

        labels = _load("labels.json")
        mail_objects = _load("mail_objects.json")
        accounts = _load("gmail_accounts.json")
        ops = _load("remote_operations.json")

        label = None
        for l in labels:
            if not isinstance(l, dict):
                continue
            # accept either internal label row id or gmail_label_id (common)
            if l.get("id") == key or l.get("gmail_label_id") == key:
                label = l
                break

        if not label:
            _append_op(None, "failed", {"id": key}, related_gmail_id=key,
                       error={"code": "NOT_FOUND", "message": "Label not found", "id": key})
            return _err("NOT_FOUND", "Label not found", id=key)

        gmail_account_id = label.get("gmail_account_id")
        acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == gmail_account_id), None)
        if not acct or acct.get("status") not in ("active", "token_expired"):
            _append_op(gmail_account_id, "failed", {"id": key}, related_gmail_id=label.get("gmail_label_id"),
                       error={"code": "UNAUTHORIZED", "message": "No connected Gmail account available for this operation"})
            return _err("UNAUTHORIZED", "No connected Gmail account available for this operation")
        if acct.get("status") in ("revoked", "disabled"):
            _append_op(gmail_account_id, "failed", {"id": key}, related_gmail_id=label.get("gmail_label_id"),
                       error={"code": "UNAUTHORIZED", "message": "Gmail connection is revoked or disabled"})
            return _err("UNAUTHORIZED", "Gmail connection is revoked or disabled")

        # Cannot delete system labels
        if label.get("label_type") == "system":
            _append_op(gmail_account_id, "failed", {"id": key}, related_gmail_id=label.get("gmail_label_id"),
                       error={"code": "CONFLICT", "message": "System labels cannot be deleted"})
            return _err("CONFLICT", "System labels cannot be deleted", id=key)

        # Idempotent delete
        if label.get("status") == "deleted":
            _append_op(gmail_account_id, "succeeded", {"id": key}, related_gmail_id=label.get("gmail_label_id"),
                       response={"deleted": True, "id": label.get("gmail_label_id")})
            return {"label": dict(label)}

        # Transition active -> deleted only
        if label.get("status") != "active":
            _append_op(gmail_account_id, "failed", {"id": key}, related_gmail_id=label.get("gmail_label_id"),
                       error={"code": "INVALID_TRANSITION", "message": f"Cannot delete label from state '{label.get('status')}'"})
            return _err("INVALID_TRANSITION", f"Cannot delete label from state '{label.get('status')}'", from_status=label.get("status"), to_status="deleted")

        # Idempotency key for the remote operation
        idem = f"delete_label:{gmail_account_id}:{label.get('gmail_label_id')}"
        existing = next((r for r in ops if isinstance(r, dict) and r.get("gmail_account_id") == gmail_account_id and r.get("idempotency_key") == idem), None)
        if not existing:
            _append_op(gmail_account_id, "queued", {"id": key}, related_gmail_id=label.get("gmail_label_id"),
                       response={"accepted": True, "id": label.get("gmail_label_id")}, idempotency_key=idem)

        # Local delete + remove from mail_objects.label_gmail_ids for this account
        deleted_label_gid = label.get("gmail_label_id")
        label["status"] = "deleted"
        label["updated_at"] = _now_iso()

        changed = False
        for mo in mail_objects:
            if not isinstance(mo, dict):
                continue
            if mo.get("gmail_account_id") != gmail_account_id:
                continue
            lg = mo.get("label_gmail_ids")
            if isinstance(lg, list) and deleted_label_gid in lg:
                mo["label_gmail_ids"] = [x for x in lg if x != deleted_label_gid]
                mo["updated_at"] = _now_iso()
                changed = True

        _save("labels.json", labels)
        if changed:
            _save("mail_objects.json", mail_objects)

        return {"label": dict(label)}
    except Exception as e:
        _append_op(None, "failed", {"id": id}, related_gmail_id=id,
                   error={"code": "CONFLICT", "message": "Internal error", "details": str(e)})
        return _err("CONFLICT", "Internal error", details=str(e))

def list_labels(includeDeleted=None, labelTypes=None, maxResults=None, pageToken=None, q=None, sortBy=None, sortOrder=None, **_extra):
    import json, os, datetime, time, base64, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0142000" if __import__("os").path.isdir("./environment_mix/0142000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "list_labels"

    def _now_iso():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, (int, float)):
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _b64url_encode(b):
        return base64.urlsafe_b64encode(b).decode("ascii").rstrip("=")

    def _b64url_decode(s):
        pad = "=" * (-len(s) % 4)
        return base64.urlsafe_b64decode((s + pad).encode("ascii"))

    def _log(status, account_id=None, error=None):
        logs = _load("remote_operations.json")
        req = {
            "includeDeleted": includeDeleted,
            "labelTypes": labelTypes,
            "maxResults": maxResults,
            "pageToken": pageToken,
            "q": q,
            "sortBy": sortBy,
            "sortOrder": sortOrder
        }
        now = _now_iso()
        op_id = "op_" + _b64url_encode(os.urandom(12))
        row = {
            "id": op_id,
            "gmail_account_id": account_id if account_id is not None else "unknown",
            "tool_name": endpoint,
            "request": req,
            "idempotency_key": None,
            "related_object_type": None,
            "related_gmail_id": None,
            "response": None,
            "error": error,
            "attempt_count": 1,
            "status": status,
            "scheduled_at": None,
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now
        }
        logs.append(row)
        _save("remote_operations.json", logs)

    # Validation
    if includeDeleted is not None and not isinstance(includeDeleted, bool):
        _log("failed", error={"code": "VALIDATION_ERROR", "message": "includeDeleted must be boolean"})
        return _err("VALIDATION_ERROR", "includeDeleted must be boolean")
    if labelTypes is not None:
        if not isinstance(labelTypes, list) or any(not isinstance(x, str) for x in labelTypes):
            _log("failed", error={"code": "VALIDATION_ERROR", "message": "labelTypes must be an array of strings"})
            return _err("VALIDATION_ERROR", "labelTypes must be an array of strings")
        allowed = {"system", "user"}
        bad = [x for x in labelTypes if x not in allowed]
        if bad:
            _log("failed", error={"code": "VALIDATION_ERROR", "message": "labelTypes contains invalid values", "invalid": bad})
            return _err("VALIDATION_ERROR", "labelTypes contains invalid values", invalid=bad)
    if maxResults is not None:
        if not isinstance(maxResults, (int, float)) or isinstance(maxResults, bool):
            _log("failed", error={"code": "VALIDATION_ERROR", "message": "maxResults must be a number"})
            return _err("VALIDATION_ERROR", "maxResults must be a number")
        if int(maxResults) != maxResults:
            _log("failed", error={"code": "VALIDATION_ERROR", "message": "maxResults must be an integer"})
            return _err("VALIDATION_ERROR", "maxResults must be an integer")
        maxResults = int(maxResults)
        if maxResults < 1 or maxResults > 500:
            _log("failed", error={"code": "VALIDATION_ERROR", "message": "maxResults must be between 1 and 500"})
            return _err("VALIDATION_ERROR", "maxResults must be between 1 and 500")
    else:
        maxResults = 100  # server default <= 100

    if pageToken is not None and not isinstance(pageToken, str):
        _log("failed", error={"code": "VALIDATION_ERROR", "message": "pageToken must be a string"})
        return _err("VALIDATION_ERROR", "pageToken must be a string")
    if q is not None and not isinstance(q, str):
        _log("failed", error={"code": "VALIDATION_ERROR", "message": "q must be a string"})
        return _err("VALIDATION_ERROR", "q must be a string")
    if sortBy is not None and sortBy not in ("name", "createdAt", "updatedAt"):
        _log("failed", error={"code": "VALIDATION_ERROR", "message": "sortBy must be one of name, createdAt, updatedAt"})
        return _err("VALIDATION_ERROR", "sortBy must be one of name, createdAt, updatedAt")
    if sortOrder is not None and sortOrder not in ("asc", "desc"):
        _log("failed", error={"code": "VALIDATION_ERROR", "message": "sortOrder must be one of asc, desc"})
        return _err("VALIDATION_ERROR", "sortOrder must be one of asc, desc")

    # Resolve ambient authentication: pick an active-ish account (reads allowed even if revoked/disabled)
    accounts = _load("gmail_accounts.json")
    acct = None
    for a in accounts:
        if isinstance(a, dict) and a.get("status") in ("active", "token_expired"):
            acct = a
            break
    if acct is None:
        for a in accounts:
            if isinstance(a, dict) and a.get("status") in ("revoked", "disabled"):
                acct = a
                break
    if acct is None:
        _log("failed", error={"code": "UNAUTHORIZED", "message": "No gmail account context available"})
        return _err("UNAUTHORIZED", "No gmail account context available")

    # Decode page token
    offset = 0
    token_account = acct.get("id")
    if pageToken:
        try:
            raw = _b64url_decode(pageToken)
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or obj.get("v") != 1 or obj.get("tool") != endpoint:
                _log("failed", acct.get("id"), error={"code": "VALIDATION_ERROR", "message": "Invalid pageToken"})
                return _err("VALIDATION_ERROR", "Invalid pageToken")
            if obj.get("gmail_account_id") != acct.get("id"):
                _log("failed", acct.get("id"), error={"code": "VALIDATION_ERROR", "message": "pageToken does not match this account"})
                return _err("VALIDATION_ERROR", "pageToken does not match this account")
            offset = obj.get("offset")
            if not isinstance(offset, int) or offset < 0:
                _log("failed", acct.get("id"), error={"code": "VALIDATION_ERROR", "message": "Invalid pageToken offset"})
                return _err("VALIDATION_ERROR", "Invalid pageToken")
            # TTL: 24h
            iat = obj.get("iat")
            if not isinstance(iat, str) or _parse_dt(iat) is None:
                _log("failed", acct.get("id"), error={"code": "VALIDATION_ERROR", "message": "Invalid pageToken timestamp"})
                return _err("VALIDATION_ERROR", "Invalid pageToken")
            if (datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - _parse_dt(iat)).total_seconds() > 86400:
                _log("failed", acct.get("id"), error={"code": "VALIDATION_ERROR", "message": "pageToken expired"})
                return _err("VALIDATION_ERROR", "pageToken expired")
        except (ValueError, json.JSONDecodeError, UnicodeDecodeError):
            _log("failed", acct.get("id"), error={"code": "VALIDATION_ERROR", "message": "Invalid pageToken"})
            return _err("VALIDATION_ERROR", "Invalid pageToken")

    # Query labels
    labels = _load("labels.json")
    rows = []
    for r in labels:
        if not isinstance(r, dict):
            continue
        if r.get("gmail_account_id") != acct.get("id"):
            continue
        if not includeDeleted and r.get("status") == "deleted":
            continue
        if labelTypes and r.get("label_type") not in set(labelTypes):
            continue
        if q:
            name = r.get("name") or ""
            if not isinstance(name, str) or q.lower() not in name.lower():
                continue
        rows.append(r)

    # Sorting
    sby = sortBy or "name"
    sorder = sortOrder or "asc"
    reverse = (sorder == "desc")

    def _key(r):
        if sby == "name":
            v = r.get("name")
            return ("" if v is None else str(v).lower(), str(r.get("id") or ""))
        if sby == "createdAt":
            d = _parse_dt(r.get("created_at"))
            return (d if d is not None else datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc), str(r.get("id") or ""))
        d = _parse_dt(r.get("updated_at"))
        return (d if d is not None else datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc), str(r.get("id") or ""))

    rows.sort(key=_key, reverse=reverse)

    total = len(rows)
    page = rows[offset:offset + maxResults]
    next_offset = offset + len(page)
    next_token = None
    if next_offset < total:
        payload = {
            "v": 1,
            "tool": endpoint,
            "gmail_account_id": acct.get("id"),
            "offset": next_offset,
            "iat": _now_iso()
        }
        next_token = _b64url_encode(json.dumps(payload, separators=(",", ":")).encode("utf-8"))

    # Shape response: expose vendor-like fields
    def _out(r):
        out = {
            "id": r.get("id"),
            "gmailLabelId": r.get("gmail_label_id"),
            "name": r.get("name"),
            "messageListVisibility": r.get("message_list_visibility"),
            "labelListVisibility": r.get("label_list_visibility"),
            "color": None,
            "type": r.get("label_type"),
            "status": r.get("status"),
            "createdAt": r.get("created_at"),
            "updatedAt": r.get("updated_at")
        }
        if r.get("color_text") is not None or r.get("color_background") is not None:
            out["color"] = {"textColor": r.get("color_text"), "backgroundColor": r.get("color_background")}
        return out

    body = {
        "labels": [_out(r) for r in page],
        "nextPageToken": next_token,
        "resultSizeEstimate": len(page),
        "total": total,
        "hasMore": next_token is not None
    }

    _log("succeeded", acct.get("id"), error=None)
    return body

def patch_label(id, name=None, messageListVisibility=None, labelListVisibility=None, color=None, **_extra):
    import json, os, datetime, time, base64, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0142000" if __import__("os").path.isdir("./environment_mix/0142000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "patch_label"

    def _now_iso():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat()

    def _b64url_encode(b):
        return base64.urlsafe_b64encode(b).decode("ascii").rstrip("=")

    def _log(status, account_id=None, req=None, related=None, error=None, response=None):
        ops = _load("remote_operations.json")
        now = _now_iso()
        op_id = "op_" + _b64url_encode(os.urandom(12))
        row = {
            "id": op_id,
            "gmail_account_id": account_id if account_id is not None else "unknown",
            "tool_name": endpoint,
            "request": req if req is not None else {},
            "idempotency_key": None,
            "related_object_type": None,
            "related_gmail_id": related,
            "response": response,
            "error": error,
            "attempt_count": 1,
            "status": status,
            "scheduled_at": None,
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now
        }
        ops.append(row)
        _save("remote_operations.json", ops)
        return row

    # Validation
    if not isinstance(id, str) or not id.strip():
        _log("failed", error={"code": "VALIDATION_ERROR", "message": "id must be a non-empty string"})
        return _err("VALIDATION_ERROR", "id must be a non-empty string")
    if name is not None and (not isinstance(name, str) or not name.strip()):
        _log("failed", error={"code": "VALIDATION_ERROR", "message": "name must be a non-empty string"})
        return _err("VALIDATION_ERROR", "name must be a non-empty string")
    if messageListVisibility is not None and messageListVisibility not in ("show", "hide"):
        _log("failed", error={"code": "VALIDATION_ERROR", "message": "messageListVisibility must be one of show, hide"})
        return _err("VALIDATION_ERROR", "messageListVisibility must be one of show, hide")
    if labelListVisibility is not None and labelListVisibility not in ("labelShow", "labelShowIfUnread", "labelHide"):
        _log("failed", error={"code": "VALIDATION_ERROR", "message": "labelListVisibility must be one of labelShow, labelShowIfUnread, labelHide"})
        return _err("VALIDATION_ERROR", "labelListVisibility must be one of labelShow, labelShowIfUnread, labelHide")
    if color is not None:
        if not isinstance(color, dict):
            _log("failed", error={"code": "VALIDATION_ERROR", "message": "color must be an object"})
            return _err("VALIDATION_ERROR", "color must be an object")
        if set(color.keys()) != {"textColor", "backgroundColor"}:
            _log("failed", error={"code": "VALIDATION_ERROR", "message": "color must include textColor and backgroundColor only"})
            return _err("VALIDATION_ERROR", "color must include textColor and backgroundColor only")
        if not isinstance(color.get("textColor"), str) or not isinstance(color.get("backgroundColor"), str):
            _log("failed", error={"code": "VALIDATION_ERROR", "message": "color.textColor and color.backgroundColor must be strings"})
            return _err("VALIDATION_ERROR", "color.textColor and color.backgroundColor must be strings")
        hexre = re.compile(r"^#[0-9A-Fa-f]{6}$")
        if not hexre.match(color["textColor"]):
            _log("failed", error={"code": "VALIDATION_ERROR", "message": "color.textColor must be a hex string like #RRGGBB"})
            return _err("VALIDATION_ERROR", "color.textColor must be a hex string like #RRGGBB")
        if not hexre.match(color["backgroundColor"]):
            _log("failed", error={"code": "VALIDATION_ERROR", "message": "color.backgroundColor must be a hex string like #RRGGBB"})
            return _err("VALIDATION_ERROR", "color.backgroundColor must be a hex string like #RRGGBB")

    # Resolve ambient auth: must find an account that can mutate (active/token_expired allowed; revoked/disabled forbidden)
    accounts = _load("gmail_accounts.json")
    acct = None
    for a in accounts:
        if isinstance(a, dict) and a.get("status") in ("active", "token_expired"):
            acct = a
            break
    if acct is None:
        _log("failed", error={"code": "UNAUTHORIZED", "message": "No connected gmail account available"})
        return _err("UNAUTHORIZED", "No connected gmail account available")
    if acct.get("status") in ("revoked", "disabled"):
        _log("failed", acct.get("id"), error={"code": "UNAUTHORIZED", "message": "Gmail account is revoked/disabled"})
        return _err("UNAUTHORIZED", "Gmail account is revoked/disabled")

    req = {"id": id, "name": name, "messageListVisibility": messageListVisibility, "labelListVisibility": labelListVisibility, "color": color}

    labels = _load("labels.json")
    target = None
    for r in labels:
        if isinstance(r, dict) and r.get("id") == id and r.get("gmail_account_id") == acct.get("id"):
            target = r
            break
    if target is None:
        _log("failed", acct.get("id"), req=req, related=id, error={"code": "NOT_FOUND", "message": "Label not found"})
        return _err("NOT_FOUND", "Label not found")

    # Cannot modify system label
    if target.get("label_type") == "system":
        _log("failed", acct.get("id"), req=req, related=target.get("gmail_label_id"), error={"code": "CONFLICT", "message": "System labels cannot be modified"})
        return _err("CONFLICT", "System labels cannot be modified")

    # Apply patch & enforce uniqueness among active user labels (case-insensitive)
    new_name = target.get("name")
    if name is not None:
        new_name = name

    if new_name is not None:
        norm = new_name.strip().lower()
        for r in labels:
            if not isinstance(r, dict):
                continue
            if r.get("gmail_account_id") != acct.get("id"):
                continue
            if r.get("id") == target.get("id"):
                continue
            if r.get("label_type") == "user" and r.get("status") == "active":
                rn = r.get("name")
                if isinstance(rn, str) and rn.strip().lower() == norm:
                    _log("failed", acct.get("id"), req=req, related=target.get("gmail_label_id"), error={"code": "CONFLICT", "message": "A user label with this name already exists"})
                    return _err("CONFLICT", "A user label with this name already exists")

    # Record remote operation (queued->running->succeeded), then mutate label cache
    op = _log("queued", acct.get("id"), req=req, related=target.get("gmail_label_id"), error=None, response=None)
    # transition to running
    ops = _load("remote_operations.json")
    for o in ops:
        if isinstance(o, dict) and o.get("id") == op["id"]:
            o["status"] = "running"
            o["updated_at"] = _now_iso()
            o["started_at"] = o.get("started_at") or _now_iso()
            break
    _save("remote_operations.json", ops)

    # Mutate
    changed = False
    if name is not None and target.get("name") != name:
        target["name"] = name
        changed = True
    if messageListVisibility is not None and target.get("message_list_visibility") != messageListVisibility:
        target["message_list_visibility"] = messageListVisibility
        changed = True
    if labelListVisibility is not None and target.get("label_list_visibility") != labelListVisibility:
        target["label_list_visibility"] = labelListVisibility
        changed = True
    if color is not None:
        if target.get("color_text") != color["textColor"]:
            target["color_text"] = color["textColor"]
            changed = True
        if target.get("color_background") != color["backgroundColor"]:
            target["color_background"] = color["backgroundColor"]
            changed = True

    if not changed:
        # Still record succeeded operation (patch no-op is acceptable if row matched and validated)
        pass

    target["updated_at"] = _now_iso()
    _save("labels.json", labels)

    # Complete op
    ops = _load("remote_operations.json")
    for o in ops:
        if isinstance(o, dict) and o.get("id") == op["id"]:
            o["status"] = "succeeded"
            o["finished_at"] = _now_iso()
            o["updated_at"] = _now_iso()
            o["response"] = {"patchedLabelId": target.get("gmail_label_id")}
            o["error"] = None
            break
    _save("remote_operations.json", ops)

    out = {
        "id": target.get("id"),
        "gmailLabelId": target.get("gmail_label_id"),
        "name": target.get("name"),
        "messageListVisibility": target.get("message_list_visibility"),
        "labelListVisibility": target.get("label_list_visibility"),
        "color": None,
        "type": target.get("label_type"),
        "status": target.get("status"),
        "createdAt": target.get("created_at"),
        "updatedAt": target.get("updated_at")
    }
    if target.get("color_text") is not None or target.get("color_background") is not None:
        out["color"] = {"textColor": target.get("color_text"), "backgroundColor": target.get("color_background")}
    return out

def update_label(id, name=None, messageListVisibility=None, labelListVisibility=None, color=None, **_extra):
    import json, os, datetime, time, base64, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0142000" if __import__("os").path.isdir("./environment_mix/0142000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "update_label"

    def _now_iso():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat()

    def _b64url_encode(b):
        return base64.urlsafe_b64encode(b).decode("ascii").rstrip("=")

    def _log(status, account_id=None, req=None, related=None, error=None, response=None):
        ops = _load("remote_operations.json")
        now = _now_iso()
        op_id = "op_" + _b64url_encode(os.urandom(12))
        row = {
            "id": op_id,
            "gmail_account_id": account_id if account_id is not None else "unknown",
            "tool_name": endpoint,
            "request": req if req is not None else {},
            "idempotency_key": None,
            "related_object_type": None,
            "related_gmail_id": related,
            "response": response,
            "error": error,
            "attempt_count": 1,
            "status": status,
            "scheduled_at": None,
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now
        }
        ops.append(row)
        _save("remote_operations.json", ops)
        return row

    # Validation
    if not isinstance(id, str) or not id.strip():
        _log("failed", error={"code": "VALIDATION_ERROR", "message": "id must be a non-empty string"})
        return _err("VALIDATION_ERROR", "id must be a non-empty string")
    if name is not None and (not isinstance(name, str) or not name.strip()):
        _log("failed", error={"code": "VALIDATION_ERROR", "message": "name must be a non-empty string"})
        return _err("VALIDATION_ERROR", "name must be a non-empty string")
    if messageListVisibility is not None and messageListVisibility not in ("show", "hide"):
        _log("failed", error={"code": "VALIDATION_ERROR", "message": "messageListVisibility must be one of show, hide"})
        return _err("VALIDATION_ERROR", "messageListVisibility must be one of show, hide")
    if labelListVisibility is not None and labelListVisibility not in ("labelShow", "labelShowIfUnread", "labelHide"):
        _log("failed", error={"code": "VALIDATION_ERROR", "message": "labelListVisibility must be one of labelShow, labelShowIfUnread, labelHide"})
        return _err("VALIDATION_ERROR", "labelListVisibility must be one of labelShow, labelShowIfUnread, labelHide")
    if color is not None:
        if not isinstance(color, dict):
            _log("failed", error={"code": "VALIDATION_ERROR", "message": "color must be an object"})
            return _err("VALIDATION_ERROR", "color must be an object")
        # update_label requires both fields if color provided
        if "textColor" not in color or "backgroundColor" not in color or len(color.keys()) != 2:
            _log("failed", error={"code": "VALIDATION_ERROR", "message": "color must include both textColor and backgroundColor"})
            return _err("VALIDATION_ERROR", "color must include both textColor and backgroundColor")
        if not isinstance(color.get("textColor"), str) or not isinstance(color.get("backgroundColor"), str):
            _log("failed", error={"code": "VALIDATION_ERROR", "message": "color.textColor and color.backgroundColor must be strings"})
            return _err("VALIDATION_ERROR", "color.textColor and color.backgroundColor must be strings")
        hexre = re.compile(r"^#[0-9A-Fa-f]{6}$")
        if not hexre.match(color["textColor"]):
            _log("failed", error={"code": "VALIDATION_ERROR", "message": "color.textColor must be a hex string like #RRGGBB"})
            return _err("VALIDATION_ERROR", "color.textColor must be a hex string like #RRGGBB")
        if not hexre.match(color["backgroundColor"]):
            _log("failed", error={"code": "VALIDATION_ERROR", "message": "color.backgroundColor must be a hex string like #RRGGBB"})
            return _err("VALIDATION_ERROR", "color.backgroundColor must be a hex string like #RRGGBB")

    # Resolve ambient auth (must be connected for mutation)
    accounts = _load("gmail_accounts.json")
    acct = None
    for a in accounts:
        if isinstance(a, dict) and a.get("status") in ("active", "token_expired"):
            acct = a
            break
    if acct is None:
        _log("failed", error={"code": "UNAUTHORIZED", "message": "No connected gmail account available"})
        return _err("UNAUTHORIZED", "No connected gmail account available")
    if acct.get("status") in ("revoked", "disabled"):
        _log("failed", acct.get("id"), error={"code": "UNAUTHORIZED", "message": "Gmail account is revoked/disabled"})
        return _err("UNAUTHORIZED", "Gmail account is revoked/disabled")

    req = {"id": id, "name": name, "messageListVisibility": messageListVisibility, "labelListVisibility": labelListVisibility, "color": color}

    labels = _load("labels.json")
    target = None
    for r in labels:
        if isinstance(r, dict) and r.get("id") == id and r.get("gmail_account_id") == acct.get("id"):
            target = r
            break
    if target is None:
        _log("failed", acct.get("id"), req=req, related=id, error={"code": "NOT_FOUND", "message": "Label not found"})
        return _err("NOT_FOUND", "Label not found")

    if target.get("label_type") == "system":
        _log("failed", acct.get("id"), req=req, related=target.get("gmail_label_id"), error={"code": "CONFLICT", "message": "System labels cannot be modified"})
        return _err("CONFLICT", "System labels cannot be modified")

    # Uniqueness among active user labels (case-insensitive) when changing name
    if name is not None:
        norm = name.strip().lower()
        for r in labels:
            if not isinstance(r, dict):
                continue
            if r.get("gmail_account_id") != acct.get("id"):
                continue
            if r.get("id") == target.get("id"):
                continue
            if r.get("label_type") == "user" and r.get("status") == "active":
                rn = r.get("name")
                if isinstance(rn, str) and rn.strip().lower() == norm:
                    _log("failed", acct.get("id"), req=req, related=target.get("gmail_label_id"), error={"code": "CONFLICT", "message": "A user label with this name already exists"})
                    return _err("CONFLICT", "A user label with this name already exists")

    # Record remote operation (queued->running->succeeded), then update cache
    op = _log("queued", acct.get("id"), req=req, related=target.get("gmail_label_id"))
    ops = _load("remote_operations.json")
    for o in ops:
        if isinstance(o, dict) and o.get("id") == op["id"]:
            o["status"] = "running"
            o["updated_at"] = _now_iso()
            o["started_at"] = o.get("started_at") or _now_iso()
            break
    _save("remote_operations.json", ops)

    # Apply updates (only provided fields are updated; it's still "update" tool but schema allows optional)
    changed = False
    if name is not None and target.get("name") != name:
        target["name"] = name
        changed = True
    if messageListVisibility is not None and target.get("message_list_visibility") != messageListVisibility:
        target["message_list_visibility"] = messageListVisibility
        changed = True
    if labelListVisibility is not None and target.get("label_list_visibility") != labelListVisibility:
        target["label_list_visibility"] = labelListVisibility
        changed = True
    if color is not None:
        if target.get("color_text") != color["textColor"]:
            target["color_text"] = color["textColor"]
            changed = True
        if target.get("color_background") != color["backgroundColor"]:
            target["color_background"] = color["backgroundColor"]
            changed = True

    # Update timestamps even if no change (consistent with update semantics)
    target["updated_at"] = _now_iso()
    _save("labels.json", labels)

    ops = _load("remote_operations.json")
    for o in ops:
        if isinstance(o, dict) and o.get("id") == op["id"]:
            o["status"] = "succeeded"
            o["finished_at"] = _now_iso()
            o["updated_at"] = _now_iso()
            o["response"] = {"updatedLabelId": target.get("gmail_label_id")}
            o["error"] = None
            break
    _save("remote_operations.json", ops)

    out = {
        "id": target.get("id"),
        "gmailLabelId": target.get("gmail_label_id"),
        "name": target.get("name"),
        "messageListVisibility": target.get("message_list_visibility"),
        "labelListVisibility": target.get("label_list_visibility"),
        "color": None,
        "type": target.get("label_type"),
        "status": target.get("status"),
        "createdAt": target.get("created_at"),
        "updatedAt": target.get("updated_at")
    }
    if target.get("color_text") is not None or target.get("color_background") is not None:
        out["color"] = {"textColor": target.get("color_text"), "backgroundColor": target.get("color_background")}
    return out

def batch_delete_messages(ids, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0142000" if __import__("os").path.isdir("./environment_mix/0142000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    endpoint = "batch_delete_messages"

    def _now_iso():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        import base64
        raw = (int(datetime.datetime.utcnow().timestamp() * 1000)).to_bytes(6, "big") + os.urandom(10)
        return f"{prefix}_{base64.urlsafe_b64encode(raw).decode('ascii').rstrip('=')}"

    def _append_op(gmail_account_id, status, request, idempotency_key=None, error=None, response=None):
        ops = _load("remote_operations.json")
        now = _now_iso()
        ops.append({
            "id": _gen_id("gop"),
            "gmail_account_id": gmail_account_id,
            "tool_name": endpoint,
            "request": request if isinstance(request, dict) else {},
            "idempotency_key": idempotency_key,
            "related_object_type": "message",
            "related_gmail_id": None,
            "response": response,
            "error": error,
            "attempt_count": 1,
            "status": status,
            "scheduled_at": None,
            "started_at": now if status in ("running", "succeeded", "failed") else None,
            "finished_at": now if status in ("succeeded", "failed", "cancelled") else None,
            "created_at": now,
            "updated_at": now,
        })
        _save("remote_operations.json", ops)

    try:
        if not isinstance(ids, list) or not ids:
            _append_op(None, "failed", {"ids": ids}, error={"code": "VALIDATION_ERROR", "message": "ids must be a non-empty array of strings"})
            return _err("VALIDATION_ERROR", "ids must be a non-empty array of strings", field="ids")
        norm = []
        for i, v in enumerate(ids):
            if not isinstance(v, str) or not v.strip():
                _append_op(None, "failed", {"ids": ids}, error={"code": "VALIDATION_ERROR", "message": "ids must be a non-empty array of strings"})
                return _err("VALIDATION_ERROR", "ids must be a non-empty array of strings", field=f"ids[{i}]")
            norm.append(v.strip())

        accounts = _load("gmail_accounts.json")
        mail_objects = _load("mail_objects.json")

        # Find all message objects referenced; accept ids as either internal id or gmail_id
        found = []
        missing = []
        for key in norm:
            mo = next((o for o in mail_objects if isinstance(o, dict) and o.get("object_type") == "message" and (o.get("id") == key or o.get("gmail_id") == key)), None)
            if not mo:
                missing.append(key)
            else:
                found.append(mo)

        if missing:
            _append_op(None, "failed", {"ids": norm}, error={"code": "NOT_FOUND", "message": "One or more messages not found", "missing": missing})
            return _err("NOT_FOUND", "One or more messages not found", missing=missing)

        # Must all belong to same gmail_account (tool executes in one account context)
        acct_ids = {o.get("gmail_account_id") for o in found}
        if len(acct_ids) != 1 or None in acct_ids:
            _append_op(None, "failed", {"ids": norm}, error={"code": "VALIDATION_ERROR", "message": "All ids must belong to the same Gmail account"})
            return _err("VALIDATION_ERROR", "All ids must belong to the same Gmail account")
        gmail_account_id = next(iter(acct_ids))
        acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == gmail_account_id), None)
        if not acct or acct.get("status") not in ("active", "token_expired"):
            _append_op(gmail_account_id, "failed", {"ids": norm}, error={"code": "UNAUTHORIZED", "message": "No connected Gmail account available for this operation"})
            return _err("UNAUTHORIZED", "No connected Gmail account available for this operation")
        if acct.get("status") in ("revoked", "disabled"):
            _append_op(gmail_account_id, "failed", {"ids": norm}, error={"code": "UNAUTHORIZED", "message": "Gmail connection is revoked or disabled"})
            return _err("UNAUTHORIZED", "Gmail connection is revoked or disabled")

        # Mutate: set status='deleted' (idempotent if already deleted)
        now = _now_iso()
        changed = 0
        for mo in found:
            if mo.get("status") != "deleted":
                # lifecycle allows active/trashed -> deleted (and sent/cancelled -> deleted for messages likely not used)
                mo["status"] = "deleted"
                mo["updated_at"] = now
                changed += 1
        _save("mail_objects.json", mail_objects)

        # Create one remote op for the batch
        idem = f"batch_delete_messages:{gmail_account_id}:" + ",".join(sorted([o.get("gmail_id") or o.get("id") for o in found]))
        _append_op(gmail_account_id, "queued", {"ids": norm}, idempotency_key=idem, response={"accepted": True, "deleted_count": len(found)})

        return {"deleted": True, "count": len(found)}
    except Exception as e:
        _append_op(None, "failed", {"ids": ids}, error={"code": "CONFLICT", "message": "Internal error", "details": str(e)})
        return _err("CONFLICT", "Internal error", details=str(e))

def batch_modify_messages(ids, addLabelIds=None, removeLabelIds=None, **_extra):
