            "error": error,
            "attempt_count": 1,
            "status": status,
            "scheduled_at": None,
            "started_at": now if status in ("running", "succeeded", "failed") else None,
            "finished_at": now if status in ("succeeded", "failed", "cancelled") else None,
            "created_at": now,
            "updated_at": now,
        })
        _save("remote_operations.json", ops)

    try:
        if not isinstance(ids, list) or not ids:
            _append_op(None, "failed", {"ids": ids, "addLabelIds": addLabelIds, "removeLabelIds": removeLabelIds},
                       error={"code": "VALIDATION_ERROR", "message": "ids must be a non-empty array of strings"})
            return _err("VALIDATION_ERROR", "ids must be a non-empty array of strings", field="ids")
        norm_ids = []
        for i, v in enumerate(ids):
            if not isinstance(v, str) or not v.strip():
                _append_op(None, "failed", {"ids": ids, "addLabelIds": addLabelIds, "removeLabelIds": removeLabelIds},
                           error={"code": "VALIDATION_ERROR", "message": "ids must be a non-empty array of strings"})
                return _err("VALIDATION_ERROR", "ids must be a non-empty array of strings", field=f"ids[{i}]")
            norm_ids.append(v.strip())

        if addLabelIds is None:
            addLabelIds = []
        if removeLabelIds is None:
            removeLabelIds = []
        if not isinstance(addLabelIds, list) or any((not isinstance(x, str) or not x.strip()) for x in addLabelIds):
            _append_op(None, "failed", {"ids": norm_ids, "addLabelIds": addLabelIds, "removeLabelIds": removeLabelIds},
                       error={"code": "VALIDATION_ERROR", "message": "addLabelIds must be an array of strings"})
            return _err("VALIDATION_ERROR", "addLabelIds must be an array of strings", field="addLabelIds")
        if not isinstance(removeLabelIds, list) or any((not isinstance(x, str) or not x.strip()) for x in removeLabelIds):
            _append_op(None, "failed", {"ids": norm_ids, "addLabelIds": addLabelIds, "removeLabelIds": removeLabelIds},
                       error={"code": "VALIDATION_ERROR", "message": "removeLabelIds must be an array of strings"})
            return _err("VALIDATION_ERROR", "removeLabelIds must be an array of strings", field="removeLabelIds")

        addLabelIds = [x.strip() for x in addLabelIds]
        removeLabelIds = [x.strip() for x in removeLabelIds]

        accounts = _load("gmail_accounts.json")
        labels = _load("labels.json")
        mail_objects = _load("mail_objects.json")

        # Resolve messages; ids can be internal id or gmail_id
        msgs = []
        missing = []
        for key in norm_ids:
            mo = next((o for o in mail_objects if isinstance(o, dict) and o.get("object_type") == "message" and (o.get("id") == key or o.get("gmail_id") == key)), None)
            if not mo:
                missing.append(key)
            else:
                msgs.append(mo)
        if missing:
            _append_op(None, "failed", {"ids": norm_ids, "addLabelIds": addLabelIds, "removeLabelIds": removeLabelIds},
                       error={"code": "NOT_FOUND", "message": "One or more messages not found", "missing": missing})
            return _err("NOT_FOUND", "One or more messages not found", missing=missing)

        acct_ids = {m.get("gmail_account_id") for m in msgs}
        if len(acct_ids) != 1 or None in acct_ids:
            _append_op(None, "failed", {"ids": norm_ids, "addLabelIds": addLabelIds, "removeLabelIds": removeLabelIds},
                       error={"code": "VALIDATION_ERROR", "message": "All ids must belong to the same Gmail account"})
            return _err("VALIDATION_ERROR", "All ids must belong to the same Gmail account")
        gmail_account_id = next(iter(acct_ids))

        acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == gmail_account_id), None)
        if not acct or acct.get("status") not in ("active", "token_expired"):
            _append_op(gmail_account_id, "failed", {"ids": norm_ids, "addLabelIds": addLabelIds, "removeLabelIds": removeLabelIds},
                       error={"code": "UNAUTHORIZED", "message": "No connected Gmail account available for this operation"})
