                       error={"code": "UNAUTHORIZED", "message": "Gmail connection is revoked or disabled"})
            return _err("UNAUTHORIZED", "Gmail connection is revoked or disabled")

        # Business rule: validate label ids exist and are active for the same account.
        # Accept either internal label row id or gmail_label_id in the request.
        active_labels = [l for l in labels if isinstance(l, dict) and l.get("gmail_account_id") == gmail_account_id and l.get("status") == "active"]
        by_internal = {l.get("id"): l for l in active_labels if l.get("id")}
        by_gmail = {l.get("gmail_label_id"): l for l in active_labels if l.get("gmail_label_id")}

        def _resolve_label_id(x):
            if x in by_internal:
                return by_internal[x].get("gmail_label_id")
            if x in by_gmail:
                return x
            return None

        resolved_add = []
        for x in addLabelIds:
            gid = _resolve_label_id(x)
            if not gid:
                _append_op(gmail_account_id, "failed", {"ids": norm_ids, "addLabelIds": addLabelIds, "removeLabelIds": removeLabelIds},
                           error={"code": "NOT_FOUND", "message": f"Label id not found or not active: {x}", "id": x})
                return _err("NOT_FOUND", f"Label id not found or not active: {x}", id=x)
            resolved_add.append(gid)

        resolved_remove = []
        for x in removeLabelIds:
            gid = _resolve_label_id(x)
            if not gid:
                _append_op(gmail_account_id, "failed", {"ids": norm_ids, "addLabelIds": addLabelIds, "removeLabelIds": removeLabelIds},
                           error={"code": "NOT_FOUND", "message": f"Label id not found or not active: {x}", "id": x})
                return _err("NOT_FOUND", f"Label id not found or not active: {x}", id=x)
            resolved_remove.append(gid)

        # Apply modifications locally (idempotent)
        now = _now_iso()
        changed = 0
        for m in msgs:
            lg = m.get("label_gmail_ids")
            if not isinstance(lg, list):
                lg = []
            before = list(lg)
            # remove then add
            if resolved_remove:
                lg = [x for x in lg if x not in set(resolved_remove)]
            for x in resolved_add:
                if x not in lg:
                    lg.append(x)
            if lg != before:
                m["label_gmail_ids"] = lg
                m["updated_at"] = now
                changed += 1
        _save("mail_objects.json", mail_objects)

        idem = f"batch_modify_messages:{gmail_account_id}:" + ",".join(sorted([m.get("gmail_id") or m.get("id") for m in msgs])) + f":add={','.join(sorted(resolved_add))}:rm={','.join(sorted(resolved_remove))}"
        _append_op(gmail_account_id, "queued", {"ids": norm_ids, "addLabelIds": addLabelIds, "removeLabelIds": removeLabelIds},
                   idempotency_key=idem, response={"accepted": True, "modified_count": len(msgs)})

        return {"modified": True, "count": len(msgs), "changed": changed}
    except Exception as e:
        _append_op(None, "failed", {"ids": ids, "addLabelIds": addLabelIds, "removeLabelIds": removeLabelIds},
                   error={"code": "CONFLICT", "message": "Internal error", "details": str(e)})
        return _err("CONFLICT", "Internal error", details=str(e))

def delete_message(id, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0142000" if __import__("os").path.isdir("./environment_mix/0142000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    endpoint = "delete_message"

    def _now_iso():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        import base64
        raw = (int(datetime.datetime.utcnow().timestamp() * 1000)).to_bytes(6, "big") + os.urandom(10)
        return f"{prefix}_{base64.urlsafe_b64encode(raw).decode('ascii').rstrip('=')}"

    def _append_op(gmail_account_id, status, request, related_gmail_id=None, idempotency_key=None, error=None, response=None):
        ops = _load("remote_operations.json")
        now = _now_iso()
        ops.append({
            "id": _gen_id("gop"),
            "gmail_account_id": gmail_account_id,
            "tool_name": endpoint,
            "request": request if isinstance(request, dict) else {},
            "idempotency_key": idempotency_key,
            "related_object_type": "message",
            "related_gmail_id": related_gmail_id,
            "response": response,
            "error": error,
            "attempt_count": 1,
            "status": status,
            "scheduled_at": None,
            "started_at": now if status in ("running", "succeeded", "failed") else None,
            "finished_at": now if status in ("succeeded", "failed", "cancelled") else None,
            "created_at": now,
            "updated_at": now,
        })
        _save("remote_operations.json", ops)

    try:
        if not isinstance(id, str) or not id.strip():
            _append_op(None, "failed", {"id": id}, error={"code": "VALIDATION_ERROR", "message": "id must be a non-empty string"})
            return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")
        key = id.strip()

        accounts = _load("gmail_accounts.json")
        mail_objects = _load("mail_objects.json")
        ops = _load("remote_operations.json")

        msg = next((o for o in mail_objects if isinstance(o, dict) and o.get("object_type") == "message" and (o.get("id") == key or o.get("gmail_id") == key)), None)
        if not msg:
            _append_op(None, "failed", {"id": key}, related_gmail_id=key,
                       error={"code": "NOT_FOUND", "message": "Message not found", "id": key})
            return _err("NOT_FOUND", "Message not found", id=key)

        gmail_account_id = msg.get("gmail_account_id")
        acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == gmail_account_id), None)
        if not acct or acct.get("status") not in ("active", "token_expired"):
            _append_op(gmail_account_id, "failed", {"id": key}, related_gmail_id=msg.get("gmail_id"),
                       error={"code": "UNAUTHORIZED", "message": "No connected Gmail account available for this operation"})
            return _err("UNAUTHORIZED", "No connected Gmail account available for this operation")
        if acct.get("status") in ("revoked", "disabled"):
            _append_op(gmail_account_id, "failed", {"id": key}, related_gmail_id=msg.get("gmail_id"),
                       error={"code": "UNAUTHORIZED", "message": "Gmail connection is revoked or disabled"})
            return _err("UNAUTHORIZED", "Gmail connection is revoked or disabled")

        # Idempotent local delete
        if msg.get("status") != "deleted":
            msg["status"] = "deleted"
            msg["updated_at"] = _now_iso()
            _save("mail_objects.json", mail_objects)

        idem = f"delete_message:{gmail_account_id}:{msg.get('gmail_id')}"
        existing = next((r for r in ops if isinstance(r, dict) and r.get("gmail_account_id") == gmail_account_id and r.get("idempotency_key") == idem), None)
        if not existing:
            _append_op(gmail_account_id, "queued", {"id": key}, related_gmail_id=msg.get("gmail_id"),
                       idempotency_key=idem, response={"accepted": True, "id": msg.get("gmail_id")})

        return {"deleted": True, "id": msg.get("gmail_id")}
    except Exception as e:
        _append_op(None, "failed", {"id": id}, related_gmail_id=id,
                   error={"code": "CONFLICT", "message": "Internal error", "details": str(e)})
        return _err("CONFLICT", "Internal error", details=str(e))

