def list_messages(maxResults=None, pageToken=None, q=None, labelIds=None, includeSpamTrash=None, includeBodyHtml=None, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0142000" if __import__("os").path.isdir("./environment_mix/0142000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _record_read_op(gmail_account_id, request, status, response=None, error=None):
        ops = _load("remote_operations.json")
        op = {
            "id": "op_" + uuid.uuid4().hex,
            "gmail_account_id": gmail_account_id,
            "tool_name": "list_messages",
            "request": request,
            "idempotency_key": None,
            "related_object_type": "message",
            "related_gmail_id": None,
            "response": response,
            "error": error,
            "attempt_count": 0,
            "status": status,
            "scheduled_at": None,
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(op)
        _save("remote_operations.json", ops)

    # Validate
    if maxResults is not None:
        if not isinstance(maxResults, (int, float)) or isinstance(maxResults, bool):
            return _err("VALIDATION_ERROR", "`maxResults` must be a number when provided")
        if int(maxResults) != maxResults:
            # allow 10.0? treat as int-like
            if not (isinstance(maxResults, float) and maxResults.is_integer()):
                return _err("VALIDATION_ERROR", "`maxResults` must be an integer between 1 and 500")
        maxResults = int(maxResults)
        if maxResults < 1 or maxResults > 500:
            return _err("VALIDATION_ERROR", "`maxResults` must be between 1 and 500")
    else:
        maxResults = 100  # server default <= 100

    if pageToken is not None and (not isinstance(pageToken, str)):
        return _err("VALIDATION_ERROR", "`pageToken` must be a string when provided")
    if q is not None and (not isinstance(q, str)):
        return _err("VALIDATION_ERROR", "`q` must be a string when provided")
    if labelIds is not None:
        if not isinstance(labelIds, list) or any(not isinstance(x, str) or not x for x in labelIds):
            return _err("VALIDATION_ERROR", "`labelIds` must be an array of strings when provided")
    if includeSpamTrash is not None and not isinstance(includeSpamTrash, bool):
        return _err("VALIDATION_ERROR", "`includeSpamTrash` must be a boolean when provided")
    if includeBodyHtml is not None and not isinstance(includeBodyHtml, bool):
        return _err("VALIDATION_ERROR", "`includeBodyHtml` must be a boolean when provided")

    accts = _load("gmail_accounts.json")
    readable_status = {"active", "token_expired"}
    acct = None
    for a in accts:
        if a.get("status") in readable_status:
            acct = a
            break
    if acct is None:
        return _err("UNAUTHORIZED", "No connected Gmail account available for this operation")

    # Validate labelIds exist/active (rule says modify tools must; list rule not required, but description hints VALIDATION_ERROR if labelIds...; we'll enforce active existence as NOT_FOUND to match ecosystem)
    labelIds = labelIds or []
    if labelIds:
        labels = _load("labels.json")
        active_label_ids = set()
        for l in labels:
            if l.get("gmail_account_id") == acct.get("id") and l.get("status") == "active":
                active_label_ids.add(l.get("gmail_label_id"))
        for lid in labelIds:
            if lid not in active_label_ids:
                _record_read_op(acct.get("id"), {"maxResults": maxResults, "pageToken": pageToken, "q": q, "labelIds": labelIds,
                                                "includeSpamTrash": bool(includeSpamTrash), "includeBodyHtml": bool(includeBodyHtml)},
                                "failed", error=_err("NOT_FOUND", f"Label id not found or not active: {lid}", labelId=lid)["error"])
                return _err("NOT_FOUND", f"Label id not found or not active: {lid}", labelId=lid)

    objs = _load("mail_objects.json")
    msgs = []
    for o in objs:
        if o.get("gmail_account_id") != acct.get("id"):
            continue
        if o.get("object_type") != "message":
            continue
        # Spam/trash filter: exclude TRASH and SPAM unless includeSpamTrash
        if not includeSpamTrash:
            labs = o.get("label_gmail_ids") if isinstance(o.get("label_gmail_ids"), list) else []
            if "TRASH" in labs or "SPAM" in labs:
                continue
        # labelIds AND semantics
        if labelIds:
            labs = o.get("label_gmail_ids") if isinstance(o.get("label_gmail_ids"), list) else []
            labset = set([x for x in labs if isinstance(x, str)])
            ok = True
            for lid in labelIds:
                if lid not in labset:
                    ok = False
                    break
            if not ok:
                continue
        # q filtering (best-effort, local cache): case-insensitive substring across subject/from/snippet/body_text
        if q:
            qq = q.strip().lower()
            hay = " ".join([
                str(o.get("subject") or ""),
                str(o.get("from_addr") or ""),
                str(o.get("snippet") or ""),
                str(o.get("body_text") or ""),
            ]).lower()
            if qq not in hay:
                continue
        msgs.append(o)

    # Sort newest first by internal_date_ms when available else created_at
    def _sort_key(o):
        v = o.get("internal_date_ms")
        if isinstance(v, (int, float)) and not isinstance(v, bool):
            return (1, float(v))
        # parse created_at fallback: lexical ISOZ ok
        return (0, o.get("created_at") or "")
    msgs.sort(key=_sort_key, reverse=True)

    # Pagination with pageToken as integer offset encoded as string "offset:<n>" or raw "<n>"
    start = 0
    if pageToken:
        tok = pageToken
        m = re.match(r"^offset:(\d+)$", tok)
        if m:
            start = int(m.group(1))
        elif tok.isdigit():
            start = int(tok)
        else:
            _record_read_op(acct.get("id"), {"maxResults": maxResults, "pageToken": pageToken, "q": q, "labelIds": labelIds,
                                            "includeSpamTrash": bool(includeSpamTrash), "includeBodyHtml": bool(includeBodyHtml)},
                            "failed", error=_err("VALIDATION_ERROR", "Invalid pageToken")["error"])
            return _err("VALIDATION_ERROR", "Invalid pageToken")
        if start < 0:
            start = 0

    page = msgs[start:start + maxResults]
    next_tok = None
    if start + maxResults < len(msgs):
        next_tok = f"offset:{start + maxResults}"

    # Enforce includeBodyHtml rule
    out_msgs = []
    for mrow in page:
        out = dict(mrow)
        if not includeBodyHtml:
            out["body_html"] = None
        out_msgs.append(out)

    resp = {
        "messages": out_msgs,
        "nextPageToken": next_tok
    }

    _record_read_op(acct.get("id"), {"maxResults": maxResults, "pageToken": pageToken, "q": q, "labelIds": labelIds,
                                    "includeSpamTrash": bool(includeSpamTrash), "includeBodyHtml": bool(includeBodyHtml)},
                    "succeeded", response={"returned": len(out_msgs), "total": len(msgs), "nextPageToken": next_tok})

    return resp

def get_attachment(messageId, id, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0142000" if __import__("os").path.isdir("./environment_mix/0142000") else "/app/database")
    def _load(n):
