    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    endpoint = "get_attachment"

    def _now_iso():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        import base64
        raw = (int(datetime.datetime.utcnow().timestamp() * 1000)).to_bytes(6, "big") + os.urandom(10)
        return f"{prefix}_{base64.urlsafe_b64encode(raw).decode('ascii').rstrip('=')}"

    def _log(status, gmail_account_id=None, request=None, related_object_type=None, related_gmail_id=None, response=None, error=None):
        ops = _load("remote_operations.json")
        now = _now_iso()
        ops.append({
            "id": _gen_id("gop"),
            "gmail_account_id": gmail_account_id,
            "tool_name": endpoint,
            "request": request if isinstance(request, dict) else {},
            "idempotency_key": None,
            "related_object_type": related_object_type,
            "related_gmail_id": related_gmail_id,
            "response": response,
            "error": error,
            "attempt_count": 1,
            "status": status,
            "scheduled_at": None,
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        })
        _save("remote_operations.json", ops)

    try:
        if not isinstance(messageId, str) or not messageId.strip():
            _log("failed", None, {"messageId": messageId, "id": id}, related_object_type="attachment", related_gmail_id=None,
                 error={"code": "VALIDATION_ERROR", "message": "messageId must be a non-empty string"})
            return _err("VALIDATION_ERROR", "messageId is required and must be a non-empty string", field="messageId")
        if not isinstance(id, str) or not id.strip():
            _log("failed", None, {"messageId": messageId, "id": id}, related_object_type="attachment", related_gmail_id=None,
                 error={"code": "VALIDATION_ERROR", "message": "id must be a non-empty string"})
            return _err("VALIDATION_ERROR", "id is required and must be a non-empty string", field="id")

        messageId = messageId.strip()
        att_key = id.strip()

        mail_objects = _load("mail_objects.json")
        accounts = _load("gmail_accounts.json")

        # Find the message (by internal id or gmail_id)
        msg = next((o for o in mail_objects if isinstance(o, dict) and o.get("object_type") == "message" and (o.get("id") == messageId or o.get("gmail_id") == messageId)), None)
        if not msg:
            _log("failed", None, {"messageId": messageId, "id": att_key}, related_object_type="attachment", related_gmail_id=att_key,
                 error={"code": "NOT_FOUND", "message": "Message not found", "id": messageId})
            return _err("NOT_FOUND", "Message not found", id=messageId)

        gmail_account_id = msg.get("gmail_account_id")
        acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == gmail_account_id), None)
        if not acct or acct.get("status") not in ("active", "token_expired"):
            _log("failed", gmail_account_id, {"messageId": messageId, "id": att_key}, related_object_type="attachment", related_gmail_id=att_key,
                 error={"code": "UNAUTHORIZED", "message": "No connected Gmail account available for this operation"})
            return _err("UNAUTHORIZED", "No connected Gmail account available for this operation")

        msg_gmail_id = msg.get("gmail_id")

        # Business rule: attachment must be object_type='attachment' AND attachment_of_message_gmail_id == provided message's gmail_id
        att = None
        for o in mail_objects:
            if not isinstance(o, dict):
                continue
            if o.get("object_type") != "attachment":
                continue
            if o.get("gmail_account_id") != gmail_account_id:
                continue
            if not (o.get("id") == att_key or o.get("gmail_id") == att_key):
                continue
            if o.get("attachment_of_message_gmail_id") != msg_gmail_id:
                continue
            att = o
            break

        if not att:
            _log("failed", gmail_account_id, {"messageId": messageId, "id": att_key}, related_object_type="attachment", related_gmail_id=att_key,
                 error={"code": "NOT_FOUND", "message": "Attachment not found for message", "id": att_key, "messageId": msg_gmail_id})
            return _err("NOT_FOUND", "Attachment not found for message", id=att_key, messageId=messageId)

        _log("succeeded", gmail_account_id, {"messageId": messageId, "id": att_key}, related_object_type="attachment", related_gmail_id=att.get("gmail_id"),
             response={"id": att.get("gmail_id"), "messageId": msg_gmail_id})

        return {"attachment": dict(att)}
    except Exception as e:
        _log("failed", None, {"messageId": messageId, "id": id}, related_object_type="attachment", related_gmail_id=id,
             error={"code": "CONFLICT", "message": "Internal error", "details": str(e)})
        return _err("CONFLICT", "Internal error", details=str(e))

