            "created_at": now,
            "updated_at": now,
        })
        _save("remote_operations.json", ops)

    try:
        if not isinstance(id, str) or not id.strip():
            _append_op(None, "failed", {"id": id}, error={"code": "VALIDATION_ERROR", "message": "id must be a non-empty string"})
            return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")
        key = id.strip()

        accounts = _load("gmail_accounts.json")
        mail_objects = _load("mail_objects.json")
        ops = _load("remote_operations.json")

        thread = next((o for o in mail_objects if isinstance(o, dict) and o.get("object_type") == "thread" and (o.get("id") == key or o.get("gmail_id") == key)), None)
        if not thread:
            _append_op(None, "failed", {"id": key}, related_gmail_id=key,
                       error={"code": "NOT_FOUND", "message": "Thread not found", "id": key})
            return _err("NOT_FOUND", "Thread not found", id=key)

        gmail_account_id = thread.get("gmail_account_id")
        acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == gmail_account_id), None)
        if not acct or acct.get("status") not in ("active", "token_expired"):
            _append_op(gmail_account_id, "failed", {"id": key}, related_gmail_id=thread.get("gmail_id"),
                       error={"code": "UNAUTHORIZED", "message": "No connected Gmail account available for this operation"})
            return _err("UNAUTHORIZED", "No connected Gmail account available for this operation")
        if acct.get("status") in ("revoked", "disabled"):
            _append_op(gmail_account_id, "failed", {"id": key}, related_gmail_id=thread.get("gmail_id"),
                       error={"code": "UNAUTHORIZED", "message": "Gmail connection is revoked or disabled"})
            return _err("UNAUTHORIZED", "Gmail connection is revoked or disabled")

        # Idempotent delete
        if thread.get("status") != "deleted":
            thread["status"] = "deleted"
            thread["updated_at"] = _now_iso()
            _save("mail_objects.json", mail_objects)

        idem = f"delete_thread:{gmail_account_id}:{thread.get('gmail_id')}"
        existing = next((r for r in ops if isinstance(r, dict) and r.get("gmail_account_id") == gmail_account_id and r.get("idempotency_key") == idem), None)
        if not existing:
            _append_op(gmail_account_id, "queued", {"id": key}, related_gmail_id=thread.get("gmail_id"),
                       idempotency_key=idem, response={"accepted": True, "id": thread.get("gmail_id")})

        return {"thread": dict(thread)}
    except Exception as e:
        _append_op(None, "failed", {"id": id}, related_gmail_id=id,
                   error={"code": "CONFLICT", "message": "Internal error", "details": str(e)})
        return _err("CONFLICT", "Internal error", details=str(e))

def get_thread(id, includeBodyHtml=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0142000" if __import__("os").path.isdir("./environment_mix/0142000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _record_op(gmail_account_id, tool_name, request_obj, status, related_object_type=None, related_gmail_id=None, error=None, response=None):
        ops = _load("remote_operations.json")
        now = _now_iso()
        op_id = "op_" + now.replace("-", "").replace(":", "").replace("Z", "") + "_" + str(len(ops) + 1)
        row = {
            "id": op_id,
            "gmail_account_id": gmail_account_id,
            "tool_name": tool_name,
            "request": request_obj,
            "idempotency_key": None,
            "related_object_type": related_object_type,
            "related_gmail_id": related_gmail_id,
            "response": response,
            "error": error,
            "attempt_count": 1,
            "status": status,
            "scheduled_at": None,
            "started_at": now if status in ("running", "succeeded", "failed", "cancelled") else None,
            "finished_at": now if status in ("succeeded", "failed", "cancelled") else None,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        _save("remote_operations.json", ops)
        return row

    t0 = time.time()

    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id is required and must be a non-empty string")
    if includeBodyHtml is not None and not isinstance(includeBodyHtml, bool):
        return _err("VALIDATION_ERROR", "includeBodyHtml must be a boolean when provided")

    thread_id = id.strip()
    include_html = bool(includeBodyHtml) if includeBodyHtml is not None else False

    accounts = _load("gmail_accounts.json")
    acct = None
    for a in accounts:
        if a.get("status") in ("active", "token_expired"):
            acct = a
            break
    if not acct:
        return _err("UNAUTHORIZED", "No connected Gmail account is available for this request")

    mail = _load("mail_objects.json")

    thread_row = None
    for r in mail:
        if r.get("gmail_account_id") == acct.get("id") and r.get("object_type") == "thread" and r.get("gmail_id") == thread_id:
            thread_row = dict(r)
            break
    if not thread_row:
        return _err("NOT_FOUND", "Thread not found in local cache", id=thread_id)

    # Include messages belonging to this thread
    msgs = []
    for r in mail:
        if r.get("gmail_account_id") == acct.get("id") and r.get("object_type") == "message" and r.get("thread_gmail_id") == thread_id:
            rr = dict(r)
            if not include_html:
                rr["body_html"] = None
            msgs.append(rr)

    # Sort by internal_date_ms asc when available
    def _sort_key(x):
        v = x.get("internal_date_ms")
        try:
            return float(v) if v is not None else float("inf")
        except Exception:
            return float("inf")

    msgs.sort(key=_sort_key)

    req_obj = {"id": thread_id, "includeBodyHtml": include_html}
    _record_op(acct.get("id"), "get_thread", req_obj, status="running", related_object_type="thread", related_gmail_id=thread_id)
    op = _record_op(
        acct.get("id"),
        "get_thread",
        req_obj,
        status="succeeded",
        related_object_type="thread",
        related_gmail_id=thread_id,
        response={"message_count": len(msgs), "latency_ms": int((time.time() - t0) * 1000)},
    )

    return {
        "thread": thread_row,
        "messages": msgs,
        "meta": {
            "gmail_account_id": acct.get("id"),
            "primary_email": acct.get("primary_email"),
            "includeBodyHtml": include_html,
            "operation_id": op.get("id"),
        },
    }

def modify_thread(id, addLabelIds=None, removeLabelIds=None, **_extra):
    import json, os, datetime, time, uuid, copy
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0142000" if __import__("os").path.isdir("./environment_mix/0142000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "modify_thread"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, gmail_account_id=None, op_id=None, error=None):
        # Best-effort request log via remote_operations as observable dynamics (schema provides it).
        ops = _load("remote_operations.json")
        req = {"id": id, "addLabelIds": addLabelIds, "removeLabelIds": removeLabelIds}
        row = {
            "id": op_id or ("op_" + uuid.uuid4().hex),
            "gmail_account_id": gmail_account_id,
            "tool_name": endpoint,
            "request": req,
            "idempotency_key": None,
            "related_object_type": "thread",
            "related_gmail_id": id,
            "response": None,
            "error": error,
            "attempt_count": 1,
            "status": status,
            "scheduled_at": None,
            "started_at": _now(),
            "finished_at": _now(),
            "created_at": _now(),
            "updated_at": _now()
        }
        ops.append(row)
        _save("remote_operations.json", ops)

    # Validate inputs
    if not isinstance(id, str) or not id.strip():
        _log("failed", None, error={"code": "VALIDATION_ERROR", "message": "id is required"})
        return _err("VALIDATION_ERROR", "id is required")

    if addLabelIds is None:
        addLabelIds = []
    if removeLabelIds is None:
        removeLabelIds = []

    if not isinstance(addLabelIds, list) or not all(isinstance(x, str) and x for x in addLabelIds):
        _log("failed", None, error={"code": "VALIDATION_ERROR", "message": "addLabelIds must be an array of non-empty strings"})
        return _err("VALIDATION_ERROR", "addLabelIds must be an array of non-empty strings")
    if not isinstance(removeLabelIds, list) or not all(isinstance(x, str) and x for x in removeLabelIds):
        _log("failed", None, error={"code": "VALIDATION_ERROR", "message": "removeLabelIds must be an array of non-empty strings"})
        return _err("VALIDATION_ERROR", "removeLabelIds must be an array of non-empty strings")

    # Resolve an authorized gmail_account context (ambient auth): any active/token_expired account is callable;
    # revoked/disabled should block mutations.
    accounts = _load("gmail_accounts.json")
    # Pick an account that can serve: must not be revoked/disabled.
    acct = None
    for a in accounts:
        if isinstance(a, dict) and a.get("status") in ("active", "token_expired"):
            acct = a
            break
    if not acct:
        _log("failed", None, error={"code": "UNAUTHORIZED", "message": "No connected Gmail account available"})
        return _err("UNAUTHORIZED", "No connected Gmail account available")

    if acct.get("status") in ("revoked", "disabled"):
        _log("failed", acct.get("id"), error={"code": "UNAUTHORIZED", "message": "Gmail connection is revoked or disabled"})
        return _err("UNAUTHORIZED", "Gmail connection is revoked or disabled")

    gmail_account_id = acct.get("id")

    # Validate label ids exist and are active for same account
    labels = _load("labels.json")
    active_label_ids = set()
    for lab in labels:
        if isinstance(lab, dict) and lab.get("gmail_account_id") == gmail_account_id and lab.get("status") == "active":
            active_label_ids.add(lab.get("gmail_label_id"))

    invalid = [x for x in (addLabelIds + removeLabelIds) if x not in active_label_ids]
    if invalid:
        _log("failed", gmail_account_id, error={"code": "VALIDATION_ERROR", "message": "One or more label IDs are invalid or deleted", "invalid_label_ids": invalid})
        return _err("VALIDATION_ERROR", "One or more label IDs are invalid or deleted", invalid_label_ids=invalid)

    # Find thread in cache
    objs = _load("mail_objects.json")
    thread = None
    for o in objs:
        if isinstance(o, dict) and o.get("gmail_account_id") == gmail_account_id and o.get("object_type") == "thread" and o.get("gmail_id") == id:
            thread = o
            break
    if not thread:
        _log("failed", gmail_account_id, error={"code": "NOT_FOUND", "message": "Thread not found"})
        return _err("NOT_FOUND", "Thread not found")

    if thread.get("status") == "deleted":
        _log("failed", gmail_account_id, error={"code": "CONFLICT", "message": "Thread is permanently deleted"})
        return _err("CONFLICT", "Thread is permanently deleted")

    # Apply label modifications locally (denormalized label_gmail_ids)
    current = thread.get("label_gmail_ids") or []
    if not isinstance(current, list):
        current = []
    current_set = set([x for x in current if isinstance(x, str)])

    # Remove then add, in line with Gmail semantics
    for rid in removeLabelIds:
        current_set.discard(rid)
    for aid in addLabelIds:
        current_set.add(aid)

    thread["label_gmail_ids"] = sorted(current_set)
    thread["updated_at"] = _now()

    # Also apply to messages in that thread (best-effort cache coherence)
    thread_id = thread.get("thread_gmail_id") or thread.get("gmail_id")
    for o in objs:
        if not isinstance(o, dict):
            continue
        if o.get("gmail_account_id") != gmail_account_id:
            continue
        if o.get("object_type") == "message" and (o.get("thread_gmail_id") == thread_id):
            if o.get("status") != "deleted":
                cur = o.get("label_gmail_ids") or []
                if not isinstance(cur, list):
                    cur = []
                s = set([x for x in cur if isinstance(x, str)])
                for rid in removeLabelIds:
                    s.discard(rid)
                for aid in addLabelIds:
                    s.add(aid)
                o["label_gmail_ids"] = sorted(s)
                o["updated_at"] = _now()

    _save("mail_objects.json", objs)

    # Record remote operation (queued then succeeded for local server simulation)
    op_id = "op_" + uuid.uuid4().hex
    ops = _load("remote_operations.json")
    op_row = {
        "id": op_id,
        "gmail_account_id": gmail_account_id,
        "tool_name": endpoint,
        "request": {"id": id, "addLabelIds": addLabelIds, "removeLabelIds": removeLabelIds},
        "idempotency_key": None,
        "related_object_type": "thread",
        "related_gmail_id": id,
        "response": {"cached": True},
        "error": None,
        "attempt_count": 1,
        "status": "succeeded",
        "scheduled_at": None,
        "started_at": _now(),
        "finished_at": _now(),
        "created_at": _now(),
        "updated_at": _now()
    }
    ops.append(op_row)
    _save("remote_operations.json", ops)

    # Enforce includeBodyHtml rule not relevant here; return cached thread.
    # Provide a minimal envelope.
    latency_ms = int((time.time() - t0) * 1000)
    out = copy.deepcopy(thread)
    out.pop("body_html", None)
    return {"thread": out, "operation_id": op_id, "latency_ms": latency_ms}

def get_imap(**_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0142000" if __import__("os").path.isdir("./environment_mix/0142000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _coerce_dt(s):
        if s is None:
            return None
        if isinstance(s, (int, float)):
            return None
        if isinstance(s, str):
            try:
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            except Exception:
                return None
        return None

    def _log(endpoint, gmail_account_id, status, error=None, latency_ms=None):
        ops = _load("remote_operations.json")
        row = {
            "id": "rop_" + uuid.uuid4().hex,
            "gmail_account_id": gmail_account_id,
            "tool_name": endpoint,
            "request": {},
            "idempotency_key": None,
            "related_object_type": None,
            "related_gmail_id": None,
            "response": None,
            "error": error,
            "attempt_count": 1,
            "status": status,
            "scheduled_at": None,
            "started_at": _now_iso(),
            "finished_at": _now_iso(),
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        if latency_ms is not None:
            row["response"] = {"latency_ms": latency_ms} if row["response"] is None else dict(row["response"], latency_ms=latency_ms)
        ops.append(row)
        _save("remote_operations.json", ops)

    def _rate_limited(gmail_account_id):
        # Simple read quota: max 300 read calls/hour per gmail_account across get_* tools.
        ops = _load("remote_operations.json")
        now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        window_start = now - datetime.timedelta(hours=1)
        count = 0
        for r in ops:
            if r.get("gmail_account_id") != gmail_account_id:
                continue
            tn = r.get("tool_name")
            if tn not in ("get_imap", "get_language", "get_pop", "get_vacation"):
                continue
            created = _coerce_dt(r.get("created_at"))
            if created is None:
                continue
            if created.tzinfo is None:
                created = created.replace(tzinfo=datetime.timezone.utc)
            if created >= window_start:
                count += 1
        return count >= 300

    t0 = time.time()

    accounts = _load("gmail_accounts.json")
    # Ambient auth: find any account that can serve reads. Require active-ish connection.
    # Treat disabled/revoked as unauthorized for reads too (invalid connection).
    usable = []
    for a in accounts:
        if not isinstance(a, dict):
            continue
        if a.get("status") in ("active", "token_expired"):
            usable.append(a)

    if not usable:
        # No account can serve request
        _log("get_imap", gmail_account_id="unknown", status="failed", error={"code": "UNAUTHORIZED", "message": "No valid Gmail connection found."}, latency_ms=int((time.time() - t0) * 1000))
        return _err("UNAUTHORIZED", "No valid Gmail connection found.")

    # Choose an account that actually has imap settings cached (to satisfy NOT_FOUND semantics);
    # but rate limiting must apply per chosen account. We'll prefer one with settings, else first usable.
    settings = _load("gmail_settings.json")
    chosen = None
    for a in usable:
        for s in settings:
            if isinstance(s, dict) and s.get("gmail_account_id") == a.get("id") and s.get("setting_type") == "imap" and s.get("provider_key") == "singleton" and s.get("status") != "deleted":
                chosen = a
                break
        if chosen:
            break
    if chosen is None:
        chosen = usable[0]

    acct_id = chosen.get("id")
    if _rate_limited(acct_id):
        _log("get_imap", gmail_account_id=acct_id, status="failed", error={"code": "RATE_LIMIT", "message": "Read rate limit exceeded."}, latency_ms=int((time.time() - t0) * 1000))
        return _err("RATE_LIMIT", "Read rate limit exceeded.")

    # Scope check (best-effort): require a settings scope.
    scopes = chosen.get("scopes") if isinstance(chosen.get("scopes"), list) else []
    if not any(isinstance(sc, str) and ("gmail.settings" in sc or "mail.google.com" in sc) for sc in scopes):
        _log("get_imap", gmail_account_id=acct_id, status="failed", error={"code": "UNAUTHORIZED", "message": "Missing required Gmail settings scope."}, latency_ms=int((time.time() - t0) * 1000))
        return _err("UNAUTHORIZED", "Missing required Gmail settings scope.")

    imap_row = None
    for s in settings:
        if not isinstance(s, dict):
            continue
        if s.get("gmail_account_id") == acct_id and s.get("setting_type") == "imap" and s.get("provider_key") == "singleton" and s.get("status") != "deleted":
            imap_row = s
            break

    if imap_row is None:
        _log("get_imap", gmail_account_id=acct_id, status="failed", error={"code": "NOT_FOUND", "message": "IMAP settings have not been synced for this mailbox."}, latency_ms=int((time.time() - t0) * 1000))
        return _err("NOT_FOUND", "IMAP settings have not been synced for this mailbox.")

    # Success log
    _log("get_imap", gmail_account_id=acct_id, status="succeeded", error=None, latency_ms=int((time.time() - t0) * 1000))

    return {
        "imap": {
            "enabled": imap_row.get("payload", {}).get("enabled") if isinstance(imap_row.get("payload"), dict) else None,
            "expungeBehavior": imap_row.get("payload", {}).get("expungeBehavior") if isinstance(imap_row.get("payload"), dict) else None,
            "maxFolderSize": imap_row.get("payload", {}).get("maxFolderSize") if isinstance(imap_row.get("payload"), dict) else None,
        },
        "settings_id": imap_row.get("id"),
        "status": imap_row.get("status"),
        "updated_at": imap_row.get("updated_at"),
    }

