def update_auto_forwarding(enabled, emailAddress, disposition, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0142000" if __import__("os").path.isdir("./environment_mix/0142000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_auto_forwarding"

    # ---- auth/context resolution (ambient): pick a workable gmail_account ----
    accounts = _load("gmail_accounts.json")
    acct = None
    for a in accounts:
        if isinstance(a, dict) and a.get("status") in ("active", "token_expired"):
            # This tool requires connection not missing/expired => must be active
            if a.get("status") == "active":
                acct = a
                break
    # if none active, decide UNAUTHORIZED vs available-but-expired
    if acct is None:
        # if any token_expired exists, treat as UNAUTHORIZED per tool description
        status = "error"
        latency_ms = int((time.time() - t0) * 1000)
        ops = _load("remote_operations.json")
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        ops.append({
            "id": f"op_{uuid.uuid4().hex}",
            "gmail_account_id": (accounts[0].get("id") if accounts else "unknown"),
            "tool_name": endpoint,
            "request": {"enabled": enabled, "emailAddress": emailAddress, "disposition": disposition},
            "idempotency_key": None,
            "related_object_type": None,
            "related_gmail_id": None,
            "response": None,
            "error": {"code": "UNAUTHORIZED", "message": "No active Gmail connection available for this operation."},
            "attempt_count": 1,
            "status": "failed",
            "scheduled_at": None,
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now
        })
        _save("remote_operations.json", ops)
        return _err("UNAUTHORIZED", "No active Gmail connection available for this operation.")

    # ---- validate inputs ----
    if not isinstance(enabled, bool):
        return _err("VALIDATION_ERROR", "enabled must be a boolean.", field="enabled")
    if not isinstance(emailAddress, str) or not emailAddress.strip():
        return _err("VALIDATION_ERROR", "emailAddress must be a non-empty string.", field="emailAddress")
    if disposition not in ("leaveInInbox", "archive", "trash", "markRead"):
        return _err("VALIDATION_ERROR", "disposition must be one of leaveInInbox|archive|trash|markRead.", field="disposition")

    # Mutating tools rejected when account revoked/disabled
    if acct.get("status") in ("revoked", "disabled"):
        return _err("UNAUTHORIZED", "Gmail connection is revoked or disabled.")

    # Business rule: if enabled=true then emailAddress must match an existing active forwarding_address
    settings = _load("gmail_settings.json")
    if enabled:
        ok = False
        for s in settings:
            if not isinstance(s, dict):
                continue
            if s.get("gmail_account_id") != acct.get("id"):
                continue
            if s.get("setting_type") == "forwarding_address" and s.get("status") == "active":
                p = s.get("payload") or {}
                if isinstance(p, dict) and p.get("forwardingEmail") == emailAddress:
                    ok = True
                    break
        if not ok:
            return _err(
                "CONFLICT",
                "Cannot enable auto-forwarding: emailAddress is not a verified active forwarding address.",
                emailAddress=emailAddress
            )

    # ---- create remote operation (idempotency: stable key by request) ----
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    request_obj = {"enabled": enabled, "emailAddress": emailAddress, "disposition": disposition}
    idem = "auto_forwarding:" + uuid.uuid5(uuid.NAMESPACE_OID, json.dumps(request_obj, sort_keys=True)).hex

    ops = _load("remote_operations.json")
    existing_op = None
    for op in ops:
        if isinstance(op, dict) and op.get("gmail_account_id") == acct.get("id") and op.get("idempotency_key") == idem:
            existing_op = op
            break

    if existing_op is not None and existing_op.get("status") in ("queued", "running", "succeeded"):
        # Do not execute twice; return current mirrored settings row (or create if missing but op exists)
        # Ensure mirror is present/updated? If op succeeded earlier, mirror should exist; but we won't fabricate.
        for s in settings:
            if isinstance(s, dict) and s.get("gmail_account_id") == acct.get("id") and s.get("setting_type") == "auto_forwarding" and s.get("provider_key") == "singleton":
                resp = dict(s)
                return {"auto_forwarding": resp}
        return _err("CONFLICT", "Operation already enqueued; settings mirror not yet available.", operation_id=existing_op.get("id"))

    # ---- upsert settings mirror row ----
    af_row = None
    for s in settings:
        if isinstance(s, dict) and s.get("gmail_account_id") == acct.get("id") and s.get("setting_type") == "auto_forwarding" and s.get("provider_key") == "singleton":
            af_row = s
            break

    def _new_id(prefix):
        return f"gs_{uuid.uuid4().hex}"

    if af_row is None:
        af_row = {
            "id": _new_id("gs"),
            "gmail_account_id": acct.get("id"),
            "setting_type": "auto_forwarding",
            "provider_key": "singleton",
            "payload": {"enabled": enabled, "emailAddress": emailAddress, "disposition": disposition},
            "status": "active",
            "created_at": now,
            "updated_at": now
        }
        settings.append(af_row)
    else:
        # lifecycle: allow active/disabled/pending_verification -> active; deleted is terminal
        if af_row.get("status") == "deleted":
            return _err("INVALID_TRANSITION", "Cannot update a deleted auto_forwarding settings object.")
        af_row["payload"] = {"enabled": enabled, "emailAddress": emailAddress, "disposition": disposition}
        # keep status active (mirror reflects desired config)
        if af_row.get("status") in ("disabled", "pending_verification"):
            af_row["status"] = "active"
        af_row["updated_at"] = now

    _save("gmail_settings.json", settings)

    # ---- enqueue/record remote op: queued -> running -> succeeded (single attempt) ----
    op_row = {
        "id": f"op_{uuid.uuid4().hex}",
        "gmail_account_id": acct.get("id"),
        "tool_name": endpoint,
        "request": request_obj,
        "idempotency_key": idem,
        "related_object_type": None,
        "related_gmail_id": "singleton",
        "response": None,
        "error": None,
        "attempt_count": 0,
        "status": "queued",
        "scheduled_at": now,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }
    ops.append(op_row)
    _save("remote_operations.json", ops)

    # Simulate execution in-process: running->succeeded, attempt_count=1
    started = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    op_row["status"] = "running"
    op_row["started_at"] = started
    op_row["updated_at"] = started
    op_row["attempt_count"] = 1
    _save("remote_operations.json", ops)

    finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    op_row["status"] = "succeeded"
    op_row["finished_at"] = finished
    op_row["updated_at"] = finished
    op_row["response"] = {"setting_type": "auto_forwarding", "provider_key": "singleton", "payload": af_row["payload"], "status": af_row["status"]}
    _save("remote_operations.json", ops)

    return {"auto_forwarding": dict(af_row)}

