def update_vacation(enableAutoReply, responseBodyPlainText, responseSubject=None, restrictToContacts=None, restrictToDomain=None, startTime=None, endTime=None, **_extra):
    import json, os, datetime, time, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0142000" if __import__("os").path.isdir("./environment_mix/0142000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    gmail_accounts = _load("gmail_accounts.json")
    gmail_settings = _load("gmail_settings.json")
    remote_ops = _load("remote_operations.json")

    def _log_op(gmail_account_id, tool_name, request_obj, status, related_object_type=None, related_gmail_id=None, response=None, error=None, idempotency_key=None, attempt_count=1):
        op_id = "op_" + uuid.uuid4().hex
        row = {
            "id": op_id,
            "gmail_account_id": gmail_account_id,
            "tool_name": tool_name,
            "request": request_obj,
            "idempotency_key": idempotency_key,
            "related_object_type": related_object_type,
            "related_gmail_id": related_gmail_id,
            "response": response,
            "error": error,
            "attempt_count": int(attempt_count),
            "status": status,
            "scheduled_at": None,
            "started_at": now if status in ("running", "succeeded", "failed") else None,
            "finished_at": now if status in ("succeeded", "failed", "cancelled") else None,
            "created_at": now,
            "updated_at": now,
        }
        remote_ops.append(row)
        _save("remote_operations.json", remote_ops)
        return row

    def _pick_account_for_mutation():
        # Must find an account that can serve the call. For mutating tools, revoked/disabled are rejected.
        for a in gmail_accounts:
            if not isinstance(a, dict):
                continue
            st = a.get("status")
            if st in ("active", "token_expired"):
                return a
        return None

    def _parse_epoch_ms_string(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return _err("VALIDATION_ERROR", f"{field} must be a string epoch-millisecond value")
        if not re.fullmatch(r"\d+", s):
            return _err("VALIDATION_ERROR", f"{field} must be a numeric-string epoch-millisecond value")
        try:
            v = int(s)
        except ValueError:
            return _err("VALIDATION_ERROR", f"{field} must be a numeric-string epoch-millisecond value")
        if v < 0:
            return _err("VALIDATION_ERROR", f"{field} must be >= 0")
        return v

    # Validate inputs
    if not isinstance(enableAutoReply, bool):
        # Still log call later? We need account for logging; if none, return UNAUTHORIZED.
        acct = _pick_account_for_mutation()
        if not acct:
            return _err("UNAUTHORIZED", "No authorized Gmail connection available")
        _log_op(acct["id"], "update_vacation", {
            "enableAutoReply": enableAutoReply,
            "responseBodyPlainText": responseBodyPlainText,
            "responseSubject": responseSubject,
            "restrictToContacts": restrictToContacts,
            "restrictToDomain": restrictToDomain,
            "startTime": startTime,
            "endTime": endTime
        }, "failed", related_object_type=None, related_gmail_id="singleton",
           error={"code": "VALIDATION_ERROR", "message": "enableAutoReply must be boolean"})
        return _err("VALIDATION_ERROR", "enableAutoReply must be boolean")

    if not isinstance(responseBodyPlainText, str):
        acct = _pick_account_for_mutation()
        if not acct:
            return _err("UNAUTHORIZED", "No authorized Gmail connection available")
        _log_op(acct["id"], "update_vacation", {
            "enableAutoReply": enableAutoReply,
            "responseBodyPlainText": responseBodyPlainText,
            "responseSubject": responseSubject,
            "restrictToContacts": restrictToContacts,
            "restrictToDomain": restrictToDomain,
            "startTime": startTime,
            "endTime": endTime
        }, "failed", related_object_type=None, related_gmail_id="singleton",
           error={"code": "VALIDATION_ERROR", "message": "responseBodyPlainText must be string"})
        return _err("VALIDATION_ERROR", "responseBodyPlainText must be a string")

    if responseSubject is not None and not isinstance(responseSubject, str):
        acct = _pick_account_for_mutation()
        if not acct:
            return _err("UNAUTHORIZED", "No authorized Gmail connection available")
        _log_op(acct["id"], "update_vacation", {
            "enableAutoReply": enableAutoReply,
            "responseBodyPlainText": responseBodyPlainText,
            "responseSubject": responseSubject,
            "restrictToContacts": restrictToContacts,
            "restrictToDomain": restrictToDomain,
            "startTime": startTime,
            "endTime": endTime
        }, "failed", related_object_type=None, related_gmail_id="singleton",
           error={"code": "VALIDATION_ERROR", "message": "responseSubject must be string when provided"})
        return _err("VALIDATION_ERROR", "responseSubject must be a string when provided")

    for bf, bv in (("restrictToContacts", restrictToContacts), ("restrictToDomain", restrictToDomain)):
        if bv is not None and not isinstance(bv, bool):
            acct = _pick_account_for_mutation()
            if not acct:
                return _err("UNAUTHORIZED", "No authorized Gmail connection available")
            _log_op(acct["id"], "update_vacation", {
                "enableAutoReply": enableAutoReply,
                "responseBodyPlainText": responseBodyPlainText,
                "responseSubject": responseSubject,
                "restrictToContacts": restrictToContacts,
                "restrictToDomain": restrictToDomain,
                "startTime": startTime,
                "endTime": endTime
            }, "failed", related_object_type=None, related_gmail_id="singleton",
               error={"code": "VALIDATION_ERROR", "message": f"{bf} must be boolean when provided"})
            return _err("VALIDATION_ERROR", f"{bf} must be a boolean when provided")

    st_v = _parse_epoch_ms_string(startTime, "startTime")
    if isinstance(st_v, dict) and "error" in st_v:
        acct = _pick_account_for_mutation()
        if not acct:
            return _err("UNAUTHORIZED", "No authorized Gmail connection available")
        _log_op(acct["id"], "update_vacation", {
            "enableAutoReply": enableAutoReply,
            "responseBodyPlainText": responseBodyPlainText,
            "responseSubject": responseSubject,
            "restrictToContacts": restrictToContacts,
            "restrictToDomain": restrictToDomain,
            "startTime": startTime,
            "endTime": endTime
        }, "failed", related_object_type=None, related_gmail_id="singleton", error=st_v["error"])
        return st_v

    en_v = _parse_epoch_ms_string(endTime, "endTime")
    if isinstance(en_v, dict) and "error" in en_v:
        acct = _pick_account_for_mutation()
        if not acct:
            return _err("UNAUTHORIZED", "No authorized Gmail connection available")
        _log_op(acct["id"], "update_vacation", {
            "enableAutoReply": enableAutoReply,
            "responseBodyPlainText": responseBodyPlainText,
            "responseSubject": responseSubject,
            "restrictToContacts": restrictToContacts,
            "restrictToDomain": restrictToDomain,
            "startTime": startTime,
            "endTime": endTime
        }, "failed", related_object_type=None, related_gmail_id="singleton", error=en_v["error"])
        return en_v

    if st_v is not None and en_v is not None and en_v < st_v:
        acct = _pick_account_for_mutation()
        if not acct:
            return _err("UNAUTHORIZED", "No authorized Gmail connection available")
        e = _err("VALIDATION_ERROR", "endTime must be >= startTime when both are provided")
        _log_op(acct["id"], "update_vacation", {
            "enableAutoReply": enableAutoReply,
            "responseBodyPlainText": responseBodyPlainText,
            "responseSubject": responseSubject,
            "restrictToContacts": restrictToContacts,
            "restrictToDomain": restrictToDomain,
            "startTime": startTime,
            "endTime": endTime
        }, "failed", related_object_type=None, related_gmail_id="singleton", error=e["error"])
        return e

    acct = _pick_account_for_mutation()
    if not acct:
        # No connection that can serve; per tool description, expired is unauthorized. Here "token_expired" exists but is
        # allowed for selection; however, the description requires missing/expired -> UNAUTHORIZED.
        # We interpret "token_expired" as expired and thus not usable for this tool.
        for a in gmail_accounts:
            if isinstance(a, dict) and a.get("status") == "token_expired":
                _log_op(a["id"], "update_vacation", {
                    "enableAutoReply": enableAutoReply,
                    "responseBodyPlainText": responseBodyPlainText,
                    "responseSubject": responseSubject,
                    "restrictToContacts": restrictToContacts,
                    "restrictToDomain": restrictToDomain,
                    "startTime": startTime,
                    "endTime": endTime
                }, "failed", related_object_type=None, related_gmail_id="singleton",
                   error={"code": "UNAUTHORIZED", "message": "Gmail connection expired"})
                return _err("UNAUTHORIZED", "Gmail connection expired")
        return _err("UNAUTHORIZED", "No authorized Gmail connection available")

    if acct.get("status") in ("revoked", "disabled"):
        op = _log_op(acct["id"], "update_vacation", {
            "enableAutoReply": enableAutoReply,
            "responseBodyPlainText": responseBodyPlainText,
            "responseSubject": responseSubject,
            "restrictToContacts": restrictToContacts,
            "restrictToDomain": restrictToDomain,
            "startTime": startTime,
            "endTime": endTime
        }, "failed", related_object_type=None, related_gmail_id="singleton",
           error={"code": "UNAUTHORIZED", "message": "Gmail connection not permitted"})
        return _err("UNAUTHORIZED", "Gmail connection not permitted", operation_id=op["id"])

    if acct.get("status") == "token_expired":
        op = _log_op(acct["id"], "update_vacation", {
            "enableAutoReply": enableAutoReply,
            "responseBodyPlainText": responseBodyPlainText,
            "responseSubject": responseSubject,
            "restrictToContacts": restrictToContacts,
            "restrictToDomain": restrictToDomain,
            "startTime": startTime,
            "endTime": endTime
        }, "failed", related_object_type=None, related_gmail_id="singleton",
           error={"code": "UNAUTHORIZED", "message": "Gmail connection expired"})
        return _err("UNAUTHORIZED", "Gmail connection expired", operation_id=op["id"])

    # Build payload respecting schema constraint for vacation
    payload = {
        "enableAutoReply": enableAutoReply,
        "responseBodyPlainText": responseBodyPlainText
    }
    if responseSubject is not None:
        payload["responseSubject"] = responseSubject
    if restrictToContacts is not None:
        payload["restrictToContacts"] = restrictToContacts
    if restrictToDomain is not None:
        payload["restrictToDomain"] = restrictToDomain
    payload["startTime"] = None if st_v is None else str(st_v)
    payload["endTime"] = None if en_v is None else str(en_v)

    # Idempotency: derive from stable request
    req_obj = {
        "enableAutoReply": enableAutoReply,
        "responseBodyPlainText": responseBodyPlainText,
        "responseSubject": responseSubject,
        "restrictToContacts": restrictToContacts,
        "restrictToDomain": restrictToDomain,
        "startTime": startTime,
        "endTime": endTime
    }
    idempotency_key = "vacation:" + acct["id"] + ":" + uuid.uuid5(uuid.NAMESPACE_URL, json.dumps(req_obj, sort_keys=True, ensure_ascii=False)).hex

    # If an op with same idempotency_key already exists and succeeded, do not execute twice; return current settings.
    existing_op = None
    for op in remote_ops:
        if isinstance(op, dict) and op.get("gmail_account_id") == acct["id"] and op.get("idempotency_key") == idempotency_key:
            existing_op = op
            break

    # Upsert settings row
    setting_row = None
    for s in gmail_settings:
        if isinstance(s, dict) and s.get("gmail_account_id") == acct["id"] and s.get("setting_type") == "vacation" and s.get("provider_key") == "singleton":
            setting_row = s
            break

    if setting_row is None:
        setting_row = {
            "id": "set_" + uuid.uuid4().hex,
            "gmail_account_id": acct["id"],
            "setting_type": "vacation",
            "provider_key": "singleton",
            "payload": payload,
            "status": "active",
            "created_at": now,
            "updated_at": now
        }
        gmail_settings.append(setting_row)
    else:
        setting_row["payload"] = payload
        # keep status unless deleted; if deleted, illegal to transition to active? schema allows deleted:[] so refuse
        if setting_row.get("status") == "deleted":
            op = _log_op(acct["id"], "update_vacation", req_obj, "failed", related_object_type=None, related_gmail_id="singleton",
                         error={"code": "INVALID_TRANSITION", "message": "Cannot update deleted vacation settings"}, idempotency_key=idempotency_key)
            return _err("INVALID_TRANSITION", "Cannot update deleted vacation settings", operation_id=op["id"])
        setting_row["updated_at"] = now

    _save("gmail_settings.json", gmail_settings)

    # Record/enqueue remote op
    if existing_op and existing_op.get("status") in ("queued", "running", "succeeded"):
        # No double execution; return the settings and existing operation id
        latency_ms = int((time.time() - t0) * 1000)
        return {
            "vacation": setting_row,
            "operation": {"id": existing_op.get("id"), "status": existing_op.get("status"), "attempt_count": existing_op.get("attempt_count")},
            "meta": {"latency_ms": latency_ms}
        }

    op_row = _log_op(
        acct["id"],
        "update_vacation",
        req_obj,
        "queued",
        related_object_type=None,
        related_gmail_id="singleton",
        response={"settings_id": setting_row["id"], "mirror_updated": True},
        error=None,
        idempotency_key=idempotency_key,
        attempt_count=(int(existing_op.get("attempt_count")) + 1) if existing_op else 1
    )

    # If there was an old failed op with same idempotency_key, keep it; uniqueness constraint implies real backend would reuse.
    # We'll cancel the old failed row by marking it cancelled to maintain uniqueness across future calls.
    if existing_op and existing_op is not op_row:
        # Only safe if old is failed; otherwise we handled above.
        if existing_op.get("status") == "failed":
            existing_op["status"] = "cancelled"
            existing_op["updated_at"] = now
            existing_op["finished_at"] = now
            _save("remote_operations.json", remote_ops)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "vacation": setting_row,
        "operation": {"id": op_row["id"], "status": op_row["status"], "attempt_count": op_row["attempt_count"]},
        "meta": {"latency_ms": latency_ms}
    }

def add_delegate(delegateEmail, **_extra):
