    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    gmail_accounts = _load("gmail_accounts.json")
    gmail_settings = _load("gmail_settings.json")
    remote_ops = _load("remote_operations.json")

    def _log_op(gmail_account_id, tool_name, request_obj, status, related_gmail_id=None, response=None, error=None, idempotency_key=None, attempt_count=1):
        op_id = "op_" + uuid.uuid4().hex
        row = {
            "id": op_id,
            "gmail_account_id": gmail_account_id,
            "tool_name": tool_name,
            "request": request_obj,
            "idempotency_key": idempotency_key,
            "related_object_type": None,
            "related_gmail_id": related_gmail_id,
            "response": response,
            "error": error,
            "attempt_count": int(attempt_count),
            "status": status,
            "scheduled_at": None,
            "started_at": now if status in ("running", "succeeded", "failed") else None,
            "finished_at": now if status in ("succeeded", "failed", "cancelled") else None,
            "created_at": now,
            "updated_at": now,
        }
        remote_ops.append(row)
        _save("remote_operations.json", remote_ops)
        return row

    # Validate input
    if not isinstance(delegateEmail, str) or not delegateEmail.strip():
        # Need some account to log against; if none, return UNAUTHORIZED
        acct = next((a for a in gmail_accounts if isinstance(a, dict) and a.get("status") in ("active", "token_expired")), None)
        if acct:
            _log_op(acct["id"], "add_delegate", {"delegateEmail": delegateEmail}, "failed",
                    related_gmail_id=str(delegateEmail) if delegateEmail is not None else None,
                    error={"code": "VALIDATION_ERROR", "message": "delegateEmail must be a non-empty string"})
        return _err("VALIDATION_ERROR", "delegateEmail must be a non-empty string")

    # Resolve account: description says missing/expired => UNAUTHORIZED; treat token_expired as expired
    acct = next((a for a in gmail_accounts if isinstance(a, dict) and a.get("status") == "active"), None)
    if not acct:
        expired = next((a for a in gmail_accounts if isinstance(a, dict) and a.get("status") == "token_expired"), None)
        if expired:
            op = _log_op(expired["id"], "add_delegate", {"delegateEmail": delegateEmail}, "failed",
                         related_gmail_id=delegateEmail,
                         error={"code": "UNAUTHORIZED", "message": "Gmail connection expired"})
            return _err("UNAUTHORIZED", "Gmail connection expired", operation_id=op["id"])
        return _err("UNAUTHORIZED", "No authorized Gmail connection available")

    if acct.get("status") in ("revoked", "disabled"):
        op = _log_op(acct["id"], "add_delegate", {"delegateEmail": delegateEmail}, "failed",
                     related_gmail_id=delegateEmail,
                     error={"code": "UNAUTHORIZED", "message": "Gmail connection not permitted"})
        return _err("UNAUTHORIZED", "Gmail connection not permitted", operation_id=op["id"])

    # Conflict if already exists and active/pending/disabled (i.e., not deleted)
    existing = None
    for s in gmail_settings:
        if isinstance(s, dict) and s.get("gmail_account_id") == acct["id"] and s.get("setting_type") == "delegate" and s.get("provider_key") == delegateEmail:
            existing = s
            break
    if existing and existing.get("status") != "deleted":
        op = _log_op(acct["id"], "add_delegate", {"delegateEmail": delegateEmail}, "failed",
                     related_gmail_id=delegateEmail,
                     error={"code": "CONFLICT", "message": "Delegate already exists"})
        return _err("CONFLICT", "Delegate already exists", operation_id=op["id"])

    # Upsert delegate settings; status active (mirror assumes added)
    if existing and existing.get("status") == "deleted":
        # deleted is terminal; cannot transition
        op = _log_op(acct["id"], "add_delegate", {"delegateEmail": delegateEmail}, "failed",
                     related_gmail_id=delegateEmail,
                     error={"code": "INVALID_TRANSITION", "message": "Cannot re-add a deleted delegate entry in mirror"})
        return _err("INVALID_TRANSITION", "Cannot re-add a deleted delegate entry in mirror", operation_id=op["id"])

    row = {
        "id": "set_" + uuid.uuid4().hex,
        "gmail_account_id": acct["id"],
        "setting_type": "delegate",
        "provider_key": delegateEmail,
        "payload": {"delegateEmail": delegateEmail},
        "status": "active",
        "created_at": now,
        "updated_at": now
    }
    gmail_settings.append(row)
    _save("gmail_settings.json", gmail_settings)

    # Enqueue remote op (idempotency based on account+email+verb)
    idem = "delegate:add:" + acct["id"] + ":" + delegateEmail.lower()
    for opx in remote_ops:
        if isinstance(opx, dict) and opx.get("gmail_account_id") == acct["id"] and opx.get("idempotency_key") == idem and opx.get("status") in ("queued", "running", "succeeded"):
            latency_ms = int((time.time() - t0) * 1000)
            return {
                "delegate": row,
                "operation": {"id": opx.get("id"), "status": opx.get("status"), "attempt_count": opx.get("attempt_count")},
                "meta": {"latency_ms": latency_ms}
            }

    op_row = _log_op(
        acct["id"], "add_delegate", {"delegateEmail": delegateEmail}, "queued",
        related_gmail_id=delegateEmail,
        response={"settings_id": row["id"], "mirror_created": True},
        idempotency_key=idem,
        attempt_count=1
    )

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "delegate": row,
        "operation": {"id": op_row["id"], "status": op_row["status"], "attempt_count": op_row["attempt_count"]},
        "meta": {"latency_ms": latency_ms}
    }

