def get_delegate(delegateEmail, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0142000" if __import__("os").path.isdir("./environment_mix/0142000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    endpoint = "get_delegate"

    def _now_iso():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        import base64
        raw = (int(datetime.datetime.utcnow().timestamp() * 1000)).to_bytes(6, "big") + os.urandom(10)
        return f"{prefix}_{base64.urlsafe_b64encode(raw).decode('ascii').rstrip('=')}"

    def _log(status, gmail_account_id=None, request=None, related_gmail_id=None, response=None, error=None):
        ops = _load("remote_operations.json")
        now = _now_iso()
        ops.append({
            "id": _gen_id("gop"),
            "gmail_account_id": gmail_account_id,
            "tool_name": endpoint,
            "request": request if isinstance(request, dict) else {},
            "idempotency_key": None,
            "related_object_type": None,
            "related_gmail_id": related_gmail_id,
            "response": response,
            "error": error,
            "attempt_count": 1,
            "status": status,
            "scheduled_at": None,
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        })
        _save("remote_operations.json", ops)

    try:
        if not isinstance(delegateEmail, str) or not delegateEmail.strip():
            _log("failed", None, {"delegateEmail": delegateEmail}, error={"code": "VALIDATION_ERROR", "message": "delegateEmail must be a non-empty string"})
            return _err("VALIDATION_ERROR", "delegateEmail must be a non-empty string", field="delegateEmail")
        delegateEmail = delegateEmail.strip()

        settings = _load("gmail_settings.json")
        accounts = _load("gmail_accounts.json")

        # Find a matching delegate settings row across all connected accounts
        match = None
        for s in settings:
            if not isinstance(s, dict):
                continue
            if s.get("setting_type") != "delegate":
                continue
            payload = s.get("payload") if isinstance(s.get("payload"), dict) else {}
            if s.get("provider_key") == delegateEmail or payload.get("delegateEmail") == delegateEmail:
                match = s
                break

        if not match:
            _log("failed", None, {"delegateEmail": delegateEmail}, related_gmail_id=delegateEmail,
                 error={"code": "NOT_FOUND", "message": "Delegate not found", "delegateEmail": delegateEmail})
            return _err("NOT_FOUND", "Delegate not found", delegateEmail=delegateEmail)

        gmail_account_id = match.get("gmail_account_id")
        acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == gmail_account_id), None)
        if not acct or acct.get("status") not in ("active", "token_expired"):
            _log("failed", gmail_account_id, {"delegateEmail": delegateEmail}, related_gmail_id=delegateEmail,
                 error={"code": "UNAUTHORIZED", "message": "No connected Gmail account available for this operation"})
            return _err("UNAUTHORIZED", "No connected Gmail account available for this operation")

        _log("succeeded", gmail_account_id, {"delegateEmail": delegateEmail}, related_gmail_id=delegateEmail,
             response={"provider_key": match.get("provider_key")})
        return {"delegate": dict(match)}
    except Exception as e:
        _log("failed", None, {"delegateEmail": delegateEmail}, related_gmail_id=delegateEmail,
             error={"code": "CONFLICT", "message": "Internal error", "details": str(e)})
        return _err("CONFLICT", "Internal error", details=str(e))

def list_delegates(includeDeleted=None, maxResults=None, pageToken=None, q=None, sortBy=None, sortOrder=None, **_extra):
    import json, os, datetime, time, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0142000" if __import__("os").path.isdir("./environment_mix/0142000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(gmail_account_id, tool_name, request, status, error=None):
        ops = _load("remote_operations.json")
        op_id = "rop_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("=")
        row = {
            "id": op_id,
            "gmail_account_id": gmail_account_id,
            "tool_name": tool_name,
            "request": request,
            "idempotency_key": None,
            "related_object_type": None,
            "related_gmail_id": None,
            "response": None if status != "succeeded" else {"ok": True},
            "error": error,
            "attempt_count": 1,
            "status": status,
            "scheduled_at": None,
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        _save("remote_operations.json", ops)

    def _rate_limit_check(gmail_account_id, tool_name):
        # Simple per-account per-tool rate limit: 120 requests/minute
        ops = _load("remote_operations.json")
        window_s = 60
        limit = 120
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)

        def _parse_ts(s):
            if not s or not isinstance(s, str): 
                return None
            try:
                if s.endswith("Z"):
                    s2 = s[:-1]
                    dt = datetime.datetime.fromisoformat(s2)
                    return dt
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        count = 0
        for r in ops:
            if r.get("gmail_account_id") != gmail_account_id: 
                continue
            if r.get("tool_name") != tool_name:
                continue
            ts = _parse_ts(r.get("created_at"))
            if ts and ts >= cutoff:
                count += 1
        if count >= limit:
            return False
        return True

    # Validate inputs
    if includeDeleted is not None and not isinstance(includeDeleted, bool):
        return _err("VALIDATION_ERROR", "includeDeleted must be a boolean")
    if maxResults is not None:
        if not isinstance(maxResults, (int, float)) or isinstance(maxResults, bool):
            return _err("VALIDATION_ERROR", "maxResults must be a number between 1 and 500")
        if int(maxResults) != maxResults:
            return _err("VALIDATION_ERROR", "maxResults must be an integer between 1 and 500")
        maxResults = int(maxResults)
        if maxResults < 1 or maxResults > 500:
            return _err("VALIDATION_ERROR", "maxResults must be between 1 and 500")
    else:
        maxResults = 100  # server default <= 100
    if pageToken is not None and not isinstance(pageToken, str):
        return _err("VALIDATION_ERROR", "pageToken must be a string")
    if q is not None and not isinstance(q, str):
        return _err("VALIDATION_ERROR", "q must be a string")
    if sortBy is not None and sortBy not in ("createdAt", "updatedAt", "providerKey"):
        return _err("VALIDATION_ERROR", "sortBy must be one of: createdAt, updatedAt, providerKey")
    if sortOrder is not None and sortOrder not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "sortOrder must be one of: asc, desc")
    if sortBy is None:
        sortBy = "createdAt"
    if sortOrder is None:
        sortOrder = "desc"

    # Resolve an authorized gmail account context (ambient auth)
    accounts = _load("gmail_accounts.json")
    acct = None
    for a in accounts:
        if a.get("status") in ("active", "token_expired"):
            acct = a
            break
    if not acct:
        # log without account context is not possible; return UNAUTHORIZED
        return _err("UNAUTHORIZED", "No valid Gmail connection exists for this user")

    gmail_account_id = acct.get("id")

    # Rate limit enforcement (observed through remote_operations)
    if not _rate_limit_check(gmail_account_id, "list_delegates"):
        _log(gmail_account_id, "list_delegates", {
            "includeDeleted": includeDeleted, "maxResults": maxResults, "pageToken": pageToken, "q": q,
            "sortBy": sortBy, "sortOrder": sortOrder
        }, "failed", error=_err("RATE_LIMIT", "Rate limit exceeded")["error"])
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # Read delegates from gmail_settings cache
    settings = _load("gmail_settings.json")
    delegates = [s for s in settings
                 if s.get("gmail_account_id") == gmail_account_id and s.get("setting_type") == "delegate"]

    if not includeDeleted:
        delegates = [d for d in delegates if d.get("status") not in ("deleted", "disabled")]

    if q:
        ql = q.lower()
        delegates = [d for d in delegates if isinstance(d.get("provider_key"), str) and ql in d.get("provider_key").lower()]

    # Sorting
    def _key(d):
        if sortBy == "providerKey":
            return (d.get("provider_key") or "").lower()
        if sortBy == "updatedAt":
            return d.get("updated_at") or ""
        return d.get("created_at") or ""
    reverse = (sortOrder == "desc")
    delegates.sort(key=_key, reverse=reverse)

    # Pagination: pageToken is opaque base64url encoded JSON {"offset": int}
    offset = 0
    if pageToken:
        try:
            pad = "=" * (-len(pageToken) % 4)
            decoded = base64.urlsafe_b64decode((pageToken + pad).encode("ascii")).decode("utf-8")
            tok = json.loads(decoded)
            if not isinstance(tok, dict) or "offset" not in tok:
                return _err("VALIDATION_ERROR", "Invalid pageToken")
            if not isinstance(tok["offset"], int) or tok["offset"] < 0:
                return _err("VALIDATION_ERROR", "Invalid pageToken")
            offset = tok["offset"]
        except (ValueError, json.JSONDecodeError, UnicodeDecodeError):
            return _err("VALIDATION_ERROR", "Invalid pageToken")

    total = len(delegates)
    page = delegates[offset: offset + maxResults]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_token = None
    if has_more:
        next_token = base64.urlsafe_b64encode(json.dumps({"offset": next_offset}).encode("utf-8")).decode("ascii").rstrip("=")

    # Log call as a succeeded remote operation record (request log)
    _log(gmail_account_id, "list_delegates", {
        "includeDeleted": includeDeleted, "maxResults": maxResults, "pageToken": pageToken, "q": q,
        "sortBy": sortBy, "sortOrder": sortOrder
    }, "succeeded", error=None)

    return {
        "delegates": page,
        "nextPageToken": next_token,
        "resultSizeEstimate": len(page),
        "total": total,
        "has_more": has_more,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def create_filter(criteria, action, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0142000" if __import__("os").path.isdir("./environment_mix/0142000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    endpoint = "create_filter"

    def _now_iso():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        import base64
        raw = (int(datetime.datetime.utcnow().timestamp() * 1000)).to_bytes(6, "big") + os.urandom(10)
        return f"{prefix}_{base64.urlsafe_b64encode(raw).decode('ascii').rstrip('=')}"

    def _append_op(gmail_account_id, status, request, related_gmail_id=None, idempotency_key=None, error=None, response=None):
        ops = _load("remote_operations.json")
        now = _now_iso()
        ops.append({
            "id": _gen_id("gop"),
            "gmail_account_id": gmail_account_id,
            "tool_name": endpoint,
            "request": request if isinstance(request, dict) else {},
            "idempotency_key": idempotency_key,
            "related_object_type": None,
            "related_gmail_id": related_gmail_id,
            "response": response,
            "error": error,
            "attempt_count": 1,
            "status": status,
            "scheduled_at": None,
            "started_at": now if status in ("running", "succeeded", "failed") else None,
            "finished_at": now if status in ("succeeded", "failed", "cancelled") else None,
            "created_at": now,
            "updated_at": now,
        })
        _save("remote_operations.json", ops)

    try:
        if not isinstance(criteria, dict):
            _append_op(None, "failed", {"criteria": criteria, "action": action}, error={"code": "VALIDATION_ERROR", "message": "criteria must be an object"})
            return _err("VALIDATION_ERROR", "criteria must be an object", field="criteria")
        if not isinstance(action, dict):
            _append_op(None, "failed", {"criteria": criteria, "action": action}, error={"code": "VALIDATION_ERROR", "message": "action must be an object"})
            return _err("VALIDATION_ERROR", "action must be an object", field="action")

        # Validate sizeComparison usage
        if "sizeComparison" in criteria and "size" not in criteria:
            _append_op(None, "failed", {"criteria": criteria, "action": action}, error={"code": "VALIDATION_ERROR", "message": "sizeComparison requires size"})
            return _err("VALIDATION_ERROR", "sizeComparison requires size", field="criteria.sizeComparison")

        if "size" in criteria and criteria["size"] is not None and not isinstance(criteria["size"], (int, float)):
            _append_op(None, "failed", {"criteria": criteria, "action": action}, error={"code": "VALIDATION_ERROR", "message": "size must be a number"})
            return _err("VALIDATION_ERROR", "size must be a number", field="criteria.size")

        if "sizeComparison" in criteria and criteria["sizeComparison"] not in ("smaller", "larger"):
            _append_op(None, "failed", {"criteria": criteria, "action": action}, error={"code": "VALIDATION_ERROR", "message": "sizeComparison must be 'smaller' or 'larger'"})
            return _err("VALIDATION_ERROR", "sizeComparison must be 'smaller' or 'larger'", field="criteria.sizeComparison")

        def _validate_label_list(v, field):
            if v is None:
                return None
            if not isinstance(v, list) or any((not isinstance(x, str) or not x.strip()) for x in v):
                return _err("VALIDATION_ERROR", f"{field} must be an array of strings", field=field)
            return [x.strip() for x in v]

        add_ids = _validate_label_list(action.get("addLabelIds"), "action.addLabelIds")
        if isinstance(add_ids, dict) and "error" in add_ids:
            _append_op(None, "failed", {"criteria": criteria, "action": action}, error=add_ids["error"])
            return add_ids
        rm_ids = _validate_label_list(action.get("removeLabelIds"), "action.removeLabelIds")
        if isinstance(rm_ids, dict) and "error" in rm_ids:
            _append_op(None, "failed", {"criteria": criteria, "action": action}, error=rm_ids["error"])
            return rm_ids

        # Resolve a usable gmail_account context: pick any active/token_expired account in store
        accounts = _load("gmail_accounts.json")
        acct = next((a for a in accounts if isinstance(a, dict) and a.get("status") in ("active", "token_expired")), None)
        if not acct:
            _append_op(None, "failed", {"criteria": criteria, "action": action}, error={"code": "UNAUTHORIZED", "message": "No connected Gmail account available for this operation"})
            return _err("UNAUTHORIZED", "No connected Gmail account available for this operation")
        if acct.get("status") in ("revoked", "disabled"):
            _append_op(acct.get("id"), "failed", {"criteria": criteria, "action": action}, error={"code": "UNAUTHORIZED", "message": "Gmail connection is revoked or disabled"})
            return _err("UNAUTHORIZED", "Gmail connection is revoked or disabled")

        gmail_account_id = acct.get("id")

        # Validate label ids exist+active for this account (accept internal id or gmail_label_id)
        labels = _load("labels.json")
        active_labels = [l for l in labels if isinstance(l, dict) and l.get("gmail_account_id") == gmail_account_id and l.get("status") == "active"]
        by_internal = {l.get("id"): l for l in active_labels if l.get("id")}
        by_gmail = {l.get("gmail_label_id"): l for l in active_labels if l.get("gmail_label_id")}

        def _resolve_label(x):
            if x in by_internal:
                return by_internal[x].get("gmail_label_id")
            if x in by_gmail:
                return x
            return None

        resolved_add = []
        for x in (add_ids or []):
            gid = _resolve_label(x)
            if not gid:
                _append_op(gmail_account_id, "failed", {"criteria": criteria, "action": action},
                           error={"code": "NOT_FOUND", "message": f"Label id not found or not active: {x}", "id": x})
                return _err("NOT_FOUND", f"Label id not found or not active: {x}", id=x)
            resolved_add.append(gid)

        resolved_rm = []
        for x in (rm_ids or []):
            gid = _resolve_label(x)
            if not gid:
                _append_op(gmail_account_id, "failed", {"criteria": criteria, "action": action},
                           error={"code": "NOT_FOUND", "message": f"Label id not found or not active: {x}", "id": x})
                return _err("NOT_FOUND", f"Label id not found or not active: {x}", id=x)
            resolved_rm.append(gid)

        # Create settings row (gmail_settings setting_type='filter')
        settings = _load("gmail_settings.json")
        provider_key = _gen_id("flt")  # local natural key representing filterId
        now = _now_iso()
        row = {
            "id": _gen_id("gms"),
            "gmail_account_id": gmail_account_id,
            "setting_type": "filter",
            "provider_key": provider_key,
            "payload": {
                "criteria": dict(criteria),
                "action": {
                    **({} if not isinstance(action, dict) else {k: action.get(k) for k in action.keys()}),
                    "addLabelIds": resolved_add,
                    "removeLabelIds": resolved_rm,
                },
            },
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }

        # Uniqueness: (gmail_account_id, setting_type, provider_key)
        if any(isinstance(s, dict) and s.get("gmail_account_id") == gmail_account_id and s.get("setting_type") == "filter" and s.get("provider_key") == provider_key for s in settings):
            # extremely unlikely, regenerate once
            provider_key = _gen_id("flt")
            row["provider_key"] = provider_key

        settings.append(row)
        _save("gmail_settings.json", settings)

        idem = f"create_filter:{gmail_account_id}:{provider_key}"
        _append_op(gmail_account_id, "queued", {"criteria": criteria, "action": action}, related_gmail_id=provider_key,
                   idempotency_key=idem, response={"accepted": True, "id": provider_key})

        return {"filter": dict(row)}
    except Exception as e:
        _append_op(None, "failed", {"criteria": criteria, "action": action}, error={"code": "CONFLICT", "message": "Internal error", "details": str(e)})
        return _err("CONFLICT", "Internal error", details=str(e))

def delete_filter(id, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0142000" if __import__("os").path.isdir("./environment_mix/0142000") else "/app/database")
    def _load(n):
