            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    endpoint = "delete_filter"

    def _now_iso():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        import base64
        raw = (int(datetime.datetime.utcnow().timestamp() * 1000)).to_bytes(6, "big") + os.urandom(10)
        return f"{prefix}_{base64.urlsafe_b64encode(raw).decode('ascii').rstrip('=')}"

    def _append_op(gmail_account_id, status, request, related_gmail_id=None, idempotency_key=None, error=None, response=None):
        ops = _load("remote_operations.json")
        now = _now_iso()
        ops.append({
            "id": _gen_id("gop"),
            "gmail_account_id": gmail_account_id,
            "tool_name": endpoint,
            "request": request if isinstance(request, dict) else {},
            "idempotency_key": idempotency_key,
            "related_object_type": None,
            "related_gmail_id": related_gmail_id,
            "response": response,
            "error": error,
            "attempt_count": 1,
            "status": status,
            "scheduled_at": None,
            "started_at": now if status in ("running", "succeeded", "failed") else None,
            "finished_at": now if status in ("succeeded", "failed", "cancelled") else None,
            "created_at": now,
            "updated_at": now,
        })
        _save("remote_operations.json", ops)

    try:
        if not isinstance(id, str) or not id.strip():
            _append_op(None, "failed", {"id": id}, error={"code": "VALIDATION_ERROR", "message": "id must be a non-empty string"})
            return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")
        key = id.strip()

        settings = _load("gmail_settings.json")
        accounts = _load("gmail_accounts.json")
        ops = _load("remote_operations.json")

        filt = None
        for s in settings:
            if not isinstance(s, dict):
                continue
            if s.get("setting_type") != "filter":
                continue
            if s.get("id") == key or s.get("provider_key") == key:
                filt = s
                break

        if not filt:
            _append_op(None, "failed", {"id": key}, related_gmail_id=key,
                       error={"code": "NOT_FOUND", "message": "Filter not found", "id": key})
            return _err("NOT_FOUND", "Filter not found", id=key)

        gmail_account_id = filt.get("gmail_account_id")
        acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == gmail_account_id), None)
        if not acct or acct.get("status") not in ("active", "token_expired"):
            _append_op(gmail_account_id, "failed", {"id": key}, related_gmail_id=filt.get("provider_key"),
                       error={"code": "UNAUTHORIZED", "message": "No connected Gmail account available for this operation"})
            return _err("UNAUTHORIZED", "No connected Gmail account available for this operation")
        if acct.get("status") in ("revoked", "disabled"):
            _append_op(gmail_account_id, "failed", {"id": key}, related_gmail_id=filt.get("provider_key"),
                       error={"code": "UNAUTHORIZED", "message": "Gmail connection is revoked or disabled"})
            return _err("UNAUTHORIZED", "Gmail connection is revoked or disabled")

        # Idempotent delete: mark status deleted (allowed transitions: active/pending/disabled -> deleted; deleted terminal)
        if filt.get("status") == "deleted":
            _append_op(gmail_account_id, "succeeded", {"id": key}, related_gmail_id=filt.get("provider_key"),
                       response={"deleted": True, "id": filt.get("provider_key")})
            return {"filter": dict(filt)}

        if filt.get("status") not in ("active", "pending_verification", "disabled"):
            _append_op(gmail_account_id, "failed", {"id": key}, related_gmail_id=filt.get("provider_key"),
                       error={"code": "INVALID_TRANSITION", "message": f"Cannot delete filter from state '{filt.get('status')}'"})
            return _err("INVALID_TRANSITION", f"Cannot delete filter from state '{filt.get('status')}'", from_status=filt.get("status"), to_status="deleted")

        filt["status"] = "deleted"
        filt["updated_at"] = _now_iso()
        _save("gmail_settings.json", settings)

        idem = f"delete_filter:{gmail_account_id}:{filt.get('provider_key')}"
        existing = next((r for r in ops if isinstance(r, dict) and r.get("gmail_account_id") == gmail_account_id and r.get("idempotency_key") == idem), None)
        if not existing:
            _append_op(gmail_account_id, "queued", {"id": key}, related_gmail_id=filt.get("provider_key"),
                       idempotency_key=idem, response={"accepted": True, "id": filt.get("provider_key")})

        return {"filter": dict(filt)}
    except Exception as e:
        _append_op(None, "failed", {"id": id}, related_gmail_id=id,
                   error={"code": "CONFLICT", "message": "Internal error", "details": str(e)})
        return _err("CONFLICT", "Internal error", details=str(e))

def get_filter(id, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0142000" if __import__("os").path.isdir("./environment_mix/0142000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return prefix + "_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("=")

    def _log(gmail_account_id, status, error=None):
        ops = _load("remote_operations.json")
        row = {
            "id": _gen_id("rop"),
            "gmail_account_id": gmail_account_id,
            "tool_name": "get_filter",
            "request": {"id": id},
            "idempotency_key": None,
            "related_object_type": None,
            "related_gmail_id": id if isinstance(id, str) else None,
            "response": None if status != "succeeded" else {"ok": True},
            "error": error,
            "attempt_count": 1,
            "status": status,
            "scheduled_at": None,
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        _save("remote_operations.json", ops)

    def _rate_limit_check(gmail_account_id):
        # Reads: 300/minute per account
        ops = _load("remote_operations.json")
        window_s = 60
        limit = 300
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)

        def _parse_ts(s):
            if not s or not isinstance(s, str): 
                return None
            try:
                if s.endswith("Z"):
                    return datetime.datetime.fromisoformat(s[:-1])
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        count = 0
        for r in ops:
            if r.get("gmail_account_id") != gmail_account_id: 
                continue
            if r.get("tool_name") != "get_filter":
                continue
            ts = _parse_ts(r.get("created_at"))
            if ts and ts >= cutoff:
                count += 1
        return count < limit

    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id is required and must be a non-empty string")
    filter_id = id.strip()

    accounts = _load("gmail_accounts.json")
    acct = None
    for a in accounts:
        if a.get("status") in ("active", "token_expired"):
            acct = a
            break
    if not acct:
        return _err("UNAUTHORIZED", "No valid Gmail connection exists for this user")
    gmail_account_id = acct.get("id")

    if not _rate_limit_check(gmail_account_id):
        _log(gmail_account_id, "failed", error=_err("RATE_LIMIT", "Request quota exceeded")["error"])
        return _err("RATE_LIMIT", "Request quota exceeded")

    settings = _load("gmail_settings.json")
    target = None
    for s in settings:
        if s.get("gmail_account_id") == gmail_account_id and s.get("setting_type") == "filter" and s.get("provider_key") == filter_id:
            target = s
            break

    if not target:
        _log(gmail_account_id, "failed", error=_err("NOT_FOUND", "Filter not found")["error"])
        return _err("NOT_FOUND", "Filter not found")

    _log(gmail_account_id, "succeeded", error=None)
    return {"filter": target, "latency_ms": int((time.time() - t0) * 1000)}

def list_filters(includeDeleted=None, maxResults=None, pageToken=None, q=None, sortBy=None, sortOrder=None, **_extra):
    import json, os, datetime, time, base64, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0142000" if __import__("os").path.isdir("./environment_mix/0142000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, latency_ms=None, error=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            row = {
                "id": "req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
                "endpoint": "list_filters",
                "credential_id": credential_id,
                "status": status,
                "latency_ms": int(latency_ms if latency_ms is not None else (time.time() - t0) * 1000),
                "timestamp": _now()
            }
            if error is not None:
                row["error"] = error
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _enforce_limits():
        # If a request log exists, enforce simple per-minute + per-day limits from it.
        logs = _load("request_logs.json")
        if not isinstance(logs, list) or not logs:
            return None
        now = datetime.datetime.utcnow()
        def _parse_ts(s):
            try:
                if isinstance(s, str) and s.endswith("Z"):
                    return datetime.datetime.fromisoformat(s[:-1])
                if isinstance(s, str):
                    return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
            return None
        last_min = 0
        last_day = 0
        for r in logs[-5000:]:
            ts = _parse_ts(r.get("timestamp"))
            if not ts:
                continue
            dt = now - ts
            if dt.total_seconds() <= 60:
                last_min += 1
            if dt.total_seconds() <= 86400:
                last_day += 1
        # Conservative defaults; only enforced if logs collection exists.
        if last_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded. Try again later.")
        if last_day >= 10000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    limit_err = _enforce_limits()
    if limit_err:
        _log("error", error=limit_err["error"])
        return limit_err

    # Validate params
    if includeDeleted is not None and not isinstance(includeDeleted, bool):
        e = _err("VALIDATION_ERROR", "includeDeleted must be a boolean.")
        _log("error", error=e["error"])
        return e

    if maxResults is None:
        maxResults = 100
    if not isinstance(maxResults, (int, float)) or isinstance(maxResults, bool):
        e = _err("VALIDATION_ERROR", "maxResults must be a number.")
        _log("error", error=e["error"])
        return e
    maxResults = int(maxResults)
    if maxResults < 1 or maxResults > 500:
        e = _err("VALIDATION_ERROR", "maxResults must be between 1 and 500.")
        _log("error", error=e["error"])
        return e

    if pageToken is not None and not isinstance(pageToken, str):
        e = _err("VALIDATION_ERROR", "pageToken must be a string.")
        _log("error", error=e["error"])
        return e

    if q is not None and not isinstance(q, str):
        e = _err("VALIDATION_ERROR", "q must be a string.")
        _log("error", error=e["error"])
        return e

    if sortBy is None:
        sortBy = "updatedAt"
    if sortBy not in ("createdAt", "updatedAt", "providerKey"):
        e = _err("VALIDATION_ERROR", "sortBy must be one of: createdAt, updatedAt, providerKey.")
        _log("error", error=e["error"])
        return e

    if sortOrder is None:
        sortOrder = "desc"
    if sortOrder not in ("asc", "desc"):
        e = _err("VALIDATION_ERROR", "sortOrder must be one of: asc, desc.")
        _log("error", error=e["error"])
        return e

    # Resolve an account context (ambient auth) that can serve reads
    accounts = _load("gmail_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    account = None
    for a in accounts:
        if isinstance(a, dict) and a.get("status") in ("active", "token_expired"):
            account = a
            break
    if not account:
        e = _err("UNAUTHORIZED", "No valid Gmail connection exists for the user.")
        _log("error", error=e["error"])
        return e
    acct_id = account.get("id")

    settings = _load("gmail_settings.json")
    if not isinstance(settings, list):
        settings = []

    rows = []
    for s in settings:
        if not isinstance(s, dict):
            continue
        if s.get("gmail_account_id") != acct_id:
            continue
        if s.get("setting_type") != "filter":
            continue
        st = s.get("status")
        if includeDeleted:
            if st not in ("active", "disabled", "deleted", "pending_verification"):
                continue
        else:
            if st != "active":
                continue
        pk = s.get("provider_key") or ""
        if q:
            if q.lower() not in str(pk).lower():
                continue
        rows.append(s)

    def _sort_key(r):
        if sortBy == "providerKey":
            return (str(r.get("provider_key") or "").lower(), str(r.get("id") or ""))
        if sortBy == "createdAt":
            return (str(r.get("created_at") or ""), str(r.get("id") or ""))
        return (str(r.get("updated_at") or ""), str(r.get("id") or ""))

    rows.sort(key=_sort_key, reverse=(sortOrder == "desc"))

    # Pagination: pageToken as base64url encoded integer offset
    offset = 0
    if pageToken:
        try:
            padded = pageToken + "=" * (-len(pageToken) % 4)
            dec = base64.urlsafe_b64decode(padded.encode("ascii")).decode("utf-8")
            if not re.fullmatch(r"\d+", dec):
                raise ValueError("bad token")
            offset = int(dec)
            if offset < 0:
                offset = 0
        except Exception:
            e = _err("VALIDATION_ERROR", "Invalid pageToken.")
            _log("error", error=e["error"])
            return e

    total = len(rows)
    page = rows[offset:offset + maxResults]
    next_offset = offset + len(page)
    next_token = None
    if next_offset < total:
        next_token = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("ascii").rstrip("=")

    resp = {
        "filters": page,
        "nextPageToken": next_token,
        "resultSizeEstimate": total
    }
    _log("ok", latency_ms=(time.time() - t0) * 1000)
    return resp

def delete_forwarding_address(forwardingEmail, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0142000" if __import__("os").path.isdir("./environment_mix/0142000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    gmail_accounts = _load("gmail_accounts.json")
    gmail_settings = _load("gmail_settings.json")
    remote_ops = _load("remote_operations.json")

    def _log_op(gmail_account_id, request_obj, status, related_gmail_id=None, error=None, response=None, idempotency_key=None, attempt_count=1):
        op_id = "rop_" + uuid.uuid4().hex
        row = {
            "id": op_id,
            "gmail_account_id": gmail_account_id,
            "tool_name": "delete_forwarding_address",
            "request": request_obj,
            "idempotency_key": idempotency_key,
            "related_object_type": None,
            "related_gmail_id": related_gmail_id,
            "response": response,
            "error": error,
            "attempt_count": int(attempt_count),
            "status": status,
            "scheduled_at": None,
            "started_at": now if status in ("running", "succeeded", "failed") else None,
            "finished_at": now if status in ("succeeded", "failed", "cancelled") else None,
            "created_at": now,
            "updated_at": now,
        }
        remote_ops.append(row)
        _save("remote_operations.json", remote_ops)
        return row

    def _pick_account_for_call():
        # Ambient auth: find any account that can serve the request.
        # For mutating tools, reject revoked/disabled.
        # Also require an active-ish connection: active or token_expired (can be retried via refresh).
        eligible = []
        for a in gmail_accounts:
            if not isinstance(a, dict):
                continue
            st = a.get("status")
            if st in ("revoked", "disabled"):
                continue
            if st in ("active", "token_expired"):
                eligible.append(a)
        # Prefer active over token_expired
        for st in ("active", "token_expired"):
            for a in eligible:
                if a.get("status") == st:
                    return a
        return None

    # Validate input
    if not isinstance(forwardingEmail, str) or not forwardingEmail.strip():
        return _err("VALIDATION_ERROR", "forwardingEmail is required and must be a non-empty string.", field="forwardingEmail")
    forwardingEmail = forwardingEmail.strip()
    # Basic email pattern check (not fully RFC, but catches obvious invalid)
    if not re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", forwardingEmail):
        return _err("VALIDATION_ERROR", "forwardingEmail must be a valid email address.", field="forwardingEmail")

    acct = _pick_account_for_call()
    if not acct:
        return _err("UNAUTHORIZED", "No valid Gmail connection exists for this operation.")

    gmail_account_id = acct.get("id")
    if not gmail_account_id:
        return _err("UNAUTHORIZED", "No valid Gmail connection exists for this operation.")

    # Enforce mutating tool rule: revoked/disabled rejected (already filtered, but keep explicit)
    if acct.get("status") in ("revoked", "disabled"):
        return _err("UNAUTHORIZED", "Gmail connection is not permitted to perform mutations in its current status.", status=acct.get("status"))

    # Find forwarding_address settings row
    target = None
    for s in gmail_settings:
        if not isinstance(s, dict):
            continue
        if s.get("gmail_account_id") == gmail_account_id and s.get("setting_type") == "forwarding_address":
            payload = s.get("payload") or {}
            if s.get("provider_key") == forwardingEmail or payload.get("forwardingEmail") == forwardingEmail:
                target = s
                break

    if not target:
        # mutation that matched no row must not report success
        # also record remote op attempt? real backend usually wouldn't enqueue deletion for unknown address.
        # We'll not enqueue; return NOT_FOUND.
        return _err("NOT_FOUND", "Forwarding address not found.", forwardingEmail=forwardingEmail)

    # Idempotency: if already deleted, be idempotent but still record remote op as succeeded (no-op) once per key
    idempotency_key = "delete_forwarding_address:" + gmail_account_id + ":" + forwardingEmail.lower()

    # If an operation with same idempotency key already succeeded/queued/running, do not execute twice.
    existing = None
    for op in remote_ops:
        if isinstance(op, dict) and op.get("gmail_account_id") == gmail_account_id and op.get("idempotency_key") == idempotency_key:
            existing = op
            break
    if existing and existing.get("status") in ("queued", "running", "succeeded"):
        # Return current cached state (after whatever was done/queued)
        # Ensure body payload returned as-is.
        latency_ms = int((time.time() - t0) * 1000)
        return {
            "forwarding_address": target,
            "remote_operation": {
                "id": existing.get("id"),
                "status": existing.get("status"),
                "attempt_count": existing.get("attempt_count"),
                "idempotency_key": existing.get("idempotency_key"),
            },
            "meta": {"latency_ms": latency_ms}
        }

    # Update local cache: mark as deleted (or disabled); schema allows disabled/deleted, but rule says deleted/disabled.
    # We'll use 'deleted' (terminal) to align with removal semantics.
    current_status = target.get("status")
    if current_status == "deleted":
        # Already deleted: still enqueue at most once; existing succeeded handled above; record succeeded no-op.
        op = _log_op(
            gmail_account_id=gmail_account_id,
            request_obj={"forwardingEmail": forwardingEmail},
            status="succeeded",
            related_gmail_id=forwardingEmail,
            response={"noop": True, "message": "Forwarding address already marked deleted in cache."},
            idempotency_key=idempotency_key,
            attempt_count=1
        )
        latency_ms = int((time.time() - t0) * 1000)
        return {
            "forwarding_address": target,
            "remote_operation": {"id": op.get("id"), "status": op.get("status"), "attempt_count": op.get("attempt_count"), "idempotency_key": op.get("idempotency_key")},
            "meta": {"latency_ms": latency_ms}
        }

    # Validate transition for gmail_settings lifecycle: active/pending_verification/disabled -> deleted allowed; deleted -> none.
    allowed = {
        "active": ["disabled", "deleted", "pending_verification"],
        "pending_verification": ["active", "deleted"],
        "disabled": ["active", "deleted"],
        "deleted": []
    }
    if current_status not in allowed:
        return _err("VALIDATION_ERROR", "Invalid current status for forwarding address setting.", status=current_status)
    if "deleted" not in allowed.get(current_status, []):
        return _err("INVALID_TRANSITION", "Cannot delete forwarding address from current status.", from_status=current_status, to_status="deleted")

    # Perform local mutation
    target["status"] = "deleted"
    target["updated_at"] = now

    # Persist settings
    _save("gmail_settings.json", gmail_settings)

    # Enqueue remote operation: queued (execution is out-of-band)
    op = _log_op(
        gmail_account_id=gmail_account_id,
        request_obj={"forwardingEmail": forwardingEmail},
        status="queued",
        related_gmail_id=forwardingEmail,
        response=None,
        error=None,
        idempotency_key=idempotency_key,
        attempt_count=0
    )

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "forwarding_address": target,
        "remote_operation": {
            "id": op.get("id"),
            "status": op.get("status"),
            "attempt_count": op.get("attempt_count"),
            "idempotency_key": op.get("idempotency_key"),
        },
        "meta": {"latency_ms": latency_ms}
    }

