    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0142000" if __import__("os").path.isdir("./environment_mix/0142000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(gmail_account_id, status, error=None):
        ops = _load("remote_operations.json")
        op = {
            "id": "op_" + hashlib.sha256(f"{now}|list_forwarding_addresses|{gmail_account_id}|{time.time()}".encode("utf-8")).hexdigest()[:24],
            "gmail_account_id": gmail_account_id,
            "tool_name": "list_forwarding_addresses",
            "request": {"maxResults": maxResults, "pageToken": pageToken},
            "idempotency_key": None,
            "related_object_type": None,
            "related_gmail_id": None,
            "response": None,
            "error": error,
            "attempt_count": 1,
            "status": status,
            "scheduled_at": None,
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        ops.append(op)
        _save("remote_operations.json", ops)

    # Validate inputs
    if maxResults is None:
        maxr = 100
    else:
        if not isinstance(maxResults, (int, float)) or isinstance(maxResults, bool):
            _log("unknown", "failed", {"code": "VALIDATION_ERROR", "message": "maxResults must be a number."})
            return _err("VALIDATION_ERROR", "maxResults must be a number.")
        if int(maxResults) != maxResults:
            _log("unknown", "failed", {"code": "VALIDATION_ERROR", "message": "maxResults must be an integer."})
            return _err("VALIDATION_ERROR", "maxResults must be an integer.")
        maxr = int(maxResults)
        if maxr < 1 or maxr > 500:
            _log("unknown", "failed", {"code": "VALIDATION_ERROR", "message": "maxResults must be between 1 and 500."})
            return _err("VALIDATION_ERROR", "maxResults must be between 1 and 500.")

    if pageToken is not None and not isinstance(pageToken, str):
        _log("unknown", "failed", {"code": "VALIDATION_ERROR", "message": "pageToken must be a string."})
        return _err("VALIDATION_ERROR", "pageToken must be a string.")

    # Resolve an authorized gmail_account context (ambient auth)
    accts = _load("gmail_accounts.json")
    acct = None
    for a in accts:
        if a.get("status") in ("active", "token_expired"):
            acct = a
            break
    if not acct:
        _log("unknown", "failed", {"code": "UNAUTHORIZED", "message": "No authorized Gmail connection exists."})
        return _err("UNAUTHORIZED", "No authorized Gmail connection exists.")

    gmail_account_id = acct["id"]

    settings = _load("gmail_settings.json")
    rows = [s for s in settings
            if s.get("gmail_account_id") == gmail_account_id
            and s.get("setting_type") == "forwarding_address"
            and s.get("status") in ("active", "pending_verification")]

    # Stable order by provider_key/email
    rows.sort(key=lambda r: (str(r.get("provider_key") or ""), str(r.get("id") or "")))

    # Pagination token: base64url of {"o": <offset>, "a": <acct_id>}
    offset = 0
    if pageToken:
        try:
            pad = "=" * (-len(pageToken) % 4)
            decoded = base64.urlsafe_b64decode((pageToken + pad).encode("utf-8")).decode("utf-8")
            tok = json.loads(decoded)
            if not isinstance(tok, dict) or "o" not in tok or "a" not in tok:
                _log(gmail_account_id, "failed", {"code": "VALIDATION_ERROR", "message": "Malformed pageToken."})
                return _err("VALIDATION_ERROR", "Malformed pageToken.")
            if tok.get("a") != gmail_account_id:
                _log(gmail_account_id, "failed", {"code": "NOT_FOUND", "message": "Supplied pageToken does not exist."})
                return _err("NOT_FOUND", "Supplied pageToken does not exist.")
            o = tok.get("o")
            if not isinstance(o, int) or o < 0:
                _log(gmail_account_id, "failed", {"code": "VALIDATION_ERROR", "message": "Malformed pageToken."})
                return _err("VALIDATION_ERROR", "Malformed pageToken.")
            offset = o
        except (ValueError, json.JSONDecodeError, base64.binascii.Error, UnicodeDecodeError):
            _log(gmail_account_id, "failed", {"code": "VALIDATION_ERROR", "message": "Malformed pageToken."})
            return _err("VALIDATION_ERROR", "Malformed pageToken.")

        if offset > len(rows):
            _log(gmail_account_id, "failed", {"code": "NOT_FOUND", "message": "Supplied pageToken does not exist."})
            return _err("NOT_FOUND", "Supplied pageToken does not exist.")

    page = rows[offset:offset + maxr]
    next_offset = offset + len(page)
    nextPageToken = None
    if next_offset < len(rows):
        tok = {"o": next_offset, "a": gmail_account_id}
        enc = base64.urlsafe_b64encode(json.dumps(tok, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")
        nextPageToken = enc

    # Return Gmail-like shape: forwardingAddresses list of payloads
    forwardingAddresses = []
    for r in page:
        payload = r.get("payload") if isinstance(r.get("payload"), dict) else {}
        forwardingAddresses.append(payload)

    resp = {
        "forwardingAddresses": forwardingAddresses,
        "nextPageToken": nextPageToken,
        "resultSizeEstimate": len(rows),
    }
    _log(gmail_account_id, "succeeded", None)
    return resp

