        return op

    # Validate inputs
    if not _email_ok(sendAsEmail):
        _log("unknown", "failed", {"sendAsEmail": sendAsEmail}, None, {"code": "VALIDATION_ERROR", "message": "sendAsEmail is missing or invalid."})
        return _err("VALIDATION_ERROR", "sendAsEmail is missing or invalid.")

    if displayName is not None and not isinstance(displayName, str):
        return _err("VALIDATION_ERROR", "displayName must be a string.")
    if replyToAddress is not None and not _email_ok(replyToAddress):
        return _err("VALIDATION_ERROR", "replyToAddress is invalid.")
    if signature is not None and not isinstance(signature, str):
        return _err("VALIDATION_ERROR", "signature must be a string.")
    if isPrimary is not None and not isinstance(isPrimary, bool):
        return _err("VALIDATION_ERROR", "isPrimary must be a boolean.")
    if treatAsAlias is not None and not isinstance(treatAsAlias, bool):
