        return _err("UNAUTHORIZED", "Gmail connection is not permitted for mutations.")

    settings = _load("gmail_settings.json")

    # Conflict if existing send_as with same provider_key
    for s in settings:
        if s.get("gmail_account_id") == gmail_account_id and s.get("setting_type") == "send_as" and s.get("provider_key") == sendAsEmail and s.get("status") != "deleted":
            _log(gmail_account_id, "failed", {"sendAsEmail": sendAsEmail}, None, {"code": "CONFLICT", "message": "Send-as alias already exists."}, related=sendAsEmail)
            return _err("CONFLICT", "Send-as alias already exists.")

    # Single-primary invariant: if new isPrimary true, demote others (active only)
    if isPrimary is True:
        changed = False
        for s in settings:
            if s.get("gmail_account_id") == gmail_account_id and s.get("setting_type") == "send_as" and s.get("status") == "active":
                payload = s.get("payload") if isinstance(s.get("payload"), dict) else {}
                if payload.get("isPrimary") is True:
                    payload["isPrimary"] = False
                    s["payload"] = payload
                    s["updated_at"] = now
                    changed = True
        if changed:
            _save("gmail_settings.json", settings)
            settings = _load("gmail_settings.json")

    # Create settings row
    payload = {
        "sendAsEmail": sendAsEmail,
        "displayName": displayName if displayName is not None else "",
        "replyToAddress": replyToAddress,
        "signature": signature,
        "isPrimary": bool(isPrimary) if isPrimary is not None else False,
        "treatAsAlias": True if treatAsAlias is None else bool(treatAsAlias),
    }
    # Normalize: keep required provider_key equality
