    # Idempotency key: unique per account+sendAsEmail
    idem_key = "create_send_as:" + sendAsEmail.lower()

    # Ensure remote_operations unique constraint: if exists, do not enqueue twice
    ops = _load("remote_operations.json")
    for op in ops:
        if op.get("gmail_account_id") == gmail_account_id and op.get("idempotency_key") == idem_key:
