            return {"sendAs": row}

    _log(
        gmail_account_id,
        "queued",
        {"sendAsEmail": sendAsEmail, "displayName": displayName, "replyToAddress": replyToAddress, "signature": signature, "isPrimary": isPrimary, "treatAsAlias": treatAsAlias},
        response_obj=None,
        error=None,
        idem_key=idem_key,
        related=sendAsEmail
    )

