def list_send_as(maxResults=None, pageToken=None, **_extra):
    import json, os, datetime, time, re, uuid, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0142000" if __import__("os").path.isdir("./environment_mix/0142000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(gmail_account_id, tool_name, status, credential_used, error=None, meta=None):
        ops = _load("remote_operations.json")
        op = {
            "id": "op_" + uuid.uuid4().hex,
            "gmail_account_id": gmail_account_id,
            "tool_name": tool_name,
            "request": {"maxResults": maxResults, "pageToken": pageToken},
            "idempotency_key": None,
            "related_object_type": None,
            "related_gmail_id": None,
            "response": meta if status in ("succeeded",) else None,
            "error": error,
            "attempt_count": 1,
            "status": status,
            "scheduled_at": None,
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(op)
        _save("remote_operations.json", ops)

    # Resolve an authenticated/connected account context (ambient auth)
    accounts = _load("gmail_accounts.json")
    if not isinstance(accounts, list):
        return _err("UNAUTHORIZED", "No Gmail accounts available.")
    # For reads, any non-revoked/disabled account is usable; prefer active then token_expired.
    acct = None
    for st in ("active", "token_expired"):
        for a in accounts:
            if isinstance(a, dict) and a.get("status") == st:
                acct = a
                break
        if acct:
            break
    if not acct:
        # If only revoked/disabled exist, still unauthorized for access to Gmail cache.
        _log("unknown", "list_send_as", "failed", None, error={"code": "UNAUTHORIZED", "message": "No authorized Gmail connection found."})
        return _err("UNAUTHORIZED", "No authorized Gmail connection found.")

    # Validate paging params
    if maxResults is None:
        max_n = 100
    else:
        if not isinstance(maxResults, (int, float)) or isinstance(maxResults, bool):
            _log(acct["id"], "list_send_as", "failed", None, error={"code": "VALIDATION_ERROR", "message": "maxResults must be a number between 1 and 500."})
            return _err("VALIDATION_ERROR", "maxResults must be a number between 1 and 500.")
        if int(maxResults) != maxResults:
            _log(acct["id"], "list_send_as", "failed", None, error={"code": "VALIDATION_ERROR", "message": "maxResults must be an integer between 1 and 500."})
            return _err("VALIDATION_ERROR", "maxResults must be an integer between 1 and 500.")
        max_n = int(maxResults)
        if max_n < 1 or max_n > 500:
            _log(acct["id"], "list_send_as", "failed", None, error={"code": "VALIDATION_ERROR", "message": "maxResults must be between 1 and 500."})
            return _err("VALIDATION_ERROR", "maxResults must be between 1 and 500.")

    if pageToken is not None and not isinstance(pageToken, str):
        _log(acct["id"], "list_send_as", "failed", None, error={"code": "VALIDATION_ERROR", "message": "pageToken must be a string."})
        return _err("VALIDATION_ERROR", "pageToken must be a string.")

    settings = _load("gmail_settings.json")
    if not isinstance(settings, list):
        _log(acct["id"], "list_send_as", "failed", None, error={"code": "NOT_FOUND", "message": "Send-as settings not found."})
        return _err("NOT_FOUND", "Send-as settings not found.")

    # Fetch send_as rows for this account (active/pending/disabled; exclude deleted)
    rows = []
    for s in settings:
        if not isinstance(s, dict):
            continue
        if s.get("gmail_account_id") != acct.get("id"):
            continue
        if s.get("setting_type") != "send_as":
            continue
        if s.get("status") == "deleted":
            continue
        payload = s.get("payload")
        if isinstance(payload, dict):
            rows.append(payload)
        else:
            # keep minimal shape
            rows.append({"sendAsEmail": s.get("provider_key")})

    # If there are no send-as settings cached for this account, return NOT_FOUND per tool description
    if len(rows) == 0:
        _log(acct["id"], "list_send_as", "failed", None, error={"code": "NOT_FOUND", "message": "Send-as settings have not been synced for this account."})
        return _err("NOT_FOUND", "Send-as settings have not been synced for this account.")

    # Deterministic ordering: primary first, then sendAsEmail
    def _key(p):
        is_primary = False
        if isinstance(p, dict):
            is_primary = bool(p.get("isPrimary"))
            email = p.get("sendAsEmail") or ""
        else:
            email = ""
        return (0 if is_primary else 1, str(email).lower())

    rows.sort(key=_key)

    # Pagination via pageToken as integer offset (opaque in real API; here cached)
    offset = 0
    if pageToken:
        if not re.fullmatch(r"\d+", pageToken):
            _log(acct["id"], "list_send_as", "failed", None, error={"code": "VALIDATION_ERROR", "message": "Invalid pageToken."})
            return _err("VALIDATION_ERROR", "Invalid pageToken.")
        offset = int(pageToken)
        if offset < 0 or offset > len(rows):
            _log(acct["id"], "list_send_as", "failed", None, error={"code": "VALIDATION_ERROR", "message": "Invalid pageToken."})
            return _err("VALIDATION_ERROR", "Invalid pageToken.")

    page = rows[offset:offset + max_n]
    next_offset = offset + len(page)
    next_token = str(next_offset) if next_offset < len(rows) else None

    resp = {
        "sendAs": page,
        "resultSizeEstimate": len(rows),
        "nextPageToken": next_token,
    }
    _log(acct["id"], "list_send_as", "succeeded", None, meta={"latency_ms": int((time.time() - t0) * 1000)})
    return resp

def patch_send_as(sendAsEmail, displayName=None, replyToAddress=None, signature=None, isPrimary=None, treatAsAlias=None, **_extra):
    import json, os, datetime, time, re, uuid, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0142000" if __import__("os").path.isdir("./environment_mix/0142000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _new_op_id():
        return "op_" + uuid.uuid4().hex

    def _make_idempotency_key(tool, acct_id, target, body):
        h = hashlib.sha256()
        h.update((tool + "|" + acct_id + "|" + str(target) + "|" + json.dumps(body, sort_keys=True, ensure_ascii=False)).encode("utf-8"))
        return "idem_" + h.hexdigest()

    def _enqueue_remote_op(acct_id, tool, req, idem_key, related_gmail_id, status, error=None, response=None):
        ops = _load("remote_operations.json")
        # idempotency: if same key exists, do not execute twice; return existing op/result
        existing = None
        if idem_key is not None:
            for o in ops:
                if isinstance(o, dict) and o.get("gmail_account_id") == acct_id and o.get("idempotency_key") == idem_key:
                    existing = o
                    break
        if existing:
            return existing, True

        op = {
            "id": _new_op_id(),
            "gmail_account_id": acct_id,
            "tool_name": tool,
            "request": req,
            "idempotency_key": idem_key,
            "related_object_type": None,
            "related_gmail_id": related_gmail_id,
            "response": response,
            "error": error,
            "attempt_count": 1,
            "status": status,
            "scheduled_at": None,
            "started_at": now,
            "finished_at": now if status in ("succeeded", "failed", "cancelled") else None,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(op)
        _save("remote_operations.json", ops)
        return op, False

    # Resolve account context for mutation: must be active or token_expired, but revoked/disabled rejected for mutations
    accounts = _load("gmail_accounts.json")
    acct = None
    for st in ("active", "token_expired"):
        for a in accounts:
            if isinstance(a, dict) and a.get("status") == st:
                acct = a
                break
        if acct:
            break
    if not acct:
        op, _ = _enqueue_remote_op("unknown", "patch_send_as", {"sendAsEmail": sendAsEmail}, None, sendAsEmail, "failed",
                                  error={"code": "UNAUTHORIZED", "message": "No authorized Gmail connection found."})
        return _err("UNAUTHORIZED", "No authorized Gmail connection found.")
    if acct.get("status") in ("revoked", "disabled"):
        op, _ = _enqueue_remote_op(acct["id"], "patch_send_as", {"sendAsEmail": sendAsEmail}, None, sendAsEmail, "failed",
                                  error={"code": "UNAUTHORIZED", "message": "Gmail connection is not permitted to modify settings."})
        return _err("UNAUTHORIZED", "Gmail connection is not permitted to modify settings.")

    # Validate inputs
    if not isinstance(sendAsEmail, str) or not sendAsEmail or "@" not in sendAsEmail:
        _enqueue_remote_op(acct["id"], "patch_send_as", {"sendAsEmail": sendAsEmail}, None, None, "failed",
                           error={"code": "VALIDATION_ERROR", "message": "sendAsEmail is required and must be a valid email string."})
        return _err("VALIDATION_ERROR", "sendAsEmail is required and must be a valid email string.")

    updatable = {}
    if displayName is not None:
        if not isinstance(displayName, str):
            _enqueue_remote_op(acct["id"], "patch_send_as", {"sendAsEmail": sendAsEmail}, None, sendAsEmail, "failed",
                               error={"code": "VALIDATION_ERROR", "message": "displayName must be a string."})
            return _err("VALIDATION_ERROR", "displayName must be a string.")
        updatable["displayName"] = displayName
    if replyToAddress is not None:
        if not isinstance(replyToAddress, str):
            _enqueue_remote_op(acct["id"], "patch_send_as", {"sendAsEmail": sendAsEmail}, None, sendAsEmail, "failed",
                               error={"code": "VALIDATION_ERROR", "message": "replyToAddress must be a string."})
