            "updated_at": now,
        }
        ops.append(op)
        _save("remote_operations.json", ops)
        return op, False

    # Resolve connected account (read/mutation: this is a mutating tool -> reject revoked/disabled)
    accounts = _load("gmail_accounts.json")
    acct = None
    for st in ("active", "token_expired"):
        for a in accounts:
            if isinstance(a, dict) and a.get("status") == st:
