                           error={"code": "NOT_FOUND", "message": "Send-as alias not found."})
        return _err("NOT_FOUND", "Send-as alias not found.")

    row = None
    for s in settings:
        if isinstance(s, dict) and s.get("gmail_account_id") == acct["id"] and s.get("setting_type") == "send_as" and s.get("provider_key") == sendAsEmail and s.get("status") != "deleted":
            row = s
            break
    if not row:
        _enqueue_remote_op(acct["id"], "verify_send_as", {"sendAsEmail": sendAsEmail}, None, sendAsEmail, "failed",
                           error={"code": "NOT_FOUND", "message": "Send-as alias does not exist."})
        return _err("NOT_FOUND", "Send-as alias does not exist.")

    # Conflict rules: already pending verification (or already active but treated as verified)
    st = row.get("status")
    if st == "pending_verification":
        _enqueue_remote_op(acct["id"], "verify_send_as", {"sendAsEmail": sendAsEmail}, None, sendAsEmail, "failed",
                           error={"code": "CONFLICT", "message": "Send-as alias is already pending verification."})
        return _err("CONFLICT", "Send-as alias is already pending verification.")
    if st == "deleted":
        _enqueue_remote_op(acct["id"], "verify_send_as", {"sendAsEmail": sendAsEmail}, None, sendAsEmail, "failed",
                           error={"code": "NOT_FOUND", "message": "Send-as alias does not exist."})
        return _err("NOT_FOUND", "Send-as alias does not exist.")
    # If disabled, allow verification request (will move to pending_verification)
    # If active, some systems don't require; treat as conflict (not eligible) per tool description examples
    if st == "active":
        _enqueue_remote_op(acct["id"], "verify_send_as", {"sendAsEmail": sendAsEmail}, None, sendAsEmail, "failed",
                           error={"code": "CONFLICT", "message": "Send-as alias is already active and not eligible for verification."})
        return _err("CONFLICT", "Send-as alias is already active and not eligible for verification.")

    # Enforce lifecycle transition per business rule: verify_send_as -> pending_verification until sync marks active
    # Allowed transitions include disabled->active or ->deleted; but we need disabled->pending_verification or active->pending_verification allowed by schema.
    # Schema allows disabled -> active/deleted, active -> pending_verification. For disabled, we still mark pending_verification per business rule.
    # If schema doesn't allow, return INVALID_TRANSITION.
    allowed = {
        "active": ["disabled", "deleted", "pending_verification"],
        "pending_verification": ["active", "deleted"],
        "disabled": ["active", "deleted"],
        "deleted": [],
    }
    if st not in allowed or "pending_verification" not in allowed.get(st, []):
        # Special-case: if disabled, schema disallows pending_verification; enforce INVALID_TRANSITION rather than violating schema.
        _enqueue_remote_op(acct["id"], "verify_send_as", {"sendAsEmail": sendAsEmail}, None, sendAsEmail, "failed",
                           error={"code": "INVALID_TRANSITION", "message": f"Cannot transition send_as from {st} to pending_verification."})
        return _err("INVALID_TRANSITION", f"Cannot transition send_as from {st} to pending_verification.")

    row["status"] = "pending_verification"
    row["updated_at"] = now
    _save("gmail_settings.json", settings)

    idem_key = _make_idempotency_key("verify_send_as", acct["id"], sendAsEmail)
    _enqueue_remote_op(acct["id"], "verify_send_as", {"sendAsEmail": sendAsEmail}, idem_key, sendAsEmail, "queued",
                       response={"accepted": True, "latency_ms": int((time.time() - t0) * 1000)})

    return {}

def delete_smime_info(sendAsEmail, id, **_extra):
