        now = _now_iso()
        ops.append({
            "id": _gen_id("gop"),
            "gmail_account_id": gmail_account_id,
            "tool_name": endpoint,
            "request": request if isinstance(request, dict) else {},
            "idempotency_key": idempotency_key,
            "related_object_type": None,
            "related_gmail_id": related_gmail_id,
            "response": response,
            "error": error,
            "attempt_count": 1,
            "status": status,
            "scheduled_at": None,
            "started_at": now if status in ("running", "succeeded", "failed") else None,
            "finished_at": now if status in ("succeeded", "failed", "cancelled") else None,
            "created_at": now,
            "updated_at": now,
        })
        _save("remote_operations.json", ops)

    try:
        if not isinstance(sendAsEmail, str) or not sendAsEmail.strip():
            _append_op(None, "failed", {"sendAsEmail": sendAsEmail, "id": id}, error={"code": "VALIDATION_ERROR", "message": "sendAsEmail must be a non-empty string"})
            return _err("VALIDATION_ERROR", "sendAsEmail must be a non-empty string", field="sendAsEmail")
        if not isinstance(id, str) or not id.strip():
            _append_op(None, "failed", {"sendAsEmail": sendAsEmail, "id": id}, error={"code": "VALIDATION_ERROR", "message": "id must be a non-empty string"})
            return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")

        sendAsEmail = sendAsEmail.strip()
        smime_id = id.strip()

        settings = _load("gmail_settings.json")
        accounts = _load("gmail_accounts.json")
        ops = _load("remote_operations.json")

        # Find smime_info row by provider_key or internal id, and match sendAsEmail in payload
        row = None
        for s in settings:
            if not isinstance(s, dict):
                continue
            if s.get("setting_type") != "smime_info":
                continue
            payload = s.get("payload") if isinstance(s.get("payload"), dict) else {}
            if payload.get("sendAsEmail") != sendAsEmail:
                continue
            if s.get("id") == smime_id or s.get("provider_key") == smime_id:
                row = s
                break

        if not row:
            _append_op(None, "failed", {"sendAsEmail": sendAsEmail, "id": smime_id}, related_gmail_id=smime_id,
                       error={"code": "NOT_FOUND", "message": "S/MIME info not found", "sendAsEmail": sendAsEmail, "id": smime_id})
            return _err("NOT_FOUND", "S/MIME info not found", sendAsEmail=sendAsEmail, id=smime_id)

