            _append_op(gmail_account_id, "failed", {"sendAsEmail": sendAsEmail, "id": smime_id}, related_gmail_id=smime_id,
                       error={"code": "UNAUTHORIZED", "message": "No connected Gmail account available for this operation"})
            return _err("UNAUTHORIZED", "No connected Gmail account available for this operation")
        if acct.get("status") in ("revoked", "disabled"):
            _append_op(gmail_account_id, "failed", {"sendAsEmail": sendAsEmail, "id": smime_id}, related_gmail_id=smime_id,
                       error={"code": "UNAUTHORIZED", "message": "Gmail connection is revoked or disabled"})
            return _err("UNAUTHORIZED", "Gmail connection is revoked or disabled")

        # Mark row deleted (allowed by lifecycle)
        if row.get("status") != "deleted":
            if row.get("status") not in ("active", "pending_verification", "disabled"):
                _append_op(gmail_account_id, "failed", {"sendAsEmail": sendAsEmail, "id": smime_id}, related_gmail_id=smime_id,
                           error={"code": "INVALID_TRANSITION", "message": f"Cannot delete smime_info from state '{row.get('status')}'"})
                return _err("INVALID_TRANSITION", f"Cannot delete smime_info from state '{row.get('status')}'", from_status=row.get("status"), to_status="deleted")
            row["status"] = "deleted"
            row["updated_at"] = _now_iso()
            _save("gmail_settings.json", settings)

        idem = f"delete_smime_info:{gmail_account_id}:{sendAsEmail}:{row.get('provider_key')}"
        existing = next((r for r in ops if isinstance(r, dict) and r.get("gmail_account_id") == gmail_account_id and r.get("idempotency_key") == idem), None)
        if not existing:
            _append_op(gmail_account_id, "queued", {"sendAsEmail": sendAsEmail, "id": smime_id},
                       related_gmail_id=row.get("provider_key"), idempotency_key=idem,
                       response={"accepted": True, "sendAsEmail": sendAsEmail, "id": row.get("provider_key")})

        return {"deleted": True, "sendAsEmail": sendAsEmail, "id": row.get("provider_key")}
    except Exception as e:
        _append_op(None, "failed", {"sendAsEmail": sendAsEmail, "id": id}, related_gmail_id=id,
                   error={"code": "CONFLICT", "message": "Internal error", "details": str(e)})
        return _err("CONFLICT", "Internal error", details=str(e))

def get_smime_info(sendAsEmail, id, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0142000" if __import__("os").path.isdir("./environment_mix/0142000") else "/app/database")

    def _load(n):
