        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate inputs
    if not isinstance(sendAsEmail, str) or not sendAsEmail.strip():
        return _err("VALIDATION_ERROR", "sendAsEmail is required and must be a non-empty string.")
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id is required and must be a non-empty string.")
    sendAsEmail = sendAsEmail.strip()
    smime_id = id.strip()

    gmail_accounts = _load("gmail_accounts.json")
    if not isinstance(gmail_accounts, list):
        return _err("CONFLICT", "Datastore corrupted: gmail_accounts is not a list.")
    acct = None
    for a in gmail_accounts:
        if isinstance(a, dict) and a.get("status") in ("active", "token_expired", "revoked", "disabled"):
            # For reads, any existing account context is acceptable; but must be a "connected" account.
            # Treat revoked/disabled as not connected for UNAUTHORIZED.
            if a.get("status") in ("active", "token_expired"):
                acct = a
                break
    if acct is None:
        return _err("UNAUTHORIZED", "No connected Gmail account is available for this operation.")

    settings = _load("gmail_settings.json")
    if not isinstance(settings, list):
        return _err("CONFLICT", "Datastore corrupted: gmail_settings is not a list.")

    # Ensure send-as alias exists
    send_as_row = None
    for s in settings:
        if not isinstance(s, dict):
            continue
        if s.get("gmail_account_id") != acct.get("id"):
            continue
        if s.get("setting_type") == "send_as" and s.get("provider_key") == sendAsEmail and s.get("status") != "deleted":
            send_as_row = s
            break
    if send_as_row is None:
        return _err("NOT_FOUND", "Send-as alias not found.", sendAsEmail=sendAsEmail)

    # Find S/MIME config
    target = None
    for s in settings:
        if not isinstance(s, dict):
            continue
        if s.get("gmail_account_id") != acct.get("id"):
            continue
        if s.get("setting_type") != "smime_info":
            continue
        if s.get("provider_key") != smime_id:
            continue
        payload = s.get("payload")
        if not isinstance(payload, dict) or payload.get("sendAsEmail") != sendAsEmail:
            continue
        if s.get("status") == "deleted":
            continue
        target = s
        break

    if target is None:
        return _err("NOT_FOUND", "S/MIME configuration not found.", sendAsEmail=sendAsEmail, id=smime_id)

    # Return the cached S/MIME config object (payload plus id)
    payload = target.get("payload") if isinstance(target.get("payload"), dict) else {}
    result = dict(payload)
    result["id"] = target.get("provider_key")
    result["sendAsEmail"] = sendAsEmail

    return {"result": result}

def insert_smime_info(sendAsEmail, encryptedKeyPassword, pkcs12, **_extra):
    import json, os, datetime, uuid, hashlib, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0142000" if __import__("os").path.isdir("./environment_mix/0142000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _record_op(gmail_account_id, tool_name, request_obj, related_object_type=None, related_gmail_id=None, status="queued", idempotency_key=None, response=None, error=None, attempt_inc=False):
        ops = _load("remote_operations.json")
        now = _now()
        if idempotency_key is not None:
            for op in ops:
                if op.get("gmail_account_id") == gmail_account_id and op.get("idempotency_key") == idempotency_key:
                    return op, ops, True
        op_id = _gen_id("rop")
        op = {
            "id": op_id,
            "gmail_account_id": gmail_account_id,
            "tool_name": tool_name,
            "request": request_obj,
            "idempotency_key": idempotency_key,
            "related_object_type": related_object_type,
            "related_gmail_id": related_gmail_id,
            "response": response,
            "error": error,
            "attempt_count": 1 if attempt_inc else 0,
            "status": status,
            "scheduled_at": None,
            "started_at": None,
            "finished_at": None,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(op)
        return op, ops, False

    # Validate inputs
    if not isinstance(sendAsEmail, str) or not sendAsEmail.strip():
        return _err("VALIDATION_ERROR", "sendAsEmail is required and must be a non-empty string.")
    if not isinstance(encryptedKeyPassword, str) or not encryptedKeyPassword:
        return _err("VALIDATION_ERROR", "encryptedKeyPassword is required and must be a non-empty string.")
    if not isinstance(pkcs12, str) or not pkcs12:
        return _err("VALIDATION_ERROR", "pkcs12 is required and must be a non-empty string.")
    sendAsEmail = sendAsEmail.strip()

    # Best-effort acceptability check for pkcs12:
    # Gmail expects base64url-ish string in many APIs; we accept base64/base64url characters, moderate size.
    if len(pkcs12) < 16:
        return _err("VALIDATION_ERROR", "pkcs12 is too short to be accepted as provided.")
    if len(pkcs12) > 10_000_000:
        return _err("VALIDATION_ERROR", "pkcs12 is too large.")
    if not re.fullmatch(r"[A-Za-z0-9\-_+/=]+", pkcs12):
        return _err("VALIDATION_ERROR", "pkcs12 must be a base64/base64url-encoded string.")
    # Ensure decodable as base64 (len not necessarily multiple of 4; pad as needed)
    try:
        s = pkcs12.replace("-", "+").replace("_", "/")
        pad = "=" * ((4 - (len(s) % 4)) % 4)
        base64.b64decode(s + pad, validate=False)
    except Exception:
        return _err("VALIDATION_ERROR", "pkcs12 cannot be decoded as base64/base64url as provided.")

    gmail_accounts = _load("gmail_accounts.json")
    if not isinstance(gmail_accounts, list):
        return _err("CONFLICT", "Datastore corrupted: gmail_accounts is not a list.")
    acct = None
    for a in gmail_accounts:
        if isinstance(a, dict) and a.get("status") in ("active", "token_expired"):
            acct = a
            break
    if acct is None:
        return _err("UNAUTHORIZED", "No connected Gmail account is available for this operation.")
    if acct.get("status") in ("revoked", "disabled"):
        return _err("UNAUTHORIZED", "Gmail connection is not permitted for mutating operations in current status.", status=acct.get("status"))

    settings = _load("gmail_settings.json")
    if not isinstance(settings, list):
        return _err("CONFLICT", "Datastore corrupted: gmail_settings is not a list.")

    # Ensure send-as alias exists
    send_as_row = None
    for s in settings:
        if not isinstance(s, dict):
            continue
        if s.get("gmail_account_id") != acct.get("id"):
            continue
        if s.get("setting_type") == "send_as" and s.get("provider_key") == sendAsEmail and s.get("status") != "deleted":
            send_as_row = s
            break
    if send_as_row is None:
        return _err("NOT_FOUND", "Send-as alias not found.", sendAsEmail=sendAsEmail)

    # Idempotency: derived from payload (so same insert doesn't create duplicates)
    idem_src = f"insert_smime_info|{acct.get('id')}|{sendAsEmail}|{hashlib.sha256(pkcs12.encode('utf-8')).hexdigest()}|{hashlib.sha256(encryptedKeyPassword.encode('utf-8')).hexdigest()}"
    idem = hashlib.sha256(idem_src.encode("utf-8")).hexdigest()

    op, ops, existed = _record_op(
        acct.get("id"),
        "insert_smime_info",
        {"sendAsEmail": sendAsEmail, "encryptedKeyPassword": encryptedKeyPassword, "pkcs12": "[REDACTED]"},
        related_object_type=None,
        related_gmail_id=sendAsEmail,
        status="queued",
        idempotency_key=idem,
    )

    if existed:
        # Return previously created config if we can find it by stored response or by scanning
        resp = op.get("response")
        if isinstance(resp, dict) and "id" in resp:
            smime_id = resp.get("id")
            for s in settings:
                if isinstance(s, dict) and s.get("gmail_account_id") == acct.get("id") and s.get("setting_type") == "smime_info" and s.get("provider_key") == smime_id and s.get("status") != "deleted":
                    payload = s.get("payload") if isinstance(s.get("payload"), dict) else {}
                    out = dict(payload)
                    out["id"] = s.get("provider_key")
                    out["sendAsEmail"] = sendAsEmail
                    return {"result": out}
        # Fallback: conflict because prior operation exists but we cannot safely replay result
        if op.get("status") in ("queued", "running"):
            return _err("CONFLICT", "An insert operation with the same idempotency key is already in progress.", operation_id=op.get("id"))
        if op.get("status") == "succeeded":
            return _err("CONFLICT", "An insert operation with the same idempotency key already succeeded, but the created object could not be located.", operation_id=op.get("id"))
        return _err("CONFLICT", "A previous insert operation exists for this request and did not succeed.", operation_id=op.get("id"), operation_status=op.get("status"))

    # Create new smime_info settings row
    now = _now()
    smime_provider_id = _gen_id("smime")
    new_row = {
        "id": _gen_id("gst"),
        "gmail_account_id": acct.get("id"),
        "setting_type": "smime_info",
        "provider_key": smime_provider_id,
        "payload": {
            "sendAsEmail": sendAsEmail,
            "encryptedKeyPassword": encryptedKeyPassword,
            "pkcs12": pkcs12,
            "isDefault": False,
        },
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }

    # Enforce unique(gmail_account_id, setting_type, provider_key)
    for s in settings:
        if isinstance(s, dict) and s.get("gmail_account_id") == acct.get("id") and s.get("setting_type") == "smime_info" and s.get("provider_key") == smime_provider_id:
            op["status"] = "failed"
            op["error"] = {"code": "CONFLICT", "message": "Generated S/MIME id collided; retry."}
            op["attempt_count"] = int(op.get("attempt_count") or 0) + 1
            op["finished_at"] = _now()
            op["updated_at"] = _now()
            _save("remote_operations.json", ops)
            return _err("CONFLICT", "Unable to allocate a unique S/MIME id; please retry.")

    settings.append(new_row)

    # Mark operation succeeded and store minimal response (do not persist secrets there)
    op_now = _now()
    op["status"] = "succeeded"
    op["response"] = {"id": smime_provider_id, "sendAsEmail": sendAsEmail, "isDefault": False}
    op["attempt_count"] = int(op.get("attempt_count") or 0) + 1
    op["started_at"] = op.get("started_at") or op_now
    op["finished_at"] = op_now
    op["updated_at"] = op_now

    _save("gmail_settings.json", settings)
    _save("remote_operations.json", ops)

    out = dict(new_row["payload"])
    out["id"] = smime_provider_id
    out["sendAsEmail"] = sendAsEmail
    return {"result": out}

