def set_default_smime_info(sendAsEmail, id, **_extra):
    import json, os, datetime, time, uuid, copy

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0142000" if __import__("os").path.isdir("./environment_mix/0142000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _is_str(x):
        return isinstance(x, str)

    def _validate_required_str(x, name):
        if not _is_str(x) or not x.strip():
            return _err("VALIDATION_ERROR", f"{name} must be a non-empty string", field=name)
        return None

    def _log_remote_op(gmail_account_id, tool_name, request, status, related_object_type=None, related_gmail_id=None, idempotency_key=None, response=None, error=None, attempt_count=1):
        ops = _load("remote_operations.json")
        ts = _now()
        op = {
            "id": _gen_id("op"),
            "gmail_account_id": gmail_account_id,
            "tool_name": tool_name,
            "request": request,
            "idempotency_key": idempotency_key,
            "related_object_type": related_object_type,
            "related_gmail_id": related_gmail_id,
            "response": response,
            "error": error,
            "attempt_count": int(attempt_count),
            "status": status,
            "scheduled_at": None,
            "started_at": ts if status in ("running", "succeeded", "failed", "cancelled") else None,
            "finished_at": ts if status in ("succeeded", "failed", "cancelled") else None,
            "created_at": ts,
            "updated_at": ts,
        }
        ops.append(op)
        _save("remote_operations.json", ops)
        return op

    t0 = time.time()

    # Validate inputs
    e = _validate_required_str(sendAsEmail, "sendAsEmail")
    if e:
        return e
    e = _validate_required_str(id, "id")
    if e:
        return e

    accounts = _load("gmail_accounts.json")
    # Ambient auth: pick any account that can serve mutating call (must be active or token_expired; not revoked/disabled)
    acct = None
    for a in accounts:
        if a.get("status") not in ("revoked", "disabled"):
            acct = a
            break
    if not acct:
        return _err("UNAUTHORIZED", "No connected Gmail account available for this operation")

    if acct.get("status") in ("revoked", "disabled"):
        return _err("UNAUTHORIZED", "Mailbox access is not permitted with the stored credentials", account_status=acct.get("status"))

    settings = _load("gmail_settings.json")

    # Find send_as alias
    send_as_row = None
    for s in settings:
        if s.get("gmail_account_id") == acct.get("id") and s.get("setting_type") == "send_as" and s.get("provider_key") == sendAsEmail and s.get("status") != "deleted":
            send_as_row = s
            break
    if not send_as_row:
        _log_remote_op(acct.get("id"), "set_default_smime_info", {"sendAsEmail": sendAsEmail, "id": id}, "failed",
                       related_object_type=None, related_gmail_id=sendAsEmail, error={"code": "NOT_FOUND", "message": "Send-as alias not found"})
        return _err("NOT_FOUND", "Send-as alias not found", sendAsEmail=sendAsEmail)

    # Find requested smime config by provider_key=id
    target = None
    for s in settings:
        if s.get("gmail_account_id") == acct.get("id") and s.get("setting_type") == "smime_info" and s.get("provider_key") == id and s.get("status") != "deleted":
            target = s
            break
    if not target:
        _log_remote_op(acct.get("id"), "set_default_smime_info", {"sendAsEmail": sendAsEmail, "id": id}, "failed",
                       related_object_type=None, related_gmail_id=id, error={"code": "NOT_FOUND", "message": "S/MIME configuration not found"})
        return _err("NOT_FOUND", "S/MIME configuration not found", id=id)

    target_payload = target.get("payload")
    if not isinstance(target_payload, dict):
        _log_remote_op(acct.get("id"), "set_default_smime_info", {"sendAsEmail": sendAsEmail, "id": id}, "failed",
                       related_object_type=None, related_gmail_id=id, error={"code": "CONFLICT", "message": "S/MIME configuration payload is invalid"})
        return _err("CONFLICT", "S/MIME configuration payload is invalid", id=id)

    if target_payload.get("sendAsEmail") != sendAsEmail:
        _log_remote_op(acct.get("id"), "set_default_smime_info", {"sendAsEmail": sendAsEmail, "id": id}, "failed",
                       related_object_type=None, related_gmail_id=id, error={"code": "CONFLICT", "message": "S/MIME configuration does not belong to the specified send-as alias"})
        return _err("CONFLICT", "S/MIME configuration does not belong to the specified send-as alias", sendAsEmail=sendAsEmail, id=id)

    # Mutating tool: create remote op (queued->running->succeeded/failed)
    _log_remote_op(acct.get("id"), "set_default_smime_info", {"sendAsEmail": sendAsEmail, "id": id}, "queued",
                   related_object_type=None, related_gmail_id=sendAsEmail)

    # Apply single-default invariant among smime_info for same sendAsEmail in payload
    ts = _now()
    changed = False
    for s in settings:
        if s.get("gmail_account_id") != acct.get("id") or s.get("setting_type") != "smime_info" or s.get("status") == "deleted":
            continue
        p = s.get("payload")
        if not isinstance(p, dict) or p.get("sendAsEmail") != sendAsEmail:
            continue
        is_target = (s.get("provider_key") == id)
        desired = True if is_target else False
        if p.get("isDefault") is not desired:
            p2 = copy.deepcopy(p)
            p2["isDefault"] = desired
            s["payload"] = p2
            s["updated_at"] = ts
            if is_target and s.get("status") != "active":
                # allow pending_verification/disabled to still be default? rule says "must set exactly one default";
                # reject if cannot be made default due to lifecycle.
                _log_remote_op(acct.get("id"), "set_default_smime_info", {"sendAsEmail": sendAsEmail, "id": id}, "failed",
                               related_object_type=None, related_gmail_id=id,
                               error={"code": "CONFLICT", "message": "S/MIME configuration is not active and cannot be made default"})
                return _err("CONFLICT", "S/MIME configuration is not active and cannot be made default", status=s.get("status"))
            changed = True

    if not changed:
        # Idempotent success: already default and others already unset; still record succeeded op.
        pass

    _save("gmail_settings.json", settings)

    # Fetch updated state for alias: send_as row plus smime_info rows for that alias
    send_as_out = None
    smime_out = []
    for s in settings:
        if s.get("gmail_account_id") != acct.get("id") or s.get("status") == "deleted":
            continue
        if s.get("setting_type") == "send_as" and s.get("provider_key") == sendAsEmail:
            send_as_out = s
        elif s.get("setting_type") == "smime_info":
            p = s.get("payload")
            if isinstance(p, dict) and p.get("sendAsEmail") == sendAsEmail:
                smime_out.append(s)

    _log_remote_op(acct.get("id"), "set_default_smime_info", {"sendAsEmail": sendAsEmail, "id": id}, "succeeded",
                   related_object_type=None, related_gmail_id=sendAsEmail,
                   response={"sendAs": {"id": send_as_out.get("id") if isinstance(send_as_out, dict) else None},
                             "smimeInfoCount": len(smime_out)})

    return {
        "gmailAccountId": acct.get("id"),
        "sendAsEmail": sendAsEmail,
        "sendAs": send_as_out,
        "smimeInfo": smime_out,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def get_profile(includeTotals=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0142000" if __import__("os").path.isdir("./environment_mix/0142000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_remote_op(gmail_account_id, tool_name, request, status, response=None, error=None):
        ops = _load("remote_operations.json")
        ts = _now()
        ops.append({
            "id": f"op_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
            "gmail_account_id": gmail_account_id,
            "tool_name": tool_name,
            "request": request,
            "idempotency_key": None,
            "related_object_type": None,
            "related_gmail_id": None,
            "response": response,
            "error": error,
            "attempt_count": 1,
            "status": status,
            "scheduled_at": None,
            "started_at": ts,
            "finished_at": ts,
            "created_at": ts,
            "updated_at": ts,
        })
        _save("remote_operations.json", ops)

    t0 = time.time()

    if includeTotals is None:
        includeTotals = False
    if not isinstance(includeTotals, bool):
        return _err("VALIDATION_ERROR", "includeTotals must be a boolean", field="includeTotals")

    accounts = _load("gmail_accounts.json")

    # Ambient auth: find any connected account (active/token_expired/disabled/revoked exist),
    # but this endpoint requires access permitted; treat revoked/disabled as forbidden for reads.
    acct = None
    for a in accounts:
        if a.get("status") in ("active", "token_expired"):
            acct = a
            break
    if not acct:
        # If only revoked/disabled exist, still "no connected account" for access.
        return _err("UNAUTHORIZED", "The user has no connected Gmail account")

    # "FORBIDDEN if access ... not permitted with stored credentials"
    # Use status to model; token_expired still permitted for cached profile read.
    if acct.get("status") in ("revoked", "disabled"):
        _log_remote_op(acct.get("id"), "get_profile", {"includeTotals": includeTotals}, "failed",
                       error={"code": "UNAUTHORIZED", "message": "Mailbox access is not permitted with the stored credentials"})
        return _err("UNAUTHORIZED", "Mailbox access is not permitted with the stored credentials", account_status=acct.get("status"))

    # NOT_FOUND if no cached profile exists yet: require primary_email and google_user_id present and created_at exists.
    if not acct.get("primary_email") or not acct.get("google_user_id"):
        _log_remote_op(acct.get("id"), "get_profile", {"includeTotals": includeTotals}, "failed",
                       error={"code": "NOT_FOUND", "message": "No cached profile exists yet"})
        return _err("NOT_FOUND", "No cached profile exists yet")

    profile = {
        "emailAddress": acct.get("primary_email"),
        "googleUserId": acct.get("google_user_id"),
        "historyId": acct.get("history_id"),
        "lastSyncAt": acct.get("last_sync_at"),
        "status": acct.get("status"),
        "updatedAt": acct.get("updated_at"),
        "createdAt": acct.get("created_at"),
    }
    if includeTotals:
        # only include totals if available (non-null)
        if acct.get("messages_total") is not None:
            profile["messagesTotal"] = acct.get("messages_total")
        if acct.get("threads_total") is not None:
            profile["threadsTotal"] = acct.get("threads_total")

    _log_remote_op(acct.get("id"), "get_profile", {"includeTotals": includeTotals}, "succeeded",
                   response={"hasTotals": includeTotals, "hasHistoryId": acct.get("history_id") is not None})

    return {"gmailAccountId": acct.get("id"), "profile": profile, "latency_ms": int((time.time() - t0) * 1000)}

def watch_mailbox(topicName, labelIds=None, labelFilterAction=None, **_extra):
    import json, os, datetime, time, uuid, copy

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0142000" if __import__("os").path.isdir("./environment_mix/0142000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log_remote_op(gmail_account_id, tool_name, request, status, related_gmail_id=None, response=None, error=None, idempotency_key=None, attempt_count=1):
        ops = _load("remote_operations.json")
        ts = _now()
        op = {
            "id": _gen_id("op"),
            "gmail_account_id": gmail_account_id,
            "tool_name": tool_name,
            "request": request,
            "idempotency_key": idempotency_key,
            "related_object_type": None,
            "related_gmail_id": related_gmail_id,
            "response": response,
            "error": error,
            "attempt_count": int(attempt_count),
            "status": status,
            "scheduled_at": None,
            "started_at": ts if status in ("running", "succeeded", "failed", "cancelled") else None,
            "finished_at": ts if status in ("succeeded", "failed", "cancelled") else None,
            "created_at": ts,
            "updated_at": ts,
        }
        ops.append(op)
        _save("remote_operations.json", ops)
        return op

    t0 = time.time()

    if not isinstance(topicName, str) or not topicName.strip():
        return _err("VALIDATION_ERROR", "topicName must be a non-empty string", field="topicName")

    if labelIds is not None:
        if not isinstance(labelIds, list) or any(not isinstance(x, str) or not x for x in labelIds):
            return _err("VALIDATION_ERROR", "labelIds must be an array of non-empty strings", field="labelIds")
    else:
        labelIds = None

    if labelFilterAction is not None:
        if labelFilterAction not in ("include", "exclude"):
            return _err("VALIDATION_ERROR", "labelFilterAction must be 'include' or 'exclude'", field="labelFilterAction")
        if not labelIds:
            return _err("VALIDATION_ERROR", "labelFilterAction requires non-empty labelIds", field="labelFilterAction")

    accounts = _load("gmail_accounts.json")
    acct = None
    for a in accounts:
        if a.get("status") not in ("revoked", "disabled"):
            acct = a
            break
    if not acct:
        return _err("UNAUTHORIZED", "No connected Gmail account available for this operation")

    if acct.get("status") in ("revoked", "disabled"):
        return _err("UNAUTHORIZED", "Mailbox access is not permitted with the stored credentials", account_status=acct.get("status"))

    # Mutating tools MUST be rejected if revoked/disabled (covered above)
    # Validate labelIds exist and active if provided
    if labelIds:
        labels = _load("labels.json")
        active_ids = set()
        for l in labels:
            if l.get("gmail_account_id") == acct.get("id") and l.get("status") == "active":
                active_ids.add(l.get("gmail_label_id"))
        missing = [x for x in labelIds if x not in active_ids]
        if missing:
            return _err("VALIDATION_ERROR", "One or more labelIds do not exist or are not active for this account", missingLabelIds=missing)

    request_obj = {"topicName": topicName, "labelIds": labelIds, "labelFilterAction": labelFilterAction}
    _log_remote_op(acct.get("id"), "watch_mailbox", request_obj, "queued", related_gmail_id=topicName)

    settings = _load("gmail_settings.json")
    ts = _now()

    # Upsert watch singleton
    watch_row = None
    for s in settings:
        if s.get("gmail_account_id") == acct.get("id") and s.get("setting_type") == "watch" and s.get("provider_key") == "singleton":
            watch_row = s
            break

    payload = {
        "topicName": topicName,
        "labelIds": labelIds if labelIds is not None else None,
        "labelFilterAction": labelFilterAction if labelFilterAction is not None else None,
        # best-effort cached watch metadata; no real Gmail call here
        "historyId": acct.get("history_id"),
        "expiration": None,
    }

    if watch_row is None:
        watch_row = {
            "id": _gen_id("set"),
            "gmail_account_id": acct.get("id"),
            "setting_type": "watch",
            "provider_key": "singleton",
            "payload": payload,
            "status": "active",
            "created_at": ts,
            "updated_at": ts,
        }
        settings.append(watch_row)
        _save("gmail_settings.json", settings)
    else:
        # lifecycle: if deleted, cannot transition; if disabled, can go active; if active/pending_verification, allow active update
        cur = watch_row.get("status")
        if cur == "deleted":
            _log_remote_op(acct.get("id"), "watch_mailbox", request_obj, "failed", related_gmail_id=topicName,
                           error={"code": "INVALID_TRANSITION", "message": "Watch is deleted and cannot be re-enabled"})
            return _err("INVALID_TRANSITION", "Watch is deleted and cannot be re-enabled")
        watch_row["payload"] = copy.deepcopy(payload)
        if cur in ("disabled", "pending_verification"):
            watch_row["status"] = "active"
        watch_row["updated_at"] = ts
        _save("gmail_settings.json", settings)

    _log_remote_op(acct.get("id"), "watch_mailbox", request_obj, "succeeded", related_gmail_id=topicName,
                   response={"watchSettingId": watch_row.get("id"), "status": watch_row.get("status")})

    return {"gmailAccountId": acct.get("id"), "watch": watch_row, "latency_ms": int((time.time() - t0) * 1000)}

def stop_mail_watch(idempotencyKey=None, **_extra):
    import json, os, datetime, time, uuid, copy

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0142000" if __import__("os").path.isdir("./environment_mix/0142000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log_remote_op(gmail_account_id, tool_name, request, status, related_gmail_id=None, response=None, error=None, idempotency_key=None, attempt_count=1):
        ops = _load("remote_operations.json")
        ts = _now()
        op = {
            "id": _gen_id("op"),
            "gmail_account_id": gmail_account_id,
            "tool_name": tool_name,
            "request": request,
            "idempotency_key": idempotency_key,
            "related_object_type": None,
            "related_gmail_id": related_gmail_id,
            "response": response,
            "error": error,
            "attempt_count": int(attempt_count),
            "status": status,
            "scheduled_at": None,
            "started_at": ts if status in ("running", "succeeded", "failed", "cancelled") else None,
            "finished_at": ts if status in ("succeeded", "failed", "cancelled") else None,
            "created_at": ts,
            "updated_at": ts,
        }
        ops.append(op)
        _save("remote_operations.json", ops)
        return op

    t0 = time.time()

    if idempotencyKey is not None and (not isinstance(idempotencyKey, str) or not idempotencyKey.strip()):
        return _err("VALIDATION_ERROR", "idempotencyKey must be a non-empty string when provided", field="idempotencyKey")

    accounts = _load("gmail_accounts.json")
    acct = None
    for a in accounts:
        if a.get("status") in ("active", "token_expired", "revoked", "disabled"):
            acct = a
            break
    if not acct:
        return _err("UNAUTHORIZED", "The user has no connected Gmail account")

    if acct.get("status") in ("revoked", "disabled"):
        # Model as not permitted to manage watch with stored credentials.
        _log_remote_op(acct.get("id"), "stop_mail_watch", {"idempotencyKey": idempotencyKey}, "failed",
                       error={"code": "UNAUTHORIZED", "message": "Mailbox access is not permitted with the stored credentials"},
                       idempotency_key=idempotencyKey)
        return _err("UNAUTHORIZED", "Mailbox access is not permitted with the stored credentials", account_status=acct.get("status"))

    # Idempotency: if an operation with same idempotency_key exists for this account, return its resulting watch state
    if idempotencyKey:
        ops = _load("remote_operations.json")
        for op in ops:
            if op.get("gmail_account_id") == acct.get("id") and op.get("idempotency_key") == idempotencyKey and op.get("tool_name") == "stop_mail_watch":
                # Return current cached watch state (may already be disabled)
                settings = _load("gmail_settings.json")
                watch_row = None
                for s in settings:
                    if s.get("gmail_account_id") == acct.get("id") and s.get("setting_type") == "watch" and s.get("provider_key") == "singleton":
                        watch_row = s
                        break
                return {
                    "gmailAccountId": acct.get("id"),
                    "watch": watch_row,
                    "idempotencyKey": idempotencyKey,
                    "operationStatus": op.get("status"),
                    "latency_ms": int((time.time() - t0) * 1000),
                }

    settings = _load("gmail_settings.json")
    watch_row = None
    for s in settings:
        if s.get("gmail_account_id") == acct.get("id") and s.get("setting_type") == "watch" and s.get("provider_key") == "singleton":
            watch_row = s
            break

    if not watch_row or watch_row.get("status") in ("disabled", "deleted"):
        # If no active watch to stop: NOT_FOUND unless idempotencyKey (handled above)
        _log_remote_op(acct.get("id"), "stop_mail_watch", {"idempotencyKey": idempotencyKey}, "failed",
                       error={"code": "NOT_FOUND", "message": "No active watch to stop"},
                       idempotency_key=idempotencyKey)
        return _err("NOT_FOUND", "No active watch to stop")

    # Record queued op first (mutating tools requirement); include idempotency key for dedupe
    _log_remote_op(acct.get("id"), "stop_mail_watch", {"idempotencyKey": idempotencyKey}, "queued",
                   related_gmail_id="watch:singleton", idempotency_key=idempotencyKey)

    # Transition to disabled (must be legal)
    cur = watch_row.get("status")
    # lifecycle transitions allow active->disabled and pending_verification->? (not allowed); disabled->...; deleted->...
    if cur == "active":
        watch_row["status"] = "disabled"
        watch_row["updated_at"] = _now()
        # preserve payload, but mark disabled intent
        p = watch_row.get("payload")
        if isinstance(p, dict):
            p2 = copy.deepcopy(p)
            p2["stoppedAt"] = watch_row["updated_at"]
            watch_row["payload"] = p2
        _save("gmail_settings.json", settings)
    elif cur in ("disabled", "deleted"):
        # should have been caught above
        pass
    else:
        _log_remote_op(acct.get("id"), "stop_mail_watch", {"idempotencyKey": idempotencyKey}, "failed",
                       related_gmail_id="watch:singleton",
                       error={"code": "INVALID_TRANSITION", "message": f"Cannot stop watch from status '{cur}'"},
                       idempotency_key=idempotencyKey)
        return _err("INVALID_TRANSITION", f"Cannot stop watch from status '{cur}'", status=cur)

    _log_remote_op(acct.get("id"), "stop_mail_watch", {"idempotencyKey": idempotencyKey}, "succeeded",
                   related_gmail_id="watch:singleton",
                   response={"watchSettingId": watch_row.get("id"), "status": watch_row.get("status")},
                   idempotency_key=idempotencyKey)

    return {
        "gmailAccountId": acct.get("id"),
        "watch": watch_row,
        "idempotencyKey": idempotencyKey,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def list_gmail_accounts(pageSize=None, pageToken=None, status=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0142000" if __import__("os").path.isdir("./environment_mix/0142000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_gmail_accounts"
    ops = _load("remote_operations.json")
    accounts = _load("gmail_accounts.json")

    def _now_iso():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _op_row(status_str, error=None, response=None):
        now = _now_iso()
        return {
            "id": f"op_{int(time.time()*1000)}_{os.getpid()}_{len(ops)+1}",
            "gmail_account_id": "listing",
            "tool_name": endpoint,
            "request": {"pageSize": pageSize, "pageToken": pageToken, "status": status},
            "idempotency_key": None,
            "related_object_type": None,
            "related_gmail_id": None,
            "response": response,
            "error": error,
            "attempt_count": 1,
            "status": status_str,
            "scheduled_at": None,
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        }

    # Validate inputs
    if pageSize is None:
        ps = 100  # server default <= 100
    else:
        if not isinstance(pageSize, int):
            op = _op_row("failed", error={"code": "VALIDATION_ERROR", "message": "pageSize must be an integer."})
            ops.append(op); _save("remote_operations.json", ops)
            return _err("VALIDATION_ERROR", "pageSize must be an integer.")
        if pageSize < 1 or pageSize > 200:
            op = _op_row("failed", error={"code": "VALIDATION_ERROR", "message": "pageSize must be between 1 and 200."})
            ops.append(op); _save("remote_operations.json", ops)
            return _err("VALIDATION_ERROR", "pageSize must be between 1 and 200.")
        ps = pageSize

    if pageToken is not None and (not isinstance(pageToken, str)):
        op = _op_row("failed", error={"code": "VALIDATION_ERROR", "message": "pageToken must be a string."})
        ops.append(op); _save("remote_operations.json", ops)
        return _err("VALIDATION_ERROR", "pageToken must be a string.")

    allowed_status = {"active", "token_expired", "revoked", "disabled"}
    if status is not None:
        if not isinstance(status, str):
            op = _op_row("failed", error={"code": "VALIDATION_ERROR", "message": "status must be a string."})
            ops.append(op); _save("remote_operations.json", ops)
            return _err("VALIDATION_ERROR", "status must be a string.")
        if status not in allowed_status:
            op = _op_row("failed", error={"code": "VALIDATION_ERROR", "message": "Invalid status filter.", "allowed": sorted(list(allowed_status))})
            ops.append(op); _save("remote_operations.json", ops)
            return _err("VALIDATION_ERROR", "Invalid status filter.", allowed=sorted(list(allowed_status)))

    # Decode pageToken as base64url JSON: {"offset": int}
    offset = 0
    if pageToken:
        try:
            padded = pageToken + "=" * (-len(pageToken) % 4)
            raw = base64.urlsafe_b64decode(padded.encode("utf-8")).decode("utf-8")
            tok = json.loads(raw)
            if not isinstance(tok, dict) or not isinstance(tok.get("offset"), int) or tok["offset"] < 0:
                raise ValueError("bad token")
            offset = tok["offset"]
        except Exception:
            op = _op_row("failed", error={"code": "VALIDATION_ERROR", "message": "Invalid pageToken."})
            ops.append(op); _save("remote_operations.json", ops)
            return _err("VALIDATION_ERROR", "Invalid pageToken.")

    # Filter + stable sort
    rows = [a for a in accounts if isinstance(a, dict)]
    if status is not None:
        rows = [a for a in rows if a.get("status") == status]
    rows.sort(key=lambda r: (str(r.get("created_at") or ""), str(r.get("id") or "")))

    total = len(rows)
    page = rows[offset: offset + ps]
    next_offset = offset + len(page)
    next_token = None
    if next_offset < total:
        tok = {"offset": next_offset}
        next_token = base64.urlsafe_b64encode(json.dumps(tok, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "gmailAccounts": page,
        "nextPageToken": next_token,
        "totalSize": total
    }

    op = _op_row("succeeded", response={"status": "ok", "latency_ms": int((time.time() - t0) * 1000), "returned": len(page), "total": total})
    ops.append(op); _save("remote_operations.json", ops)
    return resp

def update_gmail_account(gmailAccountId, status=None, oauth_access_token=None, oauth_refresh_token=None, oauth_token_expiry=None, scopes=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0142000" if __import__("os").path.isdir("./environment_mix/0142000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_gmail_account"
    ops = _load("remote_operations.json")
    accounts = _load("gmail_accounts.json")

    def _now_iso():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        # Accept "Z" or offset. Return ISO Z string.
        if not isinstance(s, str) or not s.strip():
            return None, "oauth_token_expiry must be a non-empty RFC3339 string."
        v = s.strip()
        try:
            if v.endswith("Z"):
                dt = datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
            else:
                dt = datetime.datetime.fromisoformat(v)
            if dt.tzinfo is None:
                return None, "oauth_token_expiry must include timezone (e.g., Z)."
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z"), None
        except ValueError:
            return None, "oauth_token_expiry must be a valid RFC3339 timestamp."

    def _make_op(status_str, request_obj, error=None, response=None, idem_key=None):
        now = _now_iso()
        return {
            "id": f"op_{int(time.time()*1000)}_{os.getpid()}_{len(ops)+1}",
            "gmail_account_id": gmailAccountId if isinstance(gmailAccountId, str) else "unknown",
            "tool_name": endpoint,
            "request": request_obj,
            "idempotency_key": idem_key,
            "related_object_type": None,
            "related_gmail_id": gmailAccountId if isinstance(gmailAccountId, str) else None,
            "response": response,
            "error": error,
            "attempt_count": 1,
            "status": status_str,
            "scheduled_at": None,
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        }

    # Validate required id
    if not isinstance(gmailAccountId, str) or not gmailAccountId.strip():
        op = _make_op("failed", {"gmailAccountId": gmailAccountId}, error={"code": "VALIDATION_ERROR", "message": "gmailAccountId must be a non-empty string."})
        ops.append(op); _save("remote_operations.json", ops)
        return _err("VALIDATION_ERROR", "gmailAccountId must be a non-empty string.")

    # Find account
    idx = None
    for i, a in enumerate(accounts):
        if isinstance(a, dict) and a.get("id") == gmailAccountId:
            idx = i
            break
    if idx is None:
        op = _make_op("failed", {"gmailAccountId": gmailAccountId}, error={"code": "NOT_FOUND", "message": "Gmail account not found."})
        ops.append(op); _save("remote_operations.json", ops)
        return _err("NOT_FOUND", "Gmail account not found.")

    acct = accounts[idx]
    current_status = acct.get("status")
    allowed_status = {"active", "token_expired", "revoked", "disabled"}
    if current_status not in allowed_status:
        op = _make_op("failed", {"gmailAccountId": gmailAccountId}, error={"code": "CONFLICT", "message": "Account row has invalid stored status.", "status": current_status})
        ops.append(op); _save("remote_operations.json", ops)
        return _err("CONFLICT", "Account row has invalid stored status.", status=current_status)

    # Mutating tools rejected when revoked/disabled unless transitioning disabled->active
    requested_status = status
    if requested_status is not None:
        if not isinstance(requested_status, str) or requested_status not in allowed_status:
            op = _make_op("failed", {"gmailAccountId": gmailAccountId, "status": status}, error={"code": "VALIDATION_ERROR", "message": "Invalid status.", "allowed": sorted(list(allowed_status))})
            ops.append(op); _save("remote_operations.json", ops)
            return _err("VALIDATION_ERROR", "Invalid status.", allowed=sorted(list(allowed_status)))

    # Validate other fields types
    if oauth_access_token is not None and not isinstance(oauth_access_token, str):
        op = _make_op("failed", {"gmailAccountId": gmailAccountId}, error={"code": "VALIDATION_ERROR", "message": "oauth_access_token must be a string."})
        ops.append(op); _save("remote_operations.json", ops)
        return _err("VALIDATION_ERROR", "oauth_access_token must be a string.")
    if oauth_refresh_token is not None and not isinstance(oauth_refresh_token, str):
        op = _make_op("failed", {"gmailAccountId": gmailAccountId}, error={"code": "VALIDATION_ERROR", "message": "oauth_refresh_token must be a string."})
        ops.append(op); _save("remote_operations.json", ops)
        return _err("VALIDATION_ERROR", "oauth_refresh_token must be a string.")
    expiry_iso = None
    if oauth_token_expiry is not None:
        expiry_iso, e = _parse_rfc3339(oauth_token_expiry)
        if e:
            op = _make_op("failed", {"gmailAccountId": gmailAccountId, "oauth_token_expiry": oauth_token_expiry}, error={"code": "VALIDATION_ERROR", "message": e})
            ops.append(op); _save("remote_operations.json", ops)
            return _err("VALIDATION_ERROR", e)
    if scopes is not None:
        if not isinstance(scopes, list) or any(not isinstance(x, str) for x in scopes):
            op = _make_op("failed", {"gmailAccountId": gmailAccountId, "scopes": scopes}, error={"code": "VALIDATION_ERROR", "message": "scopes must be an array of strings."})
            ops.append(op); _save("remote_operations.json", ops)
            return _err("VALIDATION_ERROR", "scopes must be an array of strings.")

    # Determine whether this is allowed given current status
    transitions = {
        "active": {"token_expired", "revoked", "disabled"},
        "token_expired": {"active", "revoked", "disabled"},
        "revoked": {"disabled"},
        "disabled": {"active"},
    }

    # If account is revoked: all mutating updates rejected (no transition except revoked->disabled allowed)
    # If account is disabled: only allow disabled->active transition; otherwise reject.
    if current_status in ("revoked", "disabled"):
        if not (current_status == "disabled" and requested_status == "active"):
            if not (current_status == "revoked" and requested_status == "disabled"):
                op = _make_op("failed",
                              {"gmailAccountId": gmailAccountId, "status": status, "oauth_access_token": bool(oauth_access_token is not None),
                               "oauth_refresh_token": bool(oauth_refresh_token is not None), "oauth_token_expiry": oauth_token_expiry, "scopes": scopes},
                              error={"code": "UNAUTHORIZED", "message": "Account is not permitted to be mutated in its current status.", "current_status": current_status})
                ops.append(op); _save("remote_operations.json", ops)
                return _err("UNAUTHORIZED", "Account is not permitted to be mutated in its current status.", current_status=current_status)

    # If status is requested, validate lifecycle transition
    if requested_status is not None and requested_status != current_status:
        if requested_status not in transitions.get(current_status, set()):
            op = _make_op("failed", {"gmailAccountId": gmailAccountId, "status": requested_status},
                          error={"code": "INVALID_TRANSITION", "message": "Illegal status transition.", "from": current_status, "to": requested_status})
            ops.append(op); _save("remote_operations.json", ops)
            return _err("INVALID_TRANSITION", "Illegal status transition.", **{"from": current_status, "to": requested_status})

    # Require at least one actual change (NO SUCCESS WITHOUT EFFECT)
    proposed = dict(acct)
    changed = False
    if requested_status is not None and requested_status != proposed.get("status"):
        proposed["status"] = requested_status
        changed = True
    if oauth_access_token is not None and oauth_access_token != proposed.get("oauth_access_token"):
        proposed["oauth_access_token"] = oauth_access_token
        changed = True
    if oauth_refresh_token is not None and oauth_refresh_token != proposed.get("oauth_refresh_token"):
        proposed["oauth_refresh_token"] = oauth_refresh_token
        changed = True
    if oauth_token_expiry is not None and expiry_iso != proposed.get("oauth_token_expiry"):
        proposed["oauth_token_expiry"] = expiry_iso
        changed = True
    if scopes is not None and scopes != proposed.get("scopes"):
        proposed["scopes"] = scopes
        changed = True

    if not changed:
        op = _make_op("failed", {"gmailAccountId": gmailAccountId}, error={"code": "CONFLICT", "message": "No changes to apply."})
        ops.append(op); _save("remote_operations.json", ops)
        return _err("CONFLICT", "No changes to apply.")

    # Enforce uniqueness constraints if relevant fields changed (google_user_id, primary_email not mutable here).
    # Persist updates + audit timestamps
    now = _now_iso()
    proposed["updated_at"] = now
    # created_at required invariant
    if not proposed.get("created_at"):
        proposed["created_at"] = now

    # Create remote operation row for mutating tool
    req_obj = {
        "gmailAccountId": gmailAccountId,
        "status": status,
        "oauth_access_token": oauth_access_token,
        "oauth_refresh_token": oauth_refresh_token,
        "oauth_token_expiry": oauth_token_expiry,
        "scopes": scopes,
    }
    # Derive idempotency key from request (best-effort stable): endpoint + accountId + fields present + values
    # (kept short-ish; uniqueness enforced per gmail_account_id when not null)
    idem_material = json.dumps({"t": endpoint, "a": gmailAccountId, "s": status, "exp": expiry_iso, "sc": scopes,
                               "has_at": oauth_access_token is not None, "has_rt": oauth_refresh_token is not None},
                              sort_keys=True, separators=(",", ":"))
    idem_key = f"idem_{abs(hash(idem_material))}"

    # If an operation with same idempotency_key already succeeded, do not execute twice (idempotent).
    existing = None
    for o in ops:
        if isinstance(o, dict) and o.get("gmail_account_id") == gmailAccountId and o.get("idempotency_key") == idem_key:
            existing = o
            break
    if existing and existing.get("status") == "succeeded":
        # Still log a retry attempt as a new op? Real backends typically don't create new rows when deduping;
        # but our schema enforces unique(gmail_account_id, idempotency_key), so we must not insert a duplicate.
        # Return current state.
        return {"gmailAccount": acct, "idempotencyKey": idem_key, "deduped": True}

    # If exists but failed/queued, treat as retry: increment attempt_count and update status/time
    if existing:
        existing["attempt_count"] = int(existing.get("attempt_count") or 0) + 1
        existing["status"] = "running"
        existing["started_at"] = now
        existing["updated_at"] = now
        _save("remote_operations.json", ops)
        op_ref = existing
    else:
        op_ref = _make_op("running", req_obj, idem_key=idem_key)
        ops.append(op_ref)
        _save("remote_operations.json", ops)

    # Execute mutation (write-through)
    accounts[idx] = proposed
    _save("gmail_accounts.json", accounts)

    # Mark operation succeeded
    finished = _now_iso()
    op_ref["status"] = "succeeded"
    op_ref["finished_at"] = finished
    op_ref["updated_at"] = finished
    op_ref["response"] = {"status": "ok", "latency_ms": int((time.time() - t0) * 1000)}
    op_ref["error"] = None
    _save("remote_operations.json", ops)

    return {"gmailAccount": proposed, "idempotencyKey": idem_key}
